addonTable.gossip_hashed = addonTable.gossip_hashed or { version = 1, rows = {} }
local rows = {
    [2609500114] = {
        ["english"] = { [1] = "The book tells of dragons uniting against another, more powerful dragon, named Deathwing. From what you can make out, the chromatic dragonflight had almost been unleashed upon the world. The Aspects were prepared.\010" },
        ["text"] = "У книзі розповідається, як дракони об'єдналися проти іншого, значно могутнішого дракона на ім'я Смертокрил. Наскільки можна зрозуміти, хроматичну драконячу зграю ледь не випустили у світ. Аспекти були готові.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2431025489] = {
        ["english"] = { [1] = "Tell me more about these hippogryphs." },
        ["text"] = "Розкажи мені більше про цих гіпогрифів.",
        ["npcs"] = { [1] = 7916 },
        ["roles"] = { ["reply"] = true },
    },
    [1279416999] = {
        ["english"] = { [1] = "The Scarlet Crusade of Tyr's Hand in the Eastern Plaguelands have many lockboxes that will challenge your skill." },
        ["text"] = "Багряний Похід у Десниці Тіра в Східному Чумнозем'ї має безліч замкнених скринь, які випробують твою майстерність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3485665859] = {
        ["english"] = { [1] = "The Shattered Hand's influence dominates these lands. We are the veil which covers Kalimdor: The protectorates, the police, the judges, the jury, and ultimately, the executioners. We see all, we know all.$B$BYou have grown much in the time which you have spent in service of the Hand, $N. The time has come to send you into the field.$B$BAre you prepared to undertake your next mission?$B" },
        ["text"] = "Вплив Розтрощеної Десниці панує на цих землях. Ми — завіса, що вкриває Калімдор: захисники, варта, судді, присяжні й, зрештою, кати. Ми бачимо все, знаємо все.$B$BЗа час служби Десниці ти значно виріс, $N. Настав час відправити тебе в поле.$B$BГотовий узятися за наступне завдання?$B",
        ["npcs"] = { [1] = 3401 },
        ["roles"] = { ["greeting"] = true },
    },
    [472833675] = {
        ["english"] = { [1] = "There are two mines in Alterac: the Irondeep in Alliance territory and the Coldtooth mine in Horde territory.  Both mines are a rich source of minerals, and in the past were used to store excess supplies.$B$BNow, these mines are constantly fought over by the Horde, the Alliance and local denizens." },
        ["text"] = "В Альтераку є дві копальні: Залізна Глибина на території Альянсу й Кригозуба на території Орди. Обидві багаті на корисні копалини, а раніше в них зберігали надлишкові припаси.$B$BТепер за ці копальні постійно б'ються Орда, Альянс і місцеві мешканці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3595565728] = {
        ["english"] = { [1] = "The monastery was once a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed. \010" },
        ["text"] = "Колись монастир був осередком навчання й просвітництва. Із появою невмерлої Скари під час Третьої війни мирний монастир перетворили на фортецю фанатичного Багряного Походу. Хрестоносці нетерпимі до всіх нелюдських рас, незалежно від союзу чи належності. Вони вважають будь-якого чужинця потенційним носієм чуми невмерлих — і таким, що підлягає знищенню.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2865447560] = {
        ["english"] = { [1] = "There are those that would teach you of Herbalism in the great home of Thunder Bluff away to the north.  Follow the road out of the village to get there and at the base of the bluff ride the elevator to the top of the rise.  There are many Bluffwatchers there who can direct you further." },
        ["text"] = "У великому Громовому Бескиді на півночі є ті, хто навчить тебе травництва. Іди дорогою із селища, а біля підніжжя бескиду піднімись ліфтом нагору. Там багато вартових Бескиду, які вкажуть подальший шлях.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3943644552] = {
        ["english"] = { [1] = "Staves are taught by Hanashi, the troll weapon master in Orgrimmar's Valley of Honor, and Ansekhwa, the tauren weapon master who trains on the lower central rise of Thunder Bluff." },
        ["text"] = "Володінню посохами навчають Ганаші, троль-майстер зброї в Долині Честі Орґріммара, та Ансеква, таурен-майстер зброї, що тренує на нижньому центральному виступі Громового Бескиду.",
        ["npcs"] = { [1] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [1776755620] = {
        ["english"] = { [1] = "Still hungry $G brother:sister;? How can we help?" },
        ["text"] = "Досі голодний, $G брате:сестро;? Чим ми можемо допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3108838704] = {
        ["english"] = { [1] = "That fight was savage and brutal. I haven't seen a grand melee like that in many years! Amazing!" },
        ["text"] = "Бій був диким і жорстоким. Я вже багато років не бачив такої великої січі! Неймовірно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3308298130] = {
        ["english"] = { [1] = "The life of a smith is not an easy one, but it puts steel in yer bones and fire in yer heart. My da' was a smith, my grandfather before him in the forges beneath Grim Batol. And now my son follows in our footsteps, that boy makes me proud." },
        ["text"] = "Життя коваля нелегке, зате воно загартовує сталь у кістках і вогонь у серці. Мій батько був ковалем, а перед ним — мій дід у кузнях під Ґрім-Батолом. Тепер і мій син іде нашими слідами. Я пишаюся хлопцем.",
        ["npcs"] = { [1] = 5511, [2] = 10276 },
        ["roles"] = { ["greeting"] = true },
    },
    [2691312509] = {
        ["english"] = { [1] = "The bear looks at you calmy and patiently, but says nothing." },
        ["text"] = "Ведмідь спокійно й терпляче дивиться на тебе, але нічого не каже.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [2667574818] = {
        ["english"] = { [1] = "The fish off the coast of Teldrassil are quite large and robust.  Rumors say it is the speedy growth of our new world tree that is the cause." },
        ["text"] = "Риба біля узбережжя Тельдрассілу дуже велика й міцна. Кажуть, причина — стрімке зростання нашого нового Світового Дерева.",
        ["npcs"] = { [1] = 10118 },
        ["roles"] = { ["greeting"] = true },
    },
    [2588877476] = {
        ["english"] = { [1] = "There are clams to be collected and orcas to be killed. Help or stay out of the way!" },
        ["text"] = "Треба збирати молюсків і вбивати косаток. Допомагай або не заважай!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [115861932] = {
        ["english"] = { [1] = "The zeppelin should have just departed from Orgrimmar." },
        ["text"] = "Дирижабль щойно мав вирушити з Орґріммара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3453444445] = {
        ["english"] = { [1] = "That's right, um, $g lad : lass;, all of the war materiel is being transported to Silithus and the last of it should get there within $2113w days. After that, we'll all just have to wait and see who puts forth a $g hero : heroine; to reconstitute the Scepter of the Shifting Sands and ring the gong on the Scarab Dais. Only when that occurs will the war begin to open the gates of Ahn'Qiraj." },
        ["text"] = "Саме так, е-е, $g хлопче : дівчино;, усі військові припаси везуть до Силітуса, і останні мають прибути протягом $2113w днів. Після цього нам лишиться чекати, хто висуне $g героя : героїню;, щоб відновити Скіпетр Мінливих Пісків і вдарити в гонг на Помості Скарабея. Лише тоді почнеться війна за відкриття брам Ан'Кіражу.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3081758879] = {
        ["english"] = { [1] = "The spirits of Silithus call out to us, $n.  The land weeps, for it has a woeful story to tell..." },
        ["text"] = "Духи Силітуса кличуть нас, $n. Земля плаче, бо має розповісти скорботну історію...",
        ["npcs"] = { [1] = 15270 },
        ["roles"] = { ["greeting"] = true },
    },
    [470061364] = {
        ["english"] = { [1] = "The vessel of rebirth must be fortified with elementium. I know of only one source of the mineral: the elemental planes, at the core of our world.$B$BThere is one, an Earthshaper, who may know more than I about the acquisition of such things. You must find this Earthshaper!" },
        ["text"] = "Посудину відродження треба зміцнити елементієм. Я знаю лише одне джерело цього мінералу: стихійні плани в самому ядрі нашого світу.$B$BЄ один Землетворець, який може знати про добування такого більше за мене. Ти мусиш знайти цього Землетворця!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3550144550] = {
        ["english"] = { [1] = "The Prince plotted to imprison a demon of immense power behind a grand force field. The pylons would channel latent energies into the field, keeping it operational.$B$BWhile imprisoned, Immol'thar would serve as a battery to the populace of Eldre'Thalas." },
        ["text"] = "Принц задумав ув'язнити демона величезної сили за великим силовим полем. Пілони мали спрямовувати приховану енергію в поле й підтримувати його.$B$BУв'язнений Імол'тар мав слугувати батареєю для населення Елдре'Таласа.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [2553318006] = {
        ["english"] = { [1] = "The body is that of a female orc warrior.$B$BIt is clear that she died in battle, probably against the quilboar in the area." },
        ["text"] = "Це тіло орчихи-воїтельки.$B$BОчевидно, вона загинула в бою, найімовірніше проти місцевих свинобразів.",
        ["npcs"] = { [1] = 10668 },
        ["roles"] = { ["greeting"] = true },
    },
    [1870882892] = {
        ["english"] = { [1] = "Thank the Light the Defias don't know the first thing about diving!" },
        ["text"] = "Хвала Світлу, Непокірні нічого не тямлять у пірнанні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2917503963] = {
        ["english"] = { [1] = "The Headless Horseman lives in the Scarlet Monastery with all the other creepy ghosts and humans." },
        ["text"] = "Вершник без голови живе в Багряному монастирі разом з іншими моторошними привидами й людьми.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [278069848] = {
        ["english"] = { [1] = "This is disheartening. Is there anything I can do to stop this?" },
        ["text"] = "Це гнітить. Я можу якось це зупинити?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [2203201377] = {
        ["english"] = { [1] = "The best miner has a firm grip on $ghis:her; pick, a stout heart in $ghis:her; chest, and thick, black dust in $ghis:her; hair." },
        ["text"] = "У найкращого шахтаря міцна рука на $gсвоїй:своїй; кирці, відважне серце в $gсвоїх:своїх; грудях і густий чорний пил у $gсвоєму:своєму; волоссі.",
        ["npcs"] = { [1] = 1681 },
        ["roles"] = { ["greeting"] = true },
    },
    [1956948910] = {
        ["english"] = { [1] = "Take me to Northpass Tower." },
        ["text"] = "Відвези мене до вежі Північного проходу.",
        ["npcs"] = { [1] = 17209 },
        ["roles"] = { ["reply"] = true },
    },
    [640501361] = {
        ["english"] = { [1] = "This windblossom plant stands out as a beacon of light in the darkness that is Felwood.  Plump and juicy berries hang from the plant, ripe for the picking." },
        ["text"] = "Ця вітроквітка сяє, мов маяк у темряві Сквернолісся. На ній висять пухкі соковиті ягоди, стиглі й готові до збору.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2358749553] = {
        ["english"] = { [1] = "The machine adjusts to face you.$B$BOn the back of the machine is an empty, oddly misshapen slot with an engraving that reads: \"Propirtee o' Cap'n Gelkak Gyromast\"" },
        ["text"] = "Машина повертається до тебе.$B$BНа її задній частині є порожній проріз дивної форми з вигравіюваним написом: «Власніс' капітана Ґелкака Гіромаста».",
        ["npcs"] = { [1] = 6669 },
        ["roles"] = { ["greeting"] = true },
    },
    [3834659277] = {
        ["english"] = { [1] = "The druids are holding a great celebration of Lunar Festival in Moonglade. If that's too far to walk, they're transporting people from the big cities." },
        ["text"] = "Друїди влаштували велике святкування Місячного фестивалю в Місячній галявині. Якщо йти надто далеко, вони перевозять людей із великих міст.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3011268062] = {
        ["english"] = { [1] = "The celebration of the Lunar Festival is in full swing in Moonglade. You can make the trek, or the druids in the Cenarion Enclave are offering transport." },
        ["text"] = "Святкування Місячного фестивалю в самому розпалі в Місячній галявині. Можеш вирушити туди пішки, або скористатися перевезенням, яке пропонують друїди Кенарійського анклаву.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [129010577] = {
        ["english"] = { [1] = "The element of air here is restless. Beware... they will not let you pass unharmed." },
        ["text"] = "Стихія повітря тут неспокійна. Стережися... вони не пропустять тебе неушкодженим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1024570353] = {
        ["english"] = { [1] = "The Sethekk believe themselves to be the true and most loyal followers of the master of all arakkoa. Do not ask about the master, $r, for his mysteries are for the feathered people alone.$B$BThe Sethekk interpreted the destruction of Auchindoun to be the arrival of our master on this planet. They set out for the ruins, taking with them the relics of our greatest hero, Terokk.$B$BThey still seek the master in the temple's ruins, but I came to see through their lies. I am no longer one of them." },
        ["text"] = "Сетекки вважають себе істинними й найвідданішими послідовниками повелителя всіх араккоа. Не питай про господаря, $r, бо його таємниці призначені лише пернатому народові.$B$BСетекки сприйняли руйнування Акіндуна як прибуття нашого господаря на цей світ. Вони вирушили до руїн, забравши із собою реліквії нашого найвеличнішого героя — Терокка.$B$BВони й досі шукають господаря в руїнах храму, але я прозрів і побачив їхню брехню. Я більше не один із них.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3860084926] = {
        ["english"] = { [1] = "The better to hear you with, my child." },
        ["text"] = "Щоб краще тебе чути, дитинко.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1202574402] = {
        ["english"] = { [1] = "The Ethereum have grown dark... twisted. Vengeance has become their only recourse and any that would stand in their way or not join their cause are considered enemies. Many saw that the Ethereum were plummeting into madness and left. Several of the Nexus-Princes of the Ethereum council abandoned the Ethereum to form other groups and factions with different goals. The Consortium are one such example of an off-shoot group. The Protectorate another... " },
        ["text"] = "Ефіріуми стали темними... викривленими. Помста стала їхнім єдиним шляхом, а кожного, хто стає на заваді або не приєднується до їхньої справи, вони вважають ворогом. Багато хто побачив, що Ефіріуми занурюються в божевілля, і пішов. Кілька Принців Нексуса з ради Ефіріумів покинули їх і заснували інші групи та фракції з іншими цілями. Консорціум — один із таких відгалужень. Протекторат — інший... ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3865396346] = {
        ["english"] = { [1] = "The Frostwolf Relief Hut lies in Frostwolf Keep, south of the Frostwolf Towers.$B$BThe Horde controls it." },
        ["text"] = "Хатина допомоги Морозних Вовків розташована у фортеці Морозних Вовків, на південь від їхніх веж.$B$BЇї контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1161180756] = {
        ["english"] = { [1] = "The lunar celebration this year is quite magnificent!" },
        ["text"] = "Цьогорічне святкування Місячного фестивалю просто чудове!",
        ["npcs"] = { [1] = 15905 },
        ["roles"] = { ["greeting"] = true },
    },
    [90625579] = {
        ["english"] = { [1] = "The dishes that Alegorn whips up are to die for.  He's always busy preparing new delicacies over in the Craftsman's Terrace.  Be sure to try his Cenarion Green recipe if he has any left.  \010\010Now, if you don't mind, I must investigate this rash of missing deer. " },
        ["text"] = "Страви, які готує Алеґорн, — пальчики оближеш. Він завжди зайнятий новими смаколиками на Ремісничій терасі. Обов'язково спробуй його «Кенарійську зелень», якщо щось лишилося.  \010\010А тепер, якщо не заперечуєш, мені треба розібратися з цією хвилею зникнень оленів. ",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2771630324] = {
        ["english"] = { [1] = "That hermit Mallory is known to concoct some potions for the local townsfolk on occasion.  He has a cottage in the hills between Stormwind and Northshire." },
        ["text"] = "Відлюдник Меллорі часом варить зілля для місцевих. Його хатина стоїть у пагорбах між Штормовієм і Північнокраєм.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4074048453] = {
        ["english"] = { [1] = "Tharnariun, the trap is lost. Do you have another?" },
        ["text"] = "Тарнаріуне, пастку втрачено. У тебе є інша?",
        ["npcs"] = { [1] = 3701 },
        ["roles"] = { ["reply"] = true },
    },
    [3447472208] = {
        ["english"] = { [1] = "The druids of Azeroth hold a great celebration in the Moonglade. If you find the lunar festival revelers in the city, they can transport you there." },
        ["text"] = "Друїди Азероту влаштовують велике святкування в Місячній галявині. Якщо знайдеш у місті гуляк Місячного фестивалю, вони можуть переправити тебе туди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [975357927] = {
        ["english"] = { [1] = "Strength of the heart is what gives you the resolve to take action... action that is rooted in intents that are pure and forthright.  To keep the balance is not to be complacent or banal.$B$BYou must show resolve for that which you believe in, and you must be willing to fight for it.  The mother bear shows endless conviction in protecting her young, as does an elder bear protecting his den.  It is this resolve, this strength of heart, which you must come to know if you are to master the way of the Claw." },
        ["text"] = "Сила серця дає рішучість діяти... діяти з чистими й щирими намірами. Зберігати рівновагу — не означає бути байдужим чи бездіяльним.$B$BТи мусиш твердо стояти за те, у що віриш, і бути готовим за це боротися. Ведмедиця невтомно захищає своїх ведмежат, а старий ведмідь — своє лігво. Саме цю рішучість, цю силу серця, ти мусиш пізнати, якщо прагнеш опанувати шлях Кігтя.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [1014019144] = {
        ["english"] = { [1] = "The Stonehearth Bunker protects the eastern flank of the Field of Strife.$B$BIt is controlled by the Alliance." },
        ["text"] = "Бункер Кам'яного Вогнища захищає східний фланг Поля Боротьби.$B$BЙого контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [906613352] = {
        ["english"] = { [1] = "The Bash'ir crystalforge can be used to transform your apexis shards into unstable flasks of the sorcerer.  These flasks make the imbiber more intelligent, heartier, and increase the effectiveness of their damaging and healing magics.$B$BMake your choice, below." },
        ["text"] = "Кристалокузня Баш'іру може перетворювати твої апекситові уламки на нестабільні флакони чаклуна. Ці флакони роблять того, хто їх вип'є, розумнішим і витривалішим, а також посилюють його закляття шкоди й зцілення.$B$BОбирай нижче.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1223699364] = {
        ["english"] = { [1] = "The most amazing of the Lunar Festival parties is in Moonglade. Don't walk there, though, the druids in the Valley of Wisdom can transport you." },
        ["text"] = "Найдивовижніша вечірка Місячного фестивалю — в Місячній галявині. Не йди туди пішки: друїди в Долині Мудрості можуть тебе переправити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1005494488] = {
        ["english"] = { [1] = "There's a great cook who works at the Pig and Whistle Tavern in Old Town.  I've watched him use a knife when he cooks and just between you and me, I don't think he's always been a cook.  Don't get me wrong... if you still want to learn, he's the best we have." },
        ["text"] = "У таверні «Свиня й Свисток» у Старому Місті працює чудовий кухар. Я бачив, як він орудує ножем під час готування, і, між нами кажучи, не думаю, що він завжди був кухарем. Не зрозумій неправильно... якщо все ще хочеш навчатися, кращого в нас немає.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4143819110] = {
        ["english"] = { [1] = "Take me to Eastwall Tower." },
        ["text"] = "Відвези мене до вежі Східної стіни.",
        ["npcs"] = { [1] = 17209 },
        ["roles"] = { ["reply"] = true },
    },
    [2178434580] = {
        ["english"] = { [1] = "Teach me how to create and apply a Heavy Runecloth Bandage, Doctor.", [2] = "Teach me how to create and apply a Heavy Runecloth Bandage, Doctor.\010" },
        ["text"] = "Навчіть мене виготовляти й накладати щільний бинт із рунічної тканини, лікарю.",
        ["npcs"] = { [1] = 12939 },
        ["roles"] = { ["reply"] = true },
    },
    [2222495716] = {
        ["english"] = { [1] = "The Forsaken weapon master Archibald knows his way around the polearm. He trains others in the War Quarter of the Undercity." },
        ["text"] = "Майстер зброї Відречених Арчібальд добре знається на древковій зброї. Він навчає у Військовому кварталі Підмістя.",
        ["npcs"] = { [1] = 11868, [2] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [3440792030] = {
        ["english"] = { [1] = "The tag on this present reads: \"For ages 10 and up.\"" },
        ["text"] = "На бирці цього подарунка написано: «Для дітей від 10 років».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [566538067] = {
        ["english"] = { [1] = "Throm'ka, Horde $C, stand proud! I am Warlord Gorchuk, commander of the Horde's war effort. There are trying times ahead of us, but we shall prevail, as always.$B$BIf you have questions, you should ask them." },
        ["text"] = "Тром’ка, ординський $C, тримайтеся гордо! Я — воєвода Ґорчук, командувач воєнними зусиллями Орди. Попереду важкі часи, але ми переможемо, як завжди.$B$BЯкщо маєте запитання — ставте їх.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [1189871833] = {
        ["english"] = { [1] = "Take every word I say and commit it to memory. Until our enemies have been eradicated, we must never shirk a chance to further our knowledge. Reinforce your armor, and never relax your guard." },
        ["text"] = "Запам'ятовуй кожне моє слово. Допоки наших ворогів не винищено, ми не маємо права втрачати жодної нагоди примножити знання. Зміцнюй обладунок і ніколи не послаблюй пильності.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3406553246] = {
        ["english"] = { [1] = "The battle goes well. The Scourge forces seem weakened. I believe it will only be a matter of time before we drive them from our shores. I will turn my magics to you, to aid in this struggle." },
        ["text"] = "Битва йде добре. Сили Скари, схоже, ослабли. Думаю, це лише питання часу, коли ми виженемо їх із наших берегів. Я зверну свою магію на тебе, щоб допомогти в цій боротьбі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2048477912] = {
        ["english"] = { [1] = "Throm'ka, $n.  Warsong Gulch is in need of heroes such as you." },
        ["text"] = "Тром’ка, $n. Ущелина Пісні Війни потребує таких героїв, як ви.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [598074520] = {
        ["english"] = { [1] = "There you are!" },
        ["text"] = "Ось ти де!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3843661712] = {
        ["english"] = { [1] = "The Headless Horseman is attacking!  Quickly, aid your Horde brethren in the village's defense!" },
        ["text"] = "Вершник без голови атакує! Швидше, допоможи братам Орди захистити селище!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2080067001] = {
        ["english"] = { [1] = "This kodo sure looks nothing like the beast I originally lured!  I wonder if the kombobulator can be used on me." },
        ["text"] = "Цей кодо геть не схожий на звіра, якого я спочатку приманив! Цікаво, чи можна застосувати комбобулятор до мене.",
        ["npcs"] = { [1] = 11627 },
        ["roles"] = { ["greeting"] = true },
    },
    [3334975987] = {
        ["english"] = { [1] = "Sun's Reach is ours.  Kael's dogs are on the run... it is time to put them out of their misery!" },
        ["text"] = "Сонячний Край наш. Пси Келя тікають... час покласти край їхнім стражданням!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3583499516] = {
        ["english"] = { [1] = "The Pool of Tears in the Swamp of Sorrows holds ancient locked boxes that were lost in another age." },
        ["text"] = "У Басейні Сліз у Болоті Скорботи лежать стародавні замкнені скрині, загублені ще в іншу епоху.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [777492566] = {
        ["english"] = { [1] = "They fear my words. They make an example out of me. A mockery of the one true god, Neptulon.$B$B<Skar'this spits.>$B$BRetribution comesss, mortal. The glorious hand of the Tidehunter will one day sweep through the non-believers like a scythe against a new harvest." },
        ["text"] = "Вони бояться моїх слів. Роблять із мене показовий приклад. Глузують із єдиного істинного бога — Нептулона.$B$B<Скар'тіс плює.>$B$BВідплата прийдессс, смертний. Славетна рука Мисливця Припливів одного дня пройде крізь невірних, наче коса крізь молодий врожай.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [49449856] = {
        ["english"] = { [1] = "The power of Elune compels you!  The power of Elune compels you!  \010\010Go now!  Seek out Jandria in the central hall of the Temple of the Moon in the southern section of Darnassus!" },
        ["text"] = "Сила Елуни наказує тобі! Сила Елуни наказує тобі!  \010\010Іди! Знайди Джандрію в центральній залі Храму Місяця в південній частині Дарнаса!",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3955072556] = {
        ["english"] = { [1] = "The duty of a clan mother is to listen. To listen to the wind and the water and the fire and the earth. To gather information for her clan in the way others gather furs to stay warm. It is the spirits that I commune with... In my dreams, Mother Kashur speaks to me like the spirits that spoke to her once... When I pass, I will speak to Drakia and Celestine in this manner.$B$B<Greatmother Geyah smiles.>" },
        ["text"] = "Обов'язок матері клану — слухати. Слухати вітер, воду, вогонь і землю. Збирати для клану знання так само, як інші збирають хутро, щоб зігрітися. Я спілкуюся з духами... У моїх снах Матір Кашур говорить зі мною, як колись духи говорили з нею... Коли я піду, так само говоритиму до Дракії й Селестини.$B$B<Праматір Ґейя усміхається.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1272752235] = {
        ["english"] = { [1] = "The Hall of Spirits is where our shamans call home.  You can find it on the Spirit Rise.  May your ancestors watch over you." },
        ["text"] = "Зала Духів — оселя наших шаманів. Знайдеш її на Висоті Духів. Нехай предки оберігають тебе.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [35853166] = {
        ["english"] = { [1] = "That no good kiss-up is probably practicing ballet in his chambers." },
        ["text"] = "Цей підлиза, мабуть, зараз тренується в балеті у своїх покоях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [243614237] = {
        ["english"] = { [1] = "The gryphon riders are standing 10 paces from us, friend. They'll be giving you a ride to Thorson's Post. Get going!" },
        ["text"] = "Вершники на грифонах стоять за десять кроків від нас, друже. Вони відвезуть тебе до застави Торсона. Рушай!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3941022678] = {
        ["english"] = { [1] = "Sure ye don't want to be a Blacksmith?  Well, if yer heart is set on Leatherworking, then you best talk to Fimble Finespindle over at his shop on the northwest side of The Great Forge." },
        ["text"] = "Точно не хочеш стати ковалем? Ну, якщо вже так припало до душі шкірництво, поговори з Фімблом Тонковеретеном у його крамниці на північному заході Великої Кузні.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2337041542] = {
        ["english"] = { [1] = "They say that I am blessed: A herald to harken in a new age." },
        ["text"] = "Кажуть, я благословенний: провісник нової епохи.",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["greeting"] = true },
    },
    [1068912662] = {
        ["english"] = { [1] = "Throm'ka, $c. You must be new. You look fresh and unspoiled by the horrors of this land.$B$B<Sergeant Shatterskull spits into the dust.>$B$BThat'll change." },
        ["text"] = "Тром’ка, $c. Ви, мабуть, новенький. Виглядаєте свіжим і ще не зіпсованим жахами цих земель.$B$B<Сержант Розтрощений Череп спльовує в пил.>$B$BЦе зміниться.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2797006896] = {
        ["english"] = { [1] = "The battlemaster" },
        ["text"] = "Воєначальник поля бою",
        ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [137918905] = {
        ["english"] = { [1] = "That kind of magic is just bad news, I tell ye.  I don't know why that Grimrizz has been allowed to set up outside the Thunderbrew Distillery of all places!  You stay away from him, you here!" },
        ["text"] = "Така магія — до добра не доведе, кажу тобі. Не знаю, хто взагалі дозволив Ґрімріззу влаштуватися просто біля гуральні Громовара! Тримайся від нього подалі, чуєш!",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1223842613] = {
        ["english"] = { [1] = "Tell me a story, Skorn." },
        ["text"] = "Розкажи мені історію, Скорне.",
        ["npcs"] = { [1] = 3052 },
        ["roles"] = { ["reply"] = true },
    },
    [2548568280] = {
        ["english"] = { [1] = "This dock here?  Well you can catch the ship that goes to that Night Elf place.  What's it's name?  Uhh Auberdine I think.  I don't really know for sure, I just load and unload stuff." },
        ["text"] = "Оцей причал? Ну, звідси можна сісти на корабель до того місця нічних ельфів. Як воно зветься? Е-е, Аубердін, здається. Я точно не знаю, я лише вантажу й розвантажую речі.",
        ["npcs"] = { [1] = 12657 },
        ["roles"] = { ["greeting"] = true },
    },
    [2789709841] = {
        ["english"] = { [1] = "Tell me about the reduction." },
        ["text"] = "Розкажи мені про зменшення.",
        ["npcs"] = { [1] = 8115 },
        ["roles"] = { ["reply"] = true },
    },
    [4104737860] = {
        ["english"] = { [1] = "Throm'ka, $c. You are here to help me with tin bars? They tell me that I will need $2006w so that they can make weapons and armor for the upcoming Ahn'Qiraj War, but I only have $2005w right now. You are going to bring me more!" },
        ["text"] = "Тром’ка, $c. Ви тут, щоб допомогти мені з олов’яними зливками? Кажуть, мені потрібно $2006w, щоб виготовити зброю й обладунки для майбутньої війни Ан’Кіражу, але зараз у мене лише $2005w. Принесіть мені ще!",
        ["npcs"] = { [1] = 15460 },
        ["roles"] = { ["greeting"] = true },
    },
    [2506503546] = {
        ["english"] = { [1] = "That Granis Swiftaxe could drink a fish under the table and yet his axe still swings true.  However, if yer looking for training, ye best catch him while ye can understand him." },
        ["text"] = "Ґраніс Швидкосокира переп'є навіть рибу під столом, а його сокира все одно б'є точно. Та якщо шукаєш навчання, краще лови його, поки ще можеш розібрати, що він каже.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2281659871] = {
        ["english"] = { [1] = "This is it, $N. We charge on your orders! Just say the word and my men and I will engage!" },
        ["text"] = "Ось і все, $N. Ми підемо в атаку за вашим наказом! Лише скажіть слово — і ми з моїми бійцями вступимо в бій!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4124381812] = {
        ["english"] = { [1] = "The plaguelands are an excellent place to strike against the Scourge!" },
        ["text"] = "Чумнозем'я — чудове місце, щоб бити Скару!",
        ["npcs"] = { [1] = 11035 },
        ["roles"] = { ["greeting"] = true },
    },
    [3880239686] = {
        ["english"] = { [1] = "This place... it's cursed.$B$BI barely managed to escape, and I cannot bear to go down through the tunnels again.$B$BMy brother, and sisters though... They were not as fortunate. Trapped inside, they are feverish with the corrupted haze that flows from the evil garden growing there.$B$BPlease, you must help." },
        ["text"] = "Це місце... воно прокляте.$B$BЯ ледве зміг утекти й не витримаю ще раз спускатися тими тунелями.$B$BАле мої брат і сестри... їм не так пощастило. Вони замкнені всередині й марять від оскверненого серпанку, що струменить із лихого саду, який там росте.$B$BБудь ласка, ви мусите допомогти.",
        ["npcs"] = { [1] = 13697 },
        ["roles"] = { ["greeting"] = true },
    },
    [897352171] = {
        ["english"] = { [1] = "Thanks for the warning, $N! We shall prepare!" },
        ["text"] = "Дякую за попередження, $N! Ми підготуємося!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2945327585] = {
        ["english"] = { [1] = "The gryphon master oversees the gryphon flights from within Stormwind.  If you're looking to take a ride, then that's where you should be headed." },
        ["text"] = "Майстер грифонів керує польотами з самого Штормовію. Якщо хочеш кудись летіти, тобі саме туди.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3083914419] = {
        ["english"] = { [1] = "The only way a hero can die, $r: Through tragedy. The Grand Crusader struck a deal with Kel'Thuzad himself! An ambush would be staged that would result in the death of Mograine. The type of betrayal that could only be a result of the actions of one's most trusted and loved companions." },
        ["text"] = "Єдиний шлях, яким може померти герой, $r: через трагедію. Великий хрестоносець уклав угоду із самим Кел'Тузадом! Мала відбутися засідка, що призвела б до смерті Моґрейна. Така зрада могла бути лише справою рук найближчих і найдорожчих йому людей.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [4035933391] = {
        ["english"] = { [1] = "Throm'ka $c!  Are you ready to fight for the Horde at Warsong Gulch?" },
        ["text"] = "Тром’ка, $c! Ви готові битися за Орду в Ущелині Пісні Війни?",
        ["npcs"] = { [1] = 3890 },
        ["roles"] = { ["greeting"] = true },
    },
    [1219406897] = {
        ["english"] = { [1] = "The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself. \010" },
        ["text"] = "Могутня фортеця, висічена у вогняних нутрощах Чорнокамінної гори, століттями належала зловісним дворфам Темного Заліза, доки Нефаріан — хитрий син Смертокрила — не захопив верхній Шпиль і не почав війну проти володінь дворфів у вулканічних глибинах гори. Дізнавшись, що дворфами керує могутній вогняний елементаль Раґнарос, Нефаріан присягнувся розчавити ворогів і забрати всю Чорнокамінну гору собі.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [4254728715] = {
        ["english"] = { [1] = "The grass is soft and lush. The air is fresh, full of light and song. Everything I've seen suggests that Teldrassil is a dream come true. Why, then, is my heart full of foreboding?" },
        ["text"] = "Трава м'яка й густа. Повітря свіже, сповнене світла й пісень. Усе, що я бачив, підказує: Тельдрассіль — здійснена мрія. Чому ж тоді серце повне лихого передчуття?",
        ["npcs"] = { [1] = 4212 },
        ["roles"] = { ["greeting"] = true },
    },
    [1505966609] = {
        ["english"] = { [1] = "Thrallmar needs you, $c. The warchief needs you. Stand ready to do your duty." },
        ["text"] = "Траллмар потребує вас, $c. Вождь потребує вас. Будьте готові виконати свій обов’язок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2849186051] = {
        ["english"] = { [1] = "There is one whose knowledge exceeds my own. You are ready to seek her out. Go to Sun Rock Retreat in Stonetalon Mountains. Find Hgarth, and continue your training." },
        ["text"] = "Є одна майстриня, чиї знання перевищують мої. Ти готовий її знайти. Іди до Притулку Сонячної Скелі в Кам'янистих горах. Знайди Гґарта й продовжуй навчання.",
        ["npcs"] = { [1] = 3011 },
        ["roles"] = { ["greeting"] = true },
    },
    [4287133266] = {
        ["english"] = { [1] = "The people were destroyed in order to preserve the Prince's immortal life and near limitless powers. The power once divided among thousands now funnels into the Prince and the Shen'dralar zealots. Those few remaining survivors are directly feeding power into the pylons in order to keep Immol'thar imprisoned.$B$BShould the demon break free of its bonds, it would surely destroy what little is left of this once great bastion of arcana." },
        ["text"] = "Людей знищили, щоб зберегти безсмертне життя Принца й майже безмежну силу. Енергія, колись розподілена між тисячами, тепер стікається до Принца та фанатиків Шен'дралара. Нечисленні вцілілі безпосередньо живлять пілони, щоб утримувати Імол'тара в ув'язненні.$B$BЯкщо демон вирветься з пут, він напевно знищить рештки цього колись великого бастіону таємної магії.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [771664354] = {
        ["english"] = { [1] = "The water elementals are at war with the fire elementals, which sort of means they're at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause..." },
        ["text"] = "Водяні елементалі воюють із вогняними, а отже, певною мірою воюють і з нами. Один із їхніх ватажків, Гідраксіс, збирає агентів для своєї справи...",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [1227431315] = {
        ["english"] = { [1] = "Such needless strife, but if the elves of Silverwing Hold will not speak to us in peace, then what alternative do they leave us?  Seek out the aid of Kergul Bloodaxe on the Hunter Rise to get to Warsong Gulch.", [2] = "Such needless strife, but if the elves of Silverwing Hold will not speak to us in peace, then what alternative do they leave us? Seek out the aid of Kergul Bloodaxe on the Hunter Rise to get to Warsong Gulch." },
        ["text"] = "Стільки марної ворожнечі... Та якщо ельфи твердині Срібнокрилих не бажають говорити з нами мирно, який вибір вони нам лишають? Звернися по допомогу до Керґула Кровосокири на Висоті Мисливців, щоб дістатися Ущелини Пісні Війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2718124410] = {
        ["english"] = { [1] = "Take me to Crown Guard Tower." },
        ["text"] = "Відвези мене до вежі Королівської варти.",
        ["npcs"] = { [1] = 17209 },
        ["roles"] = { ["reply"] = true },
    },
    [1955672281] = {
        ["english"] = { [1] = "Tell me more about this thing you call \"cooking?\"" },
        ["text"] = "Розкажи мені більше про те, що ти називаєш «кулінарією»?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1174229180] = {
        ["english"] = { [1] = "The interrogator is trying to find out what these blood elves are doing here in Nagrand. From what I hear, they're after crystal powder residue from Oshu'gun, the diamond mountain to the west.$B$BNo doubt to use in some insidious scheme or concoction...$B$BIf you are looking to help our cause and stop these blood elves, the conflict is happening right now to the northwest at Halaa. Blood elves and those Hand of Argus soldiers are battling! Join in and show them what's right!" },
        ["text"] = "Допитувач намагається з'ясувати, що ці ельфи крові роблять тут, у Наґранді. Кажуть, вони полюють на залишки кришталевого порошку з Ошу'ґуна, діамантової гори на заході.$B$BБез сумніву, для якогось підступного задуму чи зілля...$B$BЯкщо хочеш допомогти нашій справі й зупинити ельфів крові, бій точиться просто зараз на північному заході, біля Галаа. Ельфи крові та солдати Десниці Арґуса б'ються! Приєднуйся й покажи їм, хто правий!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2086817814] = {
        ["english"] = { [1] = "The spirit of the Dreadsteed pulses with rage." },
        ["text"] = "Дух Жахоконя пульсує від люті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2423055578] = {
        ["english"] = { [1] = "Thrall's Grasp they called us: Twenty of Thrall's most accomplished and honored soldiers.$B$BI had ordered the regiment to build an encampment here, on the border of the Blasted Lands, while we waited for our orders to arrive from Orgrimmar. Weeks passed without word from the warchief; the men grew restless.$B$BIt was a judgment call, $N. I was young and ambitious, afraid of nothing. The battalion would set forth into the Blasted Lands under my command.$B$BA decision I would later regret." },
        ["text"] = "Нас називали Хваткою Тралла: двадцятеро найвидатніших і найшанованіших воїнів Тралла.$B$BЯ наказав загону розбити табір тут, на кордоні зі Спустошеними землями, доки ми чекали наказів з Орґріммара. Минали тижні без жодної звістки від вождя; бійці ставали неспокійними.$B$BЦе було рішення на мій розсуд, $N. Я був молодим і честолюбним, нічого не боявся. Батальйон рушив у Спустошені землі під моїм командуванням.$B$BРішення, про яке я згодом пошкодував.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [474452277] = {
        ["english"] = { [1] = "Thrall has shown great kindness in granting me sanctuary within his domain.  I do not wish to overstay my welcome, at any rate.  It would be a great dishonor if I brought any trouble to our leader." },
        ["text"] = "Тралл виявив велику доброту, давши мені притулок у своїх володіннях. Я не хочу зловживати його гостинністю. Було б великою ганьбою, якби через мене нашому вождеві завдали клопоту.",
        ["npcs"] = { [1] = 16012 },
        ["roles"] = { ["greeting"] = true },
    },
    [3688895151] = {
        ["english"] = { [1] = "There's a Bat Handler inside the Undercity.  Head south down the road out of Brill, then west at the T-intersection.  The Ruins of Lordaeron will be on your left.  Go into them and then down into the Undercity.  You can ask an Undercity Guardian there for further assistance." },
        ["text"] = "У Підмісті є доглядач кажанів. Вийди з Брілля дорогою на південь, а на Т-подібному перехресті поверни на захід. Руїни Лордерону будуть ліворуч. Увійди в них і спустися до Підмістя. Там можеш попросити вартового Підмістя про допомогу.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3292656110] = {
        ["english"] = { [1] = "The Northern Pylon accepts yellow, red, and green crystals.$B$BThe focus is the energy that can be created using yellow crystals as the main source of power. There are two possible effects: one that will produce damage, and one that will negate damage. $B$BCrystal Charge requires red and yellow crystals. This will produce a large explosion, stunning your enemies.$B$BCrystal Restore requires yellow and green crystals. This will provide you with a healing aura." },
        ["text"] = "Північний пілон приймає жовті, червоні й зелені кристали.$B$BЙого сила зосереджена на енергії, яку можна створити, використовуючи жовті кристали як головне джерело. Є два можливі ефекти: один завдає шкоди, другий — усуває її.$B$BДля Кришталевого заряду потрібні червоні й жовті кристали. Він спричинить великий вибух і приголомшить ворогів.$B$BДля Кришталевого відновлення потрібні жовті й зелені кристали. Воно надасть тобі ауру зцілення.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [2908992689] = {
        ["english"] = { [1] = "The Earth Mother holds many secrets and Brek Stonehoof can help you to discover some of them.  You will find him on the lower rise at Stonehoof Geology." },
        ["text"] = "Матір-Земля зберігає безліч таємниць, і Брек Кам'яне Копито допоможе відкрити деякі з них. Знайдеш його на нижньому виступі в «Геології Кам'яного Копита».",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [641714516] = {
        ["english"] = { [1] = "Though the Crossroads seems to be the center of activity in The Barrens, I prefer the quietude of Camp Taurajo.  Where shall I send you?" },
        ["text"] = "Хоч Роздоріжжя й здається центром життя у Степах, я віддаю перевагу тиші табору Таурахо. Куди вас відправити?",
        ["npcs"] = { [1] = 10378 },
        ["roles"] = { ["greeting"] = true },
    },
    [3272775342] = {
        ["english"] = { [1] = "Though I hate to admit it, the bear did get the better of me. My oh my, that's one big ol' bear!$b$bNonetheless, if you can take that bear down, it'd be a feat to be proud of! It gave more than a few of our best hunters some trouble.$b$b<He claps you on the back.>$b$bBest the bear and we'll accept you as a regular member of the Farstrider Lodge." },
        ["text"] = "Хоч мені й соромно це визнавати, ведмідь таки мене здолав. Ой лишенько, який же він величезний!$b$bТа якщо вам удасться його повалити, буде чим пишатися! Він завдав клопоту не одному з наших найкращих мисливців.$b$b<Він плескає вас по спині.>$b$bЗдолайте ведмедя — і ми приймемо вас як повноправного члена Пристанища Далекоходців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1775014583] = {
        ["english"] = { [1] = "The battle for Warsong Gulch is a battle that we cannot lose.  We fight for our honor and we fight for our land, and no orc or misguided ally will take them from us!" },
        ["text"] = "Ми не можемо програти битву за Ущелину Пісні Війни. Ми б'ємося за честь і за свою землю, і жоден орк чи засліплений союзник не відбере їх у нас!",
        ["npcs"] = { [1] = 14733 },
        ["roles"] = { ["greeting"] = true },
    },
    [3984480538] = {
        ["english"] = { [1] = "Though I find the cool grass which covers Teldrassil as good a bed as any, the beds which Saelienne keeps at the Inn in Craftsman's Terrace are quite suitable for those with a taste for luxury." },
        ["text"] = "Хоч прохолодна трава Тельдрассіля для мене не гірша за будь-яке ліжко, ліжка, які Сейлієнна тримає в заїзді на Ремісничій терасі, цілком пасують тим, хто полюбляє розкіш.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3854989438] = {
        ["english"] = { [1] = "They teach me to sneak good.  You find them in Rogues' Quarter on outer ring of Undercity." },
        ["text"] = "Вони вчать мене добре крастися. Знайдеш їх у Кварталі Розбійників на зовнішньому кільці Підмістя.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2963461307] = {
        ["english"] = { [1] = "Sure thing, $N. Here's another for you." },
        ["text"] = "Авжеж, $N. Ось іще один для тебе.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [2733092271] = {
        ["english"] = { [1] = "Those filthy beasts are all over the place.$B$BIf you prefer hunting outdoors, you'll find most of them around Plaguewood and Terrordale, with a good concentration of them in the Terrorweb tunnel. They are also likely to appear at almost any Scourge encampment in the Eastern Plaguelands.$B$BIf you're a hearty dungeon crawler, you'll find a good lot of them in Stratholme and a few of the necrofiend variety in Scholomance." },
        ["text"] = "Ці гидкі тварюки скрізь.$B$BЯкщо волієте полювати просто неба, найбільше їх знайдете біля Чумолісся й Жахокраю, а особливо багато — в тунелі Жахопавутини. Вони також часто трапляються майже в будь-якому таборі Скари у Східному Чумнозем’ї.$B$BЯкщо ж ви завзятий дослідник підземель, чимало їх знайдете у Стратгольмі, а кілька некронечистей — у Некроситеті.",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["greeting"] = true },
    },
    [1391424370] = {
        ["english"] = { [1] = "The Guild Master." },
        ["text"] = "Голова гільдії.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["reply"] = true },
    },
    [1926140025] = {
        ["english"] = { [1] = "Those beasts are amazing specimens. You should feel no shame at being bested by them." },
        ["text"] = "Ці звірі — дивовижні зразки. Не соромтеся того, що вони вас здолали.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2898586743] = {
        ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer in the Terrace of Light in Shattrath City. She'll aim you at a target in a small pond outside the city walls!" },
        ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на Терасі Світла в Шаттраті. Вона націлить тебе на мішень у невеликому ставку за міськими мурами!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2314645686] = {
        ["english"] = { [1] = "That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.\010\010The Hall of Mysteries is just north of the gates of Ironforge." },
        ["text"] = "Та маленька чарівниця Бінк із Зали Таємниць, певно, зможе допомогти тобі з будь-якими магічними справами.\010\010Зала Таємниць розташована одразу на північ від брами Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1275295179] = {
        ["english"] = { [1] = "Thorim lost it.  He lashed out against his most beloved allies, the frost giants.$B$BThat's one reason why to this day, this land is torn apart by the war between the Hyldnir and the Sons of Hodir... and why Thorim has exiled himself to the Temple of Storms." },
        ["text"] = "Торім не витримав. Він накинувся на своїх найближчих союзників — крижаних велетнів.$B$BЦе одна з причин, чому й донині ці землі роздирає війна між гільднірами та Синами Годіра... і чому Торім сам вигнав себе до Храму Бур.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1922470722] = {
        ["english"] = { [1] = "The humans are in need of your assistance in their fight against The Forsaken at Arathi Basin.  Go to the Hall of Arms and speak with their representative, Donal Osgood." },
        ["text"] = "Людям потрібна твоя допомога в боротьбі проти Відречених у Низині Араті. Іди до Зали Зброї й поговори з їхнім представником Доналом Осґудом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3523914583] = {
        ["english"] = { [1] = "This was the site of a great battle.  Many great battles." },
        ["text"] = "Тут відбулася велика битва. Багато великих битв.",
        ["npcs"] = { [1] = 9990 },
        ["roles"] = { ["greeting"] = true },
    },
    [912256292] = {
        ["english"] = { [1] = "The things I would teach you would turn your brain to jelly! Come back when you've learned sufficiently!" },
        ["text"] = "Від того, чого я міг би тебе навчити, твій мозок перетворився б на желе! Повернися, коли навчишся достатньо!",
        ["npcs"] = { [1] = 5174 },
        ["roles"] = { ["greeting"] = true },
    },
    [3217114235] = {
        ["english"] = { [1] = "These races are a great opportunity to show our ingenuity!" },
        ["text"] = "Ці перегони — чудова нагода продемонструвати нашу винахідливість!",
        ["npcs"] = { [1] = 4430 },
        ["roles"] = { ["greeting"] = true },
    },
    [2711019899] = {
        ["english"] = { [1] = "This war's not over, it's only just begun!  We have brave men and women fighting our enemy inside Ahn'Qiraj day and night, $N.  It won't be long before the Qiraji city falls." },
        ["text"] = "Ця війна не скінчилася — вона лише почалася! Хоробрі чоловіки й жінки б’ються з ворогом усередині Ан’Кіражу вдень і вночі, $N. Недовго лишилося до падіння міста кіражів.",
        ["npcs"] = { [1] = 15500 },
        ["roles"] = { ["greeting"] = true },
    },
    [272737052] = {
        ["english"] = { [1] = "This ain't a ride, clem.  Beat it." },
        ["text"] = "Це не атракціон, Клеме. Забирайся.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [3145659666] = {
        ["english"] = { [1] = "The guild master" },
        ["text"] = "Голова гільдії",
        ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [3700400718] = {
        ["english"] = { [1] = "This vibrant night dragon plant stands in stark contrast to the demonic taint that sunders Felwood.  Rare and luscious fruit, known as Night Dragon's Breath, hang heavily from the plant." },
        ["text"] = "Ця яскрава рослина нічного дракона разюче контрастує з демонічною скверною, що роздирає Сквернолісся. Рідкісні й соковиті плоди, відомі як Подих нічного дракона, важко звисають із неї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3350502119] = {
        ["english"] = { [1] = "This moon beam will send you to Orgrimmar.  Use your invitation when you want to go." },
        ["text"] = "Цей місячний промінь перенесе вас до Орґріммара. Скористайтеся запрошенням, коли захочете вирушити.",
        ["npcs"] = { [1] = 15908 },
        ["roles"] = { ["greeting"] = true },
    },
    [2267681172] = {
        ["english"] = { [1] = "Thank you $g mister : miss; for finding my necklace!  You're the best!" },
        ["text"] = "Дякую, $g пане : панно;, що знайшли моє намисто! Ви найкращі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3118637256] = {
        ["english"] = { [1] = "This tower is complete and utter madness. This isn't a library, it's a huge haystack of books and I don't think the needle even exists! Now, what was I doing?" },
        ["text"] = "Ця вежа — суцільне божевілля. Це не бібліотека, а величезна копиця книжок, і я вже не певен, що та голка взагалі існує! Так, чим я займався?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4126981267] = {
        ["english"] = { [1] = "This sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called Sul'thraze the Lasher, a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls.\010" },
        ["text"] = "Це випалене сонцем місто — оселя тролів Піщаної Люті, відомих особливою жорстокістю й темним містицизмом. Легенди тролів розповідають про могутній меч Сул’траз Здирач — зброю, здатну вселяти страх і слабкість навіть у найгрізніших ворогів. Давним-давно меч розкололи навпіл. Однак ходять чутки, що обидві половини можна знайти десь у мурах Зул’Фаррака.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3022388622] = {
        ["english"] = { [1] = "This spirit hovers over its fallen body.  Its ghostly eyes pierce through you as it gazes beyond..." },
        ["text"] = "Цей дух ширяє над своїм полеглим тілом. Його примарні очі пронизують вас, вдивляючись кудись за межі...",
        ["npcs"] = { [1] = 8612 },
        ["roles"] = { ["greeting"] = true },
    },
    [4109373754] = {
        ["english"] = { [1] = "The Consortium will exact its revenge upon the Zaxxis betrayers!" },
        ["text"] = "Консорціум помститься зрадникам із Закксісу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [739679273] = {
        ["english"] = { [1] = "That Eunice Burch in Trade Quarter." },
        ["text"] = "Та Юніс Берч у Торговому кварталі.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2907019350] = {
        ["english"] = { [1] = "Thank you for checking in with me, $c. We now have all of the thorium bars that we'll need, but you may want to ask some of the others here that are in charge of different collection efforts." },
        ["text"] = "Дякую, що завітав, $c. Тепер у нас є всі потрібні торієві зливки, але можеш розпитати інших, хто відповідає за різні збори.",
        ["npcs"] = { [1] = 15432 },
        ["roles"] = { ["greeting"] = true },
    },
    [795634306] = {
        ["english"] = { [1] = "That's some impressive skill ye have there $N. The blades and hammers ye make surpass even my own, hard as that is to admit. Only person I ever met with skill even greater is Borgus Steelhand, I bet he could teach ye a thing or three." },
        ["text"] = "Вражаюча майстерність, $N. Твої клинки й молоти перевершують навіть мої, хоч мені й важко це визнавати. Єдиний, кого я зустрічав і хто вміє ще краще, — Борґус Сталерук. Б'юся об заклад, він навчить тебе дечого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2699307337] = {
        ["english"] = { [1] = "The sky is not safe, friend. Be alert!" },
        ["text"] = "Небо небезпечне, друже. Будь напоготові!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2559446919] = {
        ["english"] = { [1] = "The Emerald Circle strives to heal the wounded land of Felwood. Although the land is named for the very thing that has corrupted it, we hope that one day we will be able to eradicate the corruption from this land." },
        ["text"] = "Смарагдове Коло прагне зцілити поранену землю Сквернолісся. Хоч край названий на честь самої сили, що його осквернила, ми сподіваємося, що одного дня зможемо очистити цю землю від скверни.",
        ["npcs"] = { [1] = 9116 },
        ["roles"] = { ["greeting"] = true },
    },
    [1004643439] = {
        ["english"] = { [1] = "Then meet me at the entrance to the abbey. I'll be along in short order." },
        ["text"] = "Тоді зустрінь мене біля входу до абатства. Я скоро підійду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [200439125] = {
        ["english"] = { [1] = "This songflower plant stands out as a rock in the sea of corruption that is Felwood.  Its petals have a powerful fragrance that bolsters your spirits and strengthens your resolve." },
        ["text"] = "Ця піснеквітка стоїть, мов скеля в морі скверни, яким стало Сквернолісся. Її пелюстки мають сильний аромат, що підносить дух і зміцнює рішучість.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1454530363] = {
        ["english"] = { [1] = "This sign contains various announcements and notices of rewards." },
        ["text"] = "На цій дошці висять різні оголошення й повідомлення про винагороди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [871862036] = {
        ["english"] = { [1] = "The liquids and mixtures all bubble and spasm as you approach. Next to the equipment lies a large pair of tongs that look as though they would be adequate for dropping in samples of ooze.$B$BThere is safety gear present, but it appears to be dusty and well-ignored.$B$BYou don't think touching anything would be wise." },
        ["text"] = "Коли ти наближаєшся, рідини й суміші починають булькотіти й сіпатися. Поряд з обладнанням лежать великі щипці, якими, схоже, зручно опускати зразки слизу.$B$BЗахисне спорядження є, але воно припало пилом і явно давно не використовувалося.$B$BТобі здається, що торкатися тут чогось — погана ідея.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2673151470] = {
        ["english"] = { [1] = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter." },
        ["text"] = "У цій крижаній скалці відлунює глибокий тріск наступаючих льодовиків. Її холод навіює думки про мертву, нескінченну зиму.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1129057635] = {
        ["english"] = { [1] = "Tell me more about these Darkmoon Cards." },
        ["text"] = "Розкажи мені більше про ці карти Темного Місяця.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["reply"] = true },
    },
    [3253818406] = {
        ["english"] = { [1] = "The Snowfall Graveyard lies high atop a hill in the Field of Strife, east of Winterax Hold.$B$BNeither side controls it." },
        ["text"] = "Кладовище Снігопаду лежить високо на пагорбі Поля Боротьби, на схід від фортеці Зимосокири.$B$BЙого не контролює жодна зі сторін.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1129712292] = {
        ["english"] = { [1] = "This potion seems to heal less damage every time I brew it, though I use the same ingredients. There can be only one conclusion: the plants are changing. I cannot say why or into what." },
        ["text"] = "Це зілля щоразу зцілює дедалі менше, хоч я використовую ті самі складники. Висновок може бути лише один: рослини змінюються. Не можу сказати, чому й на що саме.",
        ["npcs"] = { [1] = 4160 },
        ["roles"] = { ["greeting"] = true },
    },
    [2965006071] = {
        ["english"] = { [1] = "The Horde must not allow the draenei and their meddling Alliance to control all the mana cells in Outland. Will you join the blood elves in their assault on the Eye of the Storm?" },
        ["text"] = "Орда не може дозволити дренеям і їхнім втручальникам з Альянсу контролювати всі комірки мани в Позамежжі. Приєднаєшся до ельфів крові в їхньому нападі на Око Бурі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3311873428] = {
        ["english"] = { [1] = "Then Orgrimmar is where you need to go.  The north road out of Razor Hill leads directly there.  Just talk to one of the grunts there and they can give you further directions." },
        ["text"] = "Тоді тобі треба до Орґріммара. Північна дорога з Колючого Пагорба веде прямо туди. Просто поговори з одним із рубак — вони підкажуть далі.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [501490106] = {
        ["english"] = { [1] = "The Darkmoon Faire is right now located in the golden plains of Mulgore, just southwest of Thunder Bluff.  Don't miss it!" },
        ["text"] = "Ярмарок Темного Місяця зараз розташований на золотих рівнинах Мулґора, трохи на південний захід від Громового Бескиду. Не пропусти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [443278338] = {
        ["english"] = { [1] = "That's right, I've seen you here before! How could I forget? I can teleport you to Stratholme now, if you wish." },
        ["text"] = "Точно, я вже бачив тебе тут! Як я міг забути? Якщо хочеш, тепер можу телепортувати тебе до Стратгольма.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [286089274] = {
        ["english"] = { [1] = "The Venture Company based around Windshear Crag in Stonetalon keeps their supplies in locked boxes." },
        ["text"] = "Торговельна компанія біля Вітрорізного кряжа в Кам'янистих горах зберігає припаси в замкнених скринях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3934613660] = {
        ["english"] = { [1] = "This is a dangerous place, $N. Be careful around here." },
        ["text"] = "Це небезпечне місце, $N. Будьте тут обережні.",
        ["npcs"] = { [1] = 738 },
        ["roles"] = { ["greeting"] = true },
    },
    [2685748560] = {
        ["english"] = { [1] = "These babies can hurl fire like none other. We've even attached a secondary cannon, a grappling hook and added a manual fuel injection system.  If you can obtain liquid pyrite from the mechanognomes, you can use it to hurl high-density explosives, or turbo-boost your movement speed. $B$BLet's see those Explorer's League twirps beat that!" },
        ["text"] = "Ці крихітки жбурляють вогонь як ніхто інший. Ми навіть прикріпили другу гармату, гак і додали ручну систему впорскування пального. Якщо дістанеш рідкий пірит у механогномів, зможеш запускати вибухівку високої щільності або турбоприскорювати рух.$B$BПодивимося, чи зможуть ті телепні з Ліги дослідників це перевершити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1675876034] = {
        ["english"] = { [1] = "This portal leads to the Caverns of Time, deep beneath the earth in far-off Tanaris.$B$BUntil you have grown stronger, though, I must ask you not to travel there." },
        ["text"] = "Цей портал веде до Печер Часу, глибоко під землею в далекому Танарісі.$B$BАле доки ви не станете сильнішими, мушу просити вас туди не подорожувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2396524979] = {
        ["english"] = { [1] = "The mighty hunter, $N returns.  Tell me the tale of stalking your latest prey." },
        ["text"] = "Могутній мисливець $N повернувся. Розкажи мені про полювання на свою останню здобич.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4257417222] = {
        ["english"] = { [1] = "The bank is located in the serene city of Darnassus.  You must go there if you wish to store your possessions." },
        ["text"] = "Банк розташований у спокійному місті Дарнасі. Якщо хочеш зберігати свої речі, мусиш піти туди.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1376050768] = {
        ["english"] = { [1] = "Teleport me to the lair of the Twin Emperors, please." },
        ["text"] = "Телепортуйте мене до лігва Імператорів-близнюків, будь ласка.",
        ["npcs"] = { [1] = 15502 },
        ["roles"] = { ["reply"] = true },
    },
    [1604808914] = {
        ["english"] = { [1] = "This is getting good!  It really warms the stomach!  And $N, I have to say, you're a sharp dressing $gfellow:lass;!" },
        ["text"] = "Оце вже стає цікаво! Аж у животі теплішає! І, $N, мушу сказати, ви вельми $g ошатний юнак : ошатна дівчино;!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [905069498] = {
        ["english"] = { [1] = "This does not concern you. Be on your way." },
        ["text"] = "Це вас не стосується. Ідіть своєю дорогою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [291102492] = {
        ["english"] = { [1] = "This plant stands out among the normal flora of Teldrassil, and emits a strange, purplish glow." },
        ["text"] = "Ця рослина вирізняється серед звичайної флори Тельдрассіля й випромінює дивне пурпурове сяйво.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [977644445] = {
        ["english"] = { [1] = "The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free. \010" },
        ["text"] = "Штормовійська В'язниця — комплекс суворого режиму, прихований під каналами міста Штормовій. Під наглядом наглядача Телвотера тут утримують дрібних злочинців, політичних заколотників, убивць і безліч найнебезпечніших злочинців краю. Нещодавно повстання в'язнів спричинило цілковитий хаос: охорону вигнали, а засуджені вільно блукають камерами.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2611064454] = {
        ["english"] = { [1] = "This ethereal teleport pad is covered in brightly colored buttons and switches, but seems to have fallen into disuse." },
        ["text"] = "Цей ефірний телепортаційний майданчик укритий яскравими кнопками й перемикачами, але, схоже, давно не використовується.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2839467619] = {
        ["english"] = { [1] = "Throm'ka, $c. All of the war materiel is in final preparation and being sent to Silithus. It should arrive over the course of the next $2113w days. With the equipment readied, and our forces arrayed, all we will be waiting for is someone to ring the gong on the Scarab Dais, which should open the gates of Ahn'Qiraj and start the war.$B$BLok'tar Ogar!" },
        ["text"] = "Тром’ка, $c. Усі військові припаси проходять останню підготовку й вирушають до Силітуса. Вони мають прибути протягом наступних $2113w днів. Коли спорядження буде готове, а наші сили розгорнуті, залишиться тільки дочекатися, доки хтось ударить у гонг на Помості Скарабея, що має відкрити брами Ан’Кіражу й розпочати війну.$B$BЛок’тар Оґар!",
        ["npcs"] = { [1] = 15522 },
        ["roles"] = { ["greeting"] = true },
    },
    [3980296542] = {
        ["english"] = { [1] = "The story of your journey will be told for years to come!" },
        ["text"] = "Історію твоєї подорожі розповідатимуть багато років!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [549887846] = {
        ["english"] = { [1] = "There is only one whose skills exceed my own. You are ready to receive her knowledge. She is Annora, and you may find her... in Uldaman." },
        ["text"] = "Є лише одна людина, чия майстерність перевищує мою. Ти готовий прийняти її знання. Її звати Аннора, і знайти її можна... в Ульдамані.",
        ["npcs"] = { [1] = 11074 },
        ["roles"] = { ["greeting"] = true },
    },
    [1436516215] = {
        ["english"] = { [1] = "The Thunder Bluff Bank can be found on the lower rise." },
        ["text"] = "Банк Громового Бескиду розташований на нижньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [541658219] = {
        ["english"] = { [1] = "The Light gives us the strength and magic to triumph." },
        ["text"] = "Світло дає нам силу й магію для перемоги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1252443735] = {
        ["english"] = { [1] = "The zeppelin master" },
        ["text"] = "Майстер дирижаблів",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [3559773178] = {
        ["english"] = { [1] = "The spirits have brought you to me, and so I feel blessed by them. " },
        ["text"] = "Духи привели тебе до мене, тож я відчуваю їхнє благословення.",
        ["npcs"] = { [1] = 2998, [2] = 3478 },
        ["roles"] = { ["greeting"] = true },
    },
    [2577063802] = {
        ["english"] = { [1] = "This outfit really brings out the blue in my eyes, don't you think? It should be obvious I have plenty of skill to go around, so I can afford to share a few of my tricks of the trade. Listen up, okay?" },
        ["text"] = "Це вбрання чудово підкреслює блакить моїх очей, хіба ні? Мало б бути очевидно, що майстерності в мене хоч відбавляй, тож можу поділитися кількома професійними хитрощами. Слухайте уважно, гаразд?",
        ["npcs"] = { [1] = 11096 },
        ["roles"] = { ["greeting"] = true },
    },
    [697752006] = {
        ["english"] = { [1] = "There is a pile of wrapped gifts here." },
        ["text"] = "Тут лежить купа загорнутих подарунків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3193294684] = {
        ["english"] = { [1] = "That's the spirit!$B$BI'm glad that we had this little meeting.  I feel much better about the attack now.  With leaders like you on the front, how can we lose?$B$BAlright, you have your marching orders.  Now get back to the Ruuan Weald and make it happen!" },
        ["text"] = "Оце настрій!$B$BРадий, що ми трохи поговорили. Тепер я значно спокійніше дивлюся на майбутній напад. З такими ватажками на передовій як ми можемо програти?$B$BГаразд, накази ти отримав. А тепер повертайся до Руаної Пущі й зроби це!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [675540281] = {
        ["english"] = { [1] = "The Bronze Flight is in your debt." },
        ["text"] = "Бронзова зграя в боргу перед тобою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [785669301] = {
        ["english"] = { [1] = "Sword" },
        ["text"] = "Меч",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869, [6] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [3807626647] = {
        ["english"] = { [1] = "The Iceblood Graveyard is on the south side of the Field of Strife, east of the Iceblood Tower.$B$BThe Horde currently controls it." },
        ["text"] = "Кладовище Крижаної Крові лежить на південному боці Поля Боротьби, на схід від вежі Крижаної Крові.$B$BНаразі його контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3883689767] = {
        ["english"] = { [1] = "The fissure closed and Krixix was gone! Swallowed whole!$B$BBe warned, $r, what you wish for could very well become that which you do not want. You play with beings and arcana that are older than time itself!$B$BShould Krixix be alive and should he have the information which you seek, you can be certain that he will not give up said information. He has faced terrors far worse than you could ever dream to perpetuate." },
        ["text"] = "Розлом закрився, і Криксікс зник! Його поглинуло цілком!$B$BСтережися, $r: те, чого ти бажаєш, цілком може обернутися на те, чого ти не хочеш. Ти граєшся з істотами й таємними силами, старшими за сам час!$B$BЯкщо Криксікс живий і має відомості, яких ти шукаєш, будь певен: добровільно він їх не віддасть. Він зустрічав жахи, значно страшніші за все, що ти здатен уявити.",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["greeting"] = true },
    },
    [1369633663] = {
        ["english"] = { [1] = "This is awful! I shouldn't be sitting here, useless, when there's so much to be done! If only my arm hadn't gotten injured up in Northrend... No use dwelling on it, though! Tahu will have me patched up and cured eventually, and we'll still help around here in the meantime.$B$BJust because we're not at the front doesn't mean we can't help out somehow." },
        ["text"] = "Це жахливо! Я не повинен сидіти тут без діла, коли стільки всього треба зробити! Якби ж я не пошкодив руку в Нортренді... Та немає сенсу про це думати! Тагу зрештою мене підлатає й вилікує, а поки ми все одно допомагатимемо тут.$B$BТе, що ми не на передовій, не означає, що ми нічим не можемо зарадити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3177892261] = {
        ["english"] = { [1] = "This moonlight will send you to Ironforge.  But who'd want to leave this party?" },
        ["text"] = "Це місячне сяйво перенесе вас до Залізогарта. Але хто захоче залишати таку гулянку?",
        ["npcs"] = { [1] = 15906 },
        ["roles"] = { ["greeting"] = true },
    },
    [3343714579] = {
        ["english"] = { [1] = "The ways of Jaedenar are dark and treacherous.  Watch your moves in this place, $C, or you will find your soul entralled by your rivals..." },
        ["text"] = "Шляхи Джеденара темні й підступні. Пильнуй кожен крок у цьому місці, $C, інакше твою душу можуть поневолити суперники...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1653106812] = {
        ["english"] = { [1] = "Tell me more about the Western Crystal Pylon." },
        ["text"] = "Розкажи мені більше про Західний Кришталевий Пілон.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["reply"] = true },
    },
    [2395309681] = {
        ["english"] = { [1] = "The Silverwing Sentinels still fight the Horde in Warsong Gulch, $c. What remains to be seen is if you will return there to help them." },
        ["text"] = "Срібнокрилі Вартові досі б'ються з Ордою в Ущелині Пісні Війни, $c. Питання лише в тому, чи повернешся ти туди допомогти їм.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [938800133] = {
        ["english"] = { [1] = "That would be wonderful! Thank you, Meridith." },
        ["text"] = "Було б чудово! Дякую, Мередіт.",
        ["npcs"] = { [1] = 15526 },
        ["roles"] = { ["reply"] = true },
    },
    [3897260892] = {
        ["english"] = { [1] = "The spirits told me you would come, that you would seek me for some reason, but that even you may not know that reason. So, do you know why you are here?" },
        ["text"] = "Духи сказали, що ти прийдеш і шукатимеш мене з якоїсь причини, але навіть ти можеш її не знати. Тож знаєш, навіщо ти тут?",
        ["npcs"] = { [1] = 7869 },
        ["roles"] = { ["greeting"] = true },
    },
    [3162228232] = {
        ["english"] = { [1] = "The strength of your resolve shines, $N. You continue to prove that you are an asset to our people. Someday the world will realize the extent of your great deeds." },
        ["text"] = "Сила твоєї рішучості сяє, $N. Ти знову й знову доводиш, що корисний нашому народові. Одного дня світ усвідомить масштаб твоїх великих діянь.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2231659352] = {
        ["english"] = { [1] = "The felhound... a vicious creature indeed. It is not as physically strong as an infernal, but a wise warlock knows that brute force is not always the answer--if it was, you would have chosen the path of a warrior instead, wouldn't you?$B$BThe felhound draws upon the mana of its foes, using that and its quickness to overcome enemies. Its strength comes from the arcane and using that arcane power for its own ends.$B$BIf you wish to know more about infernals, then you should speak to Magaz across from me." },
        ["text"] = "Скверногончак... справді люта істота. Фізично він не такий сильний, як інфернал, але мудрий чорнокнижник знає: груба сила — не завжди відповідь. Якби це було так, ти пішов би шляхом воїна, правда?$B$BСкверногончак живиться маною ворогів і використовує її разом зі швидкістю, щоб перемагати. Його сила походить із таємної магії й уміння використовувати її для власних цілей.$B$BЯкщо хочеш більше дізнатися про інферналів, поговори з Маґазом навпроти мене.",
        ["npcs"] = { [1] = 6254 },
        ["roles"] = { ["greeting"] = true },
    },
    [4018807373] = {
        ["english"] = { [1] = "This may come as a shock to you, but business hasn't been all that good as of late..." },
        ["text"] = "Може, це вас здивує, але останнім часом справи в торгівлі йдуть не надто добре...",
        ["npcs"] = { [1] = 9676 },
        ["roles"] = { ["greeting"] = true },
    },
    [4117986445] = {
        ["english"] = { [1] = "They have grown up here. We kept them safe from harm. We did the best that we could in nursing them back to health. Many perished but many, many more grew strong. Like Garrosh...$B$B<Greatmother Geyah sighs.>$B$BHe has lost his heart, you know. He tells me that I am his balance. That without me, the blood lust that consumed his father and ultimately cursed our people would take him over." },
        ["text"] = "Вони виросли тут. Ми берегли їх від біди. Робили все можливе, щоб виходити їх і повернути здоров'я. Багато загинуло, але ще більше виросло сильними. Як Ґаррош...$B$B<Праматір Ґейя зітхає.>$B$BВін утратив серце, знаєш. Каже, що я — його рівновага. Що без мене жага крові, яка поглинула його батька й зрештою прокляла наш народ, поглине й його.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2516805782] = {
        ["english"] = { [1] = "This large jack-o'-lantern rests in the middle of the village." },
        ["text"] = "Посеред селища стоїть великий гарбузовий ліхтар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3494224736] = {
        ["english"] = { [1] = "This kind of work isn't for the faint of heart. I have an uncle who lost a hand! Poor old Stumpy... anyway, if you're still interested I might be able to show you a few things." },
        ["text"] = "Така робота не для слабкодухих. У мене дядько руку втратив! Бідолашний старий Кукса... Та якщо тобі й досі цікаво, можу показати кілька прийомів.",
        ["npcs"] = { [1] = 11026 },
        ["roles"] = { ["greeting"] = true },
    },
    [4191392836] = {
        ["english"] = { [1] = "Stormwind Counting House is located by the front gates in the Trade District of Stormwind. And when you get tired of counting your money, be sure to stop by the Gilded Rose for a drink.", [2] = "Stormwind Counting House is located by the front gates in the trade district of Stormwind. And when you get tired of counting your money, be sure to stop by the Gilded Rose for a drink." },
        ["text"] = "Рахункова палата Штормовію розташована біля головної брами в Торговому районі. А коли втомишся рахувати гроші, обов'язково зазирни до «Позолоченої троянди» випити чогось.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3890920346] = {
        ["english"] = { [1] = "Thank you for delivering that list!  My leg is almost recovered enough that I'll be able to walk back to the crash site." },
        ["text"] = "Дякую, що доставив той список! Нога вже майже загоїлася настільки, що я зможу сам дійти назад до місця падіння.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [975524820] = {
        ["english"] = { [1] = "That's it, everything's been collected by both sides. Now it's all being transported over to Silithus and should be there in less than a day. Once that's done and someone rings the gong on the Scarab Dais with the Scepter of the Shifting Sands, the war is on!" },
        ["text"] = "От і все, обидві сторони зібрали все потрібне. Тепер усе везуть до Силітуса, і менш ніж за день воно буде там. Коли це станеться й хтось ударить у гонг на Помості Скарабея Скіпетром Мінливих Пісків — війна почнеться!",
        ["npcs"] = { [1] = 15434 },
        ["roles"] = { ["greeting"] = true },
    },
    [3282839941] = {
        ["english"] = { [1] = "The alchemy lab is not quite yet ready, $N. Mar'nah says that she is $3223w percent done with its assembly, however.$B$BIf you would like to help her with that, you will find her inside the inn at the Sun's Reach Harbor." },
        ["text"] = "Алхімічна лабораторія ще не зовсім готова, $N. Мар'на каже, що її зібрано на $3223w відсотків.$B$BЯкщо хочеш допомогти, знайдеш її в корчмі в Гавані Сонячного Краю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1290770456] = {
        ["english"] = { [1] = "There's only one hunter around here I would have ye talk to, and that would be Grif Wildheart.  Ye'll find him standing just outside the smithy in Kharanos." },
        ["text"] = "Є лише один мисливець у цих краях, з яким я радив би поговорити, — Ґріф Дикосерд. Знайдеш його просто біля кузні в Караносі.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [270638949] = {
        ["english"] = { [1] = "There is a wise one in the village who goes by the name Narm Skychaser.  He can continue your learning along the path of the Shaman." },
        ["text"] = "У селищі є мудрець на ім'я Нарм Небесний Переслідувач. Він може продовжити твоє навчання на шляху шамана.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3637216912] = {
        ["english"] = { [1] = "This just happens to be your lucky day; I just completed Super-Seller 680's maintenance. There are tons of items for sell at great low-low prices. Go ahead and see for yourself... my brother Cork thinks his Vendor-Tron 1000 will out sell my bot." },
        ["text"] = "Сьогодні твій щасливий день: я щойно завершив техобслуговування Супер-Продавця 680. У нього сила-силенна товарів за неймовірно низькими цінами. Іди та переконайся сам... Мій брат Корк думає, що його Торговельник-1000 переплюне мого робота.",
        ["npcs"] = { [1] = 11626 },
        ["roles"] = { ["greeting"] = true },
    },
    [3233292986] = {
        ["english"] = { [1] = "The pumpkin has been smashed, and offers no more treasure." },
        ["text"] = "Гарбуз розбито, і скарбів у ньому більше немає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2683013855] = {
        ["english"] = { [1] = "This job is definitely not worth sixteen-five a year." },
        ["text"] = "Ця робота точно не варта шістнадцяти з половиною на рік.",
        ["npcs"] = { [1] = 11056 },
        ["roles"] = { ["greeting"] = true },
    },
    [2044601770] = {
        ["english"] = { [1] = "This isn't a game you toy with youngling! Go, speak with Snarl outside. He may be a serpent in my lair but he does know his way around an anvil." },
        ["text"] = "Це не гра, з якою можна бавитися, малечо! Іди, поговори зі Снарлом надворі. Може, він і змій у моєму лігві, але з ковадлом поводитися вміє.",
        ["npcs"] = { [1] = 3355 },
        ["roles"] = { ["greeting"] = true },
    },
    [1516322726] = {
        ["english"] = { [1] = "This isn't quite what I signed up for, but hey... at least it's warm here." },
        ["text"] = "Це не зовсім те, на що я підписувався, але... принаймні тут тепло.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [981571142] = {
        ["english"] = { [1] = "The School for Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands." },
        ["text"] = "Школа некромантії, відома як Некроситет, розташована на зруйнованому острові Каєр-Дарроу в Західному Чумнозем'ї.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [113149084] = {
        ["english"] = { [1] = "The skinners usually take all their hides into Ironforge to dry out.  Why don't you head there and see if you can find one to train ye?" },
        ["text"] = "Шкуродери зазвичай несуть усі шкури сушити до Залізогарта. Чому б тобі не піти туди й не знайти когось, хто тебе навчить?",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3572917739] = {
        ["english"] = { [1] = "The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see!" },
        ["text"] = "Ярмарок Темного Місяця прибув до міста! Не пропусти найзахопливіше видовище у своєму житті!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3674544162] = {
        ["english"] = { [1] = "This is the gateway that Kael's armies used to retreat to the Sunwell.  Some of his lapdogs remain here; the Legion has rewarded them in a most... unusual way." },
        ["text"] = "Це брама, крізь яку війська Келя відступили до Сонячного Колодязя. Дехто з його псів залишився тут; Легіон винагородив їх у вельми... незвичайний спосіб.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4112946295] = {
        ["english"] = { [1] = "This is the end of the line, no friend of mine!" },
        ["text"] = "Тут тобі кінець, ти мені не друг!",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["greeting"] = true },
    },
    [3148761482] = {
        ["english"] = { [1] = "There's nothing I can teach you, other than maybe a better eye for color and detail. Talk to Simon Tanner over there; he knows a lot of advanced techniques for working with leather." },
        ["text"] = "Мені нічого тебе навчити, хіба що краще розрізняти кольори й деталі. Поговори з Саймоном Таннером он там; він знає багато складних прийомів роботи зі шкірою.",
        ["npcs"] = { [1] = 11096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1537014753] = {
        ["english"] = { [1] = "Surely you've been a student once in your life, $c. You learned from an instructor, and you gained respect for them in some way, yes? Maybe not as a person, but at the least, as one who knew more than you and was willing to teach you. If not, use your imagination...$b$bWhat would you do if you came to realize your instructor may not know as much as you thought, and that you may have found a better path?" },
        ["text"] = "Ти ж колись у житті був учнем, $c. Навчався в наставника й так чи інакше поважав його, так? Може, не як людину, але принаймні як того, хто знав більше за тебе й був готовий навчати. Якщо ні — уяви...$b$bЩо б ти зробив, якби зрозумів, що твій наставник знає не так багато, як ти думав, а ти, можливо, знайшов кращий шлях?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2905255771] = {
        ["english"] = { [1] = "The humans and their so-called League of Arathor think to push us out of Arathi Basin.  I think not $c!  Are you ready to be sent there and demonstrate that it is they, and not The Defilers, that will be leaving soon?" },
        ["text"] = "Люди та їхня так звана Ліга Аратора думають витіснити нас із Низини Араті. Не вийде, $c! Готовий вирушити туди й показати, що незабаром підуть саме вони, а не Осквернителі?",
        ["npcs"] = { [1] = 15006 },
        ["roles"] = { ["greeting"] = true },
    },
    [4261562471] = {
        ["english"] = { [1] = "Teaching is not a one-sided trade, $N. As I teach you, I learn more myself, and my understanding grows." },
        ["text"] = "Навчання — не одностороння справа, $N. Навчаючи тебе, я й сам дізнаюся більше, а моє розуміння поглиблюється.",
        ["npcs"] = { [1] = 3964 },
        ["roles"] = { ["greeting"] = true },
    },
    [814570110] = {
        ["english"] = { [1] = "There is one that I know of here in Thunder Bluff that can aid you in your journey to Alterac Valley.  On the Hunter Rise look for Taim Ragetotem.  May you find what you are looking for $N.", [2] = "There is one that I know of here in Thunder Bluff that can aid you in your journey to Alterac Valley. On the Hunter Rise look for Taim Ragetotem. May you find what you are looking for $N." },
        ["text"] = "Я знаю одного тут, у Громовому Бескиді, хто може допомогти тобі дістатися Альтерацької долини. Шукай Тайма Лютого Тотема на Висоті Мисливців. Нехай знайдеш те, чого шукаєш, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2108145468] = {
        ["english"] = { [1] = "This is MY WAGON!$B$BMINE!" },
        ["text"] = "Це МІЙ ВІЗ!$B$BМІЙ!",
        ["npcs"] = { [1] = 2153 },
        ["roles"] = { ["greeting"] = true },
    },
    [694798295] = {
        ["english"] = { [1] = "Strive to keep the balance in all things, $c.  This is where true harmony lies." },
        ["text"] = "Прагни зберігати рівновагу в усьому, $c. Саме в ній істинна гармонія.",
        ["npcs"] = { [1] = 3033 },
        ["roles"] = { ["greeting"] = true },
    },
    [2786829204] = {
        ["english"] = { [1] = "The Scourge are a blemish upon these pristine lands.  By the might of my creators, I will crush every last one of their decrepit bones under my heel." },
        ["text"] = "Скара — пляма на цих чистих землях. Силою моїх творців я розчавлю під п'ятою кожну їхню гнилу кістку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [92092732] = {
        ["english"] = { [1] = "The musty pages of the codex seem to magically turn themselves, guiding your attention to a specific chapter past horrors no mortal eyes should ever perceive.$B$BThe book opens to a page that somehow feels 'right,' yet so very wrong." },
        ["text"] = "Затхлі сторінки кодексу ніби самі перегортаються, ведучи твій погляд до певного розділу повз жахи, яких не повинні бачити очі смертних.$B$BКнига відкривається на сторінці, що чомусь здається «правильною» — і водночас страшенно неправильною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4170319061] = {
        ["english"] = { [1] = "Throm'ka, $c. Did you know our fight with the Silverwing Sentinels in Warsong Gulch continues still? Your presence would be welcome there..." },
        ["text"] = "Тром’ка, $c. Чи знаєте ви, що наша боротьба зі Срібнокрилими вартовими в Ущелині Пісні Війни досі триває? Там вам будуть раді...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1583882484] = {
        ["english"] = { [1] = "Sure, sure.  We have a Mining Trainer right here in town.  Look for Krunn over in the northwest corner alongside the inn." },
        ["text"] = "Авжеж, авжеж. У нас тут у місті є наставник гірництва. Шукай Крунна в північно-західному кутку, біля корчми.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [133852618] = {
        ["english"] = { [1] = "Step right up!  Get your Red Hot Wings right here!" },
        ["text"] = "Підходьте ближче! Гарячі крильця — просто тут!",
        ["npcs"] = { [1] = 14845 },
        ["roles"] = { ["greeting"] = true },
    },
    [3157238072] = {
        ["english"] = { [1] = "The stranded Alliance sailors know they're going to die, yet they fight us tooth and nail.$B$BImpressive and pathetic at the same time." },
        ["text"] = "Моряки Альянсу, що застрягли тут, знають, що загинуть, але б'ються з нами до останнього.$B$BВодночас вражає й викликає жаль.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4055351638] = {
        ["english"] = { [1] = "The untamed plains of Nagrand offer some of the best hunting I've ever experienced. " },
        ["text"] = "Дикі рівнини Наґранда пропонують одне з найкращих полювань, які я коли-небудь бачив.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2762272096] = {
        ["english"] = { [1] = "Then I am glad you came. Now that you know of our fires, and of honoring them... and of the fires of our enemies, and of extinguishing them... you may return to him and be rewarded." },
        ["text"] = "Тоді я радий, що ти прийшов. Тепер, коли ти знаєш про наші вогні та як їх ушановувати... і про вогні ворогів та як їх гасити... можеш повернутися до нього по нагороду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [906748559] = {
        ["english"] = { [1] = "Take a look around and let me know if there's anything that you're interested in." },
        ["text"] = "Озирнися й скажи, якщо щось тебе зацікавить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1376507091] = {
        ["english"] = { [1] = "Sure! Let's go for a ride." },
        ["text"] = "Авжеж! Поїхали.",
        ["npcs"] = { [1] = 2859 },
        ["roles"] = { ["reply"] = true },
    },
    [2497075717] = {
        ["english"] = { [1] = "Sure, I'll tell you the phrase.  As long as I don't have to go anywhere near Tirth!" },
        ["text"] = "Гаразд, скажу тобі фразу. Але тільки якщо мені не доведеться навіть наближатися до Тірта!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [804682533] = {
        ["english"] = { [1] = "The Butcher would speak of 'the blood of innocents,' and his dark master, 'Kirtonos.' Of how he must appease his master.$B$BFinally, the beast was done with his experiments. We had been drained of all life. Our spirits shattered. The sweet embrace of death was upon us and we welcomed it with open arms. But in his infinite cruelty, the Butcher revived us from death's door.$B$BWe were to be kept alive and thrown to his ravenous ghouls. He laughed as he watched the fiends devour our flesh." },
        ["text"] = "М'ясник говорив про «кров невинних» і свого темного господаря — «Кіртоноса». Про те, що мусить задобрити його.$B$BЗрештою потвора завершила свої досліди. З нас висмоктали все життя. Наші духи були зламані. Солодкі обійми смерті вже огортали нас, і ми зустрічали їх із розкритими руками. Та в безмежній жорстокості М'ясник повернув нас із порога смерті.$B$BНас тримали живими, щоб кинути його ненажерливим гулям. Він сміявся, дивлячись, як ті тварюки пожирають нашу плоть.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [61409904] = {
        ["english"] = { [1] = "There is nothing more that I can teach - now get out! And don't even think of approaching Saru, for one as unworthy as you he will use your blood to temper his steel." },
        ["text"] = "Мені більше нічого тебе навчити — геть звідси! І навіть не думай підходити до Сару: такого недостойного, як ти, він використає кров'ю для гартування своєї сталі.",
        ["npcs"] = { [1] = 1383 },
        ["roles"] = { ["greeting"] = true },
    },
    [2553681782] = {
        ["english"] = { [1] = "The Scourge's plague is almost to the turning point; a handful more cauldron subversions will push us over the top!  Be sure to do your part to help out!" },
        ["text"] = "Чума Скари майже на переломному етапі; ще кілька диверсій із котлами — і ми візьмемо гору! Не забудь зробити свій внесок!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1511800282] = {
        ["english"] = { [1] = "This is disturbing. Please continue." },
        ["text"] = "Це тривожно. Продовжуйте, будь ласка.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [2994395919] = {
        ["english"] = { [1] = "Thank you for saving me!$B$BI'm a cook and an alchemist from Stormwind.  I was here looking for local herbs and recipes for my uncle Angus when these quilboar captured me.  If you hadn't come around, I'm sure I'd have ended up in their stew pot!" },
        ["text"] = "Дякую, що врятував мене!$B$BЯ кухар і алхімік зі Штормовію. Я прийшов сюди шукати місцеві трави й рецепти для свого дядька Анґуса, коли ці свинобрази мене схопили. Якби ти не з'явився, певно, я вже варився б у їхньому казані!",
        ["npcs"] = { [1] = 8696 },
        ["roles"] = { ["greeting"] = true },
    },
    [896310898] = {
        ["english"] = { [1] = "The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a bag of some sort." },
        ["text"] = "Щоденник Джендіс Баров переповнений безумними записами про невмерлих. Наприкінці книги, схоже, є кравецька викрійка для створення якоїсь сумки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1059617552] = {
        ["english"] = { [1] = "This is delicate work out here, you know?  It can't just be rushed, or something's likely to get broken.$B$BLike Fuselage's head!$B$BYou might be wondering about my bots?  I'm always working on the Mk. I, and the Mk. II gained sentience for a split-second before his brain capacitor blew out and he went insane!$B$BI decided to skip III and IV, and went straight to the Mk. V - my pride and joy!" },
        ["text"] = "Тут робота тонка, розумієте? Не можна просто все робити похапцем, бо щось обов’язково зламається.$B$BНаприклад, голова Фюзеляжа!$B$BМабуть, вам цікаво, що з моїми роботами? Над Mk. I я працюю постійно, а Mk. II на мить набув свідомості, перш ніж у нього вибухнув мозковий конденсатор і він збожеволів!$B$BЯ вирішив пропустити III та IV і відразу перейти до Mk. V — моєї гордості й радості!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2249332746] = {
        ["english"] = { [1] = "Surely ye didn't think ye would find a town without a resident miner about, did ye?  Yarr can usually be found over at Steelgrill's Depot just outside of Kharanos." },
        ["text"] = "Невже ти думав, що знайдеш містечко без місцевого шахтаря? Ярра зазвичай можна знайти на складі Сталерешета, одразу за Караносом.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [115975708] = {
        ["english"] = { [1] = "The gathering and knowledge of herbs is a specialty of Firodren Mooncaller.  Seek him out in the Temple Gardens in the southwestern area of Darnassus." },
        ["text"] = "Збирання трав і знання про них — спеціалізація Фіродрена Місячного Закликача. Шукай його в Храмових садах на південному заході Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2365754240] = {
        ["english"] = { [1] = "The one that they call Hellscream might be our only hope." },
        ["text"] = "Той, кого звуть Пеклокриком, може бути нашою єдиною надією.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [996721422] = {
        ["english"] = { [1] = "This moonlight will take you to Thunder Bluff.  Use it when you want to leave the festival." },
        ["text"] = "Це місячне сяйво перенесе вас до Громового Бескиду. Скористайтеся ним, коли захочете залишити фестиваль.",
        ["npcs"] = { [1] = 15719 },
        ["roles"] = { ["greeting"] = true },
    },
    [960896957] = {
        ["english"] = { [1] = "This is an exotic sample of flora, unseen in other parts of Teldrassil." },
        ["text"] = "Це незвичайний зразок флори, якого не побачиш в інших частинах Тельдрассіля.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3441474548] = {
        ["english"] = { [1] = "The Plates of Uldum are discs synthesized by the Creators that allow access into the Uldum compound.  These discs house and store specific data related to the Creators' activities here.$B$BPhysically, they are nearly identical in circumference to the disc set you currently possess.  Their markings, however, are directly related to information on Uldum as opposed to the Uldaman complex." },
        ["text"] = "Пластини Ульдума — диски, синтезовані Творцями, що надають доступ до комплексу Ульдум. Ці диски містять і зберігають конкретні дані про діяльність Творців тут.$B$BФізично вони майже однакові за діаметром із набором дисків, який ти вже маєш. Однак їхні позначки стосуються даних про Ульдум, а не комплексу Ульдаман.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2454997695] = {
        ["english"] = { [1] = "That's nice, $N. Go show whatever it is to Vosur over there. He'll answer any questions you have." },
        ["text"] = "Гарно, $N. Віднеси це, що б воно не було, Восуру он там. Він відповість на твої запитання.",
        ["npcs"] = { [1] = 5177 },
        ["roles"] = { ["greeting"] = true },
    },
    [3152756329] = {
        ["english"] = { [1] = "The arcane only corrupts those who are weak. Even if you do not follow the path of the warlock, you would do well to remember that." },
        ["text"] = "Таємна магія розбещує лише слабких. Навіть якщо ти не йдеш шляхом чорнокнижника, тобі варто це пам'ятати.",
        ["npcs"] = { [1] = 459 },
        ["roles"] = { ["greeting"] = true },
    },
    [3791340543] = {
        ["english"] = { [1] = "This is an atrocity." },
        ["text"] = "Це жахливе злодіяння.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [1822324371] = {
        ["english"] = { [1] = "The times we live in are as fickle as the shifting winds, $c.  It is important to remember what is true and lasting in this world, and to preserve that.  Everything else is a waste." },
        ["text"] = "Часи, в які ми живемо, мінливі, наче вітер, $c. Важливо пам'ятати, що в цьому світі істинне й тривке, та берегти це. Решта — марнота.",
        ["npcs"] = { [1] = 3448 },
        ["roles"] = { ["greeting"] = true },
    },
    [474283649] = {
        ["english"] = { [1] = "This is all very interesting but what is it that you want?" },
        ["text"] = "Усе це дуже цікаво, але чого ви від мене хочете?",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["reply"] = true },
    },
    [2062176896] = {
        ["english"] = { [1] = "There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Horde takes time to give something back to these innocents.  This time is called Children's Week.\010" },
        ["text"] = "Війна має свою ціну, $c... і про неї часто забувають. Ця ціна — сироти, діти, що втратили батьків у надто численних конфліктах, які вирують по всьому Азероту. Ті, кому більше нікуди йти, часто живуть тут, доки не стануть достатньо дорослими, щоб дбати про себе.$B$BОдин весняний тиждень на рік Орда намагається щось повернути цим невинним. Цей час називається Дитячим тижнем.\010",
        ["npcs"] = { [1] = 14451 },
        ["roles"] = { ["greeting"] = true },
    },
    [3323827589] = {
        ["english"] = { [1] = "This is a lot to think about." },
        ["text"] = "Тут є над чим подумати.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [3843887419] = {
        ["english"] = { [1] = "There you are.  Are you ready then?  Once we start, there is no turning back." },
        ["text"] = "Ось ти де. То що, готовий? Щойно почнемо — дороги назад не буде.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3859866212] = {
        ["english"] = { [1] = "The first time I saw mushrooms taller than trees, I wasn't so sure I could call this place home. After a while you just stop noticing." },
        ["text"] = "Коли я вперше побачив гриби, вищі за дерева, то не був певен, що зможу назвати це місце домом. А згодом просто перестаєш помічати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3028742564] = {
        ["english"] = { [1] = "The Eastern Pylon accepts blue, yellow, and green crystals.$B$BIt focuses on the energy that can be created using blue crystals as the main source of power. There are two possible effects: one provides bonus to spirit, and one that creates a damaging shield.$B$BCrystal Force requires blue and green crystals. This will provide you with an increase in spirit.$B$BCrystal Spire requires blue and yellow crystals. This will create a shield that does damage to attackers.\010\010" },
        ["text"] = "Східний пілон приймає сині, жовті й зелені кристали.$B$BВін зосереджується на енергії, яку можна створити, використовуючи сині кристали як основне джерело сили. Можливі два ефекти: один дає бонус до духу, другий створює щит, що завдає шкоди.$B$BДля Кришталевої сили потрібні сині й зелені кристали. Вона підвищить твій дух.$B$BДля Кришталевого шпиля потрібні сині й жовті кристали. Він створить щит, що завдаватиме шкоди нападникам.\010\010",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [3326732390] = {
        ["english"] = { [1] = "The West Frostwolf Tower protects the gate between Frostwolf Village and Frostwolf Keep.$B$BIt is controlled by the Horde." },
        ["text"] = "Західна вежа Морозних Вовків захищає браму між селищем Морозних Вовків і їхньою фортецею.$B$BЇї контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2127217253] = {
        ["english"] = { [1] = "The search for my people.  Our struggle against the Alliance.  The war with the ogres and their gronn masters.$B$BAll of these things weigh heavy upon my shoulders, $c.$B$BEven I can use some help from time to time." },
        ["text"] = "Пошуки мого народу. Наша боротьба проти Альянсу. Війна з ограми та їхніми господарями-гроннами.$B$BУсе це важким тягарем лежить на моїх плечах, $c.$B$BНавіть мені час від часу потрібна допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [205145520] = {
        ["english"] = { [1] = "The herbs found in nature can be a powerful ally when combined with respect.  You will want to seek out Bena at her alchemy shop on the middle rise to further your training." },
        ["text"] = "Трави, що ростуть у природі, можуть стати могутніми союзниками, якщо ставитися до них із належною повагою. Для подальшого навчання знайди Бену в її алхімічній крамниці на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [66424675] = {
        ["english"] = { [1] = "The Horde's gathering efforts are completed, $c. Now we bide our time with extra preparations while the Alliance finishes their war collections." },
        ["text"] = "Збір Орди завершено, $c. Тепер ми готуємося додатково й чекаємо, доки Альянс завершить свої воєнні збори.",
        ["npcs"] = { [1] = 15477 },
        ["roles"] = { ["greeting"] = true },
    },
    [3056032715] = {
        ["english"] = { [1] = "There's no loitering, pan handling, cursing, fighting, or anything else you're thinking about doing, allowed in Caer Darrow." },
        ["text"] = "У Каєр-Дарроу заборонено тинятися без діла, жебракувати, лаятися, битися й узагалі робити все, що тобі зараз спало на думку.",
        ["npcs"] = { [1] = 11279, [2] = 11281 },
        ["roles"] = { ["greeting"] = true },
    },
    [1223004948] = {
        ["english"] = { [1] = "This is good stuff!  But it's a little weak.  I think I'll add a little more garlic breath to it..." },
        ["text"] = "Оце добра штука! Але трохи слабенька. Думаю, додам ще трохи часникового подиху...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1048891372] = {
        ["english"] = { [1] = "The battle is over, and the people of Darrowshire are saved." },
        ["text"] = "Битва закінчилась, і жителів Дерроуширу врятовано.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1602825413] = {
        ["english"] = { [1] = "The concern that you show for the welfare of your animal companions is commendable.  Bulrug, on the lower rise, can help you with that.  Seek him out between the bank and the inn." },
        ["text"] = "Твоя турбота про добробут тваринних супутників гідна похвали. Булруґ на нижньому виступі може допомогти. Шукай його між банком і корчмою.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [34729240] = {
        ["english"] = { [1] = "The bank?  Oh, ye mean The Vault!  No safer place to store yer valuables than The Vault. Ye'll find it just northeast of the entrance to Ironforge. " },
        ["text"] = "Банк? А, ти про Сховище! Немає безпечнішого місця для коштовностей, ніж Сховище. Знайдеш його одразу на північний схід від входу до Залізогарта. ",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [4161651523] = {
        ["english"] = { [1] = "This healthy whipper root plant stands as a polar opposite to the sickly taint of corruption that dominates Felwood.  Tender and healthy roots yield delicious tubers that lay on the ground next to the plant." },
        ["text"] = "Ця здорова рослина батожного кореня разюче контрастує з хворобливою скверною, що панує у Скверноліссі. Ніжне здорове коріння дає смачні бульби, які лежать на землі поруч із рослиною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3993055508] = {
        ["english"] = { [1] = "This forest can be confusing! Be careful out there." },
        ["text"] = "У цьому лісі легко заблукати! Будьте обережні.",
        ["npcs"] = { [1] = 12724 },
        ["roles"] = { ["greeting"] = true },
    },
    [1430102097] = {
        ["english"] = { [1] = "The pumpkin head smolders forebodingly..." },
        ["text"] = "Гарбузова голова зловісно тліє...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3933657276] = {
        ["english"] = { [1] = "This forest be a spooky place.  It's full of more bad juju than just the Alliance, so you watch out for yourself." },
        ["text"] = "Цей ліс — моторошне місце. Тут повно лихого джуджу, і не лише від Альянсу, тож бережіть себе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [801141812] = {
        ["english"] = { [1] = "This flight takes you to the far point of the Singing Ridge.  Very dangerous!$B$BFor this one, I'm going to need a signed waiver..." },
        ["text"] = "Цей політ доправить вас до дальнього краю Співучого хребта. Дуже небезпечно!$B$BДля цього мені знадобиться підписана вами відмова від претензій...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [399989181] = {
        ["english"] = { [1] = "The death of our flesh marked the birth of our spirit and our sacred task." },
        ["text"] = "Смерть нашої плоті стала народженням нашого духу й нашого священного обов'язку.",
        ["npcs"] = { [1] = 9034 },
        ["roles"] = { ["greeting"] = true },
    },
    [2938956514] = {
        ["english"] = { [1] = "Tell me, do your feel prepared to face the challenge I have laid out for you? The spirits tell me that you will pass, but do you have faith in them or in yourself?" },
        ["text"] = "Скажи, ти почуваєшся готовим до випробування, яке я тобі приготував? Духи кажуть, що ти впораєшся, та чи віриш ти їм — або собі?",
        ["npcs"] = { [1] = 2998, [2] = 3478 },
        ["roles"] = { ["greeting"] = true },
    },
    [2826517962] = {
        ["english"] = { [1] = "The tides of war have come again. From the cold north, the Lich King's necropolises have laid siege to our lands.  He and his cursed general, Kel'Thuzad, send flying necropolises to invade across the world." },
        ["text"] = "Припливи війни знову накотилися. З холодної півночі некрополі Короля-ліча обложили наші землі. Він і його проклятий генерал Кел'Тузад посилають летючі некрополі вторгатися по всьому світу.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [2002938114] = {
        ["english"] = { [1] = "The Argent Dawn salutes you, $c.  I am Hasana - one of but a few authorized equipment and materiel quartermasters for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Officer Garush.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." },
        ["text"] = "Сріблястий Світанок вітає тебе, $c. Я Гасана — одна з небагатьох уповноважених квартирмейстерів Світанку зі спорядження та припасів.$B$BБорючись зі злом за нашим дорученням і здобуваючи нашу повагу й довіру, ти отримуватимеш жетони доблесті від офіцера Ґаруша. Жетони мають два призначення: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде твоє становище у Світанку, то більше предметів стануть тобі доступні.",
        ["npcs"] = { [1] = 10856 },
        ["roles"] = { ["greeting"] = true },
    },
    [4172658712] = {
        ["english"] = { [1] = "The Captain is busy at the moment.  He's studying maps we recently acquired of the underground silithid hives.  Stay with us if you'd like to help, he'll come out any moment now." },
        ["text"] = "Капітан зараз зайнятий. Він вивчає нещодавно здобуті мапи підземних вуликів силітидів. Якщо хочеш допомогти, лишайся з нами — він ось-ось вийде.",
        ["npcs"] = { [1] = 15443 },
        ["roles"] = { ["greeting"] = true },
    },
    [2794776944] = {
        ["english"] = { [1] = "There are several battlegrounds from which to choose.  To which battlemaster shall I send you?" },
        ["text"] = "Є кілька полів бою на вибір. До якого воєначальника тебе відправити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2411163198] = {
        ["english"] = { [1] = "The place is a bit drafty... but what do I care? I'm dead." },
        ["text"] = "Тут трохи протягує... але мені яка різниця? Я мертвий.",
        ["npcs"] = { [1] = 2399 },
        ["roles"] = { ["greeting"] = true },
    },
    [2123596876] = {
        ["english"] = { [1] = "The Headless Horseman attacks the village!  Someone must save the children and stop him!" },
        ["text"] = "Вершник без голови нападає на селище! Хтось мусить урятувати дітей і зупинити його!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1674802169] = {
        ["english"] = { [1] = "Their day will come, $N.$B$BAnd when it does, I will be there." },
        ["text"] = "Їхній день настане, $N.$B$BІ коли це станеться, я буду там.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1354221084] = {
        ["english"] = { [1] = "That's quite a tale, lord-commander." },
        ["text"] = "Оце історія, лорде-командире.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1387604644] = {
        ["english"] = { [1] = "The altar seems to beckon to you as if it were alive." },
        ["text"] = "Здається, вівтар кличе тебе, ніби він живий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [730685195] = {
        ["english"] = { [1] = "This portal is not like the others that lead back to Azeroth. To maintain it, we must acquire more mana cells.$B$BIt is either that or risk losing our access to the Isle of Quel'Danas and the Sunwell." },
        ["text"] = "Цей портал не такий, як інші, що ведуть назад до Азероту. Щоб підтримувати його, нам потрібно здобувати більше осередків мани.$B$BІнакше ми ризикуємо втратити доступ до острова Кель’Данас і Сонячного Колодязя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [578365611] = {
        ["english"] = { [1] = "There's one in Orgrimmar.  A grunt up there will know what directions to give you.  Just head north up the road here, you can't miss it." },
        ["text"] = "Один такий є в Орґріммарі. Тамтешній рубака підкаже дорогу. Просто йди звідси дорогою на північ — не проминеш.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [751181002] = {
        ["english"] = { [1] = "The inn" },
        ["text"] = "Корчма",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1496, [4] = 1652, [5] = 1735, [6] = 1738, [7] = 1742, [8] = 1743, [9] = 1744, [10] = 1745, [11] = 1746, [12] = 1976, [13] = 2209, [14] = 2210, [15] = 2808, [16] = 3084, [17] = 3212, [18] = 3215, [19] = 3217, [20] = 3218, [21] = 3219, [22] = 3220, [23] = 3221, [24] = 3222, [25] = 3223, [26] = 3224, [27] = 3296, [28] = 3571, [29] = 4262, [30] = 5595, [31] = 5624, [32] = 5725, [33] = 5953, [34] = 6272, [35] = 6740, [36] = 8931, [37] = 12996, [38] = 13076, [39] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [2173871195] = {
        ["english"] = { [1] = "These are dangerous times, $r.  An ancient evil is rising, and it cares not if you're Horde or Alliance." },
        ["text"] = "Небезпечні часи, $r. Прадавнє зло прокидається, і йому байдуже, Орда ти чи Альянс.",
        ["npcs"] = { [1] = 7010 },
        ["roles"] = { ["greeting"] = true },
    },
    [3891378735] = {
        ["english"] = { [1] = "The land is in worse shape than I could've imagined. If the damage continues at this rate, Farahlon -- err, Netherstorm will be nothing but cosmic gravel very soon.$B$BWhere will it stop, I wonder? Perhaps the better question is, 'will it stop?'" },
        ["text"] = "Земля в гіршому стані, ніж я міг уявити. Якщо руйнування триватиме такими темпами, Фаралон — е-е, Бурекрай — дуже скоро перетвориться на космічний щебінь.$B$BЦікаво, де це зупиниться? Хоча краще питання: «чи зупиниться взагалі?»",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3297378901] = {
        ["english"] = { [1] = "That is terrible." },
        ["text"] = "Це жахливо.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["reply"] = true },
    },
    [2111627786] = {
        ["english"] = { [1] = "The footlockers of Kil'sorrow Fortress in Nagrand would provide a considerable challenge to even a rogue of your notable skill." },
        ["text"] = "Скрині у фортеці Кіл'скорботи в Наґранді стануть серйозним випробуванням навіть для розбійника з твоєю відомою майстерністю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1952180961] = {
        ["english"] = { [1] = "Teach me the ways of the spirits." },
        ["text"] = "Навчи мене шляхів духів.",
        ["npcs"] = { [1] = 3030, [2] = 3031, [3] = 3032, [4] = 3062, [5] = 3066, [6] = 3173, [7] = 3344, [8] = 3403, [9] = 13417 },
        ["roles"] = { ["reply"] = true },
    },
    [1970111083] = {
        ["english"] = { [1] = "The goblin racer packs a lot of punch, but the gnomes hid a trick or two in their car..." },
        ["text"] = "Ґоблінська гоночна машина має неабияку силу, але гноми приховали у своїй машині кілька хитрощів...",
        ["npcs"] = { [1] = 4419 },
        ["roles"] = { ["greeting"] = true },
    },
    [3431578091] = {
        ["english"] = { [1] = "There is a mailbox located conveniently right between the Stormwind Bank and The Gilded Rose Inn in the Trade District." },
        ["text"] = "Поштова скринька зручно розташована просто між Банком Штормовію й корчмою «Позолочена троянда» в Торговому районі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4008855969] = {
        ["english"] = { [1] = "Talk about making the wrong investment!$B$BLord Valthalak's dark book of spells fetched a pretty penny in the black market.  It's too bad he didn't take too kindly to getting his possessions stolen.  That stinker got us even after he'd been dead for months!" },
        ["text"] = "Оце так невдала інвестиція!$B$BТемна книга заклять лорда Вальталака пішла на чорному ринку за кругленьку суму. Шкода, що він зовсім не зрадів крадіжці своїх речей. Цей мерзотник дістав нас навіть через кілька місяців після смерті!",
        ["npcs"] = { [1] = 16123 },
        ["roles"] = { ["greeting"] = true },
    },
    [2660806927] = {
        ["english"] = { [1] = "The Silverwing Sentinels shall be in your debt $c.  You will find Elfarran, our battlemaster, inside Stormwind Keep, attending the boy-king's audience.  Goddess watch over you!" },
        ["text"] = "Срібнокрилі Вартові будуть у тебе в боргу, $c. Нашу воєначальницю Ельфарран знайдеш у фортеці Штормовію, на аудієнції в короля-хлопчика. Нехай Богиня оберігає тебе!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2569049712] = {
        ["english"] = { [1] = "The time has come, my $g brother : sister; in arms, to take back the night from the Scourge!" },
        ["text"] = "Час настав, $g мій брате : моя сестро; по зброї, повернути ніч у Скари!",
        ["npcs"] = { [1] = 11053, [2] = 11055 },
        ["roles"] = { ["greeting"] = true },
    },
    [1154152989] = {
        ["english"] = { [1] = "The Stormpike Guard must be destroyed!  Ready for Alterac Valley $c?" },
        ["text"] = "Варту Бурешпиля треба знищити! Готовий до Альтерацької долини, $c?",
        ["npcs"] = { [1] = 347 },
        ["roles"] = { ["greeting"] = true },
    },
    [414686647] = {
        ["english"] = { [1] = "Stay away from Sumi and Tumi. They are....spoken for." },
        ["text"] = "Тримайся подалі від Сумі й Тумі. Вони... вже зайняті.",
        ["npcs"] = { [1] = 1383 },
        ["roles"] = { ["greeting"] = true },
    },
    [1925466347] = {
        ["english"] = { [1] = "The fel crystalforge can be used to transform your apexis shards into unstable flasks of the beast.  These flasks make the imbiber more agile, stronger and heartier.$B$BMake your choice, below." },
        ["text"] = "Сквернокристалокузня може перетворювати апекситові уламки на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип'є, спритнішим, сильнішим і витривалішим.$B$BОбирай нижче.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1136384802] = {
        ["english"] = { [1] = "This cultist is in a deep trance..." },
        ["text"] = "Цей культист перебуває в глибокому трансі...",
        ["npcs"] = { [1] = 16230 },
        ["roles"] = { ["greeting"] = true },
    },
    [2666271580] = {
        ["english"] = { [1] = "This console stands before steaming rubble.  The sounds of an engine can be heard below." },
        ["text"] = "Ця консоль стоїть перед купою паруючих уламків. Знизу чути гуркіт двигуна.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3616160156] = {
        ["english"] = { [1] = "This cherry pie tastes so good, it could make a grown gnome cry." },
        ["text"] = "Цей вишневий пиріг такий смачний, що й дорослий гном може розплакатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2132097006] = {
        ["english"] = { [1] = "Then listen well, $r.$B$BSeveral months ago, the Magistrate of Lakeshire sent envoys to Ironforge, pleading with the King for assistance with the Blackrock incursions coming from Redridge and the Burning Steppes.$B$BPrincess Moira volunteered to help, against my pleadings. I was assigned twenty elite guardsmen to protect the Princess through the perilous journey from the Loch to Lakeshire." },
        ["text"] = "Тоді слухай уважно, $r.$B$BКілька місяців тому магістрат Приозер'я відправив послів до Залізогарта, благаючи Короля про допомогу проти нападів Чорнокаменю з Багряногір'я та Палаючого степу.$B$BПринцеса Мойра добровільно погодилася допомогти, попри мої вмовляння. Мені дали двадцять елітних вартових, щоб провести Принцесу небезпечним шляхом від Лоху до Приозер'я.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [1662536938] = {
        ["english"] = { [1] = "The goblin Steamwheedle Fighting Circuit has begun. You can find Arena Organizers selling arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade's Edge Mountains." },
        ["text"] = "Ґоблінський Бойовий Турнір Парової Шляхти розпочався. Організаторів арен, які продають хартії команд, знайдеш у Пристробляску та біля арен у Наґранді й Лезокраїх горах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [662858951] = {
        ["english"] = { [1] = "The Wildhammer dwarves might have fast steeds, but can those Aerie Peak gryphons stand the heat of The Great Forge?  I think not!" },
        ["text"] = "Дворфи Дикого Молота, може, й мають швидких скакунів, але чи витримають грифони Орлиного Піку жар Великої Кузні? Не думаю!",
        ["npcs"] = { [1] = 1573 },
        ["roles"] = { ["greeting"] = true },
    },
    [3727355025] = {
        ["english"] = { [1] = "Then it is to Taim Ragetotem that you must speak.  Seek him out on the Hunter Rise.", [2] = "Then it is to Taim Ragetotem that you must speak. Seek him out on the Hunter Rise." },
        ["text"] = "Тоді тобі треба поговорити з Таймом Лютим Тотемом. Шукай його на Висоті Мисливців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3106059891] = {
        ["english"] = { [1] = "This board is used by the Steamwheedle representatives at Mudsprocket to post bounties and job notices." },
        ["text"] = "Цю дошку представники Парової Штольні в Бруднолипці використовують для оголошень про винагороди та роботу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3832047824] = {
        ["english"] = { [1] = "Take it easy on old Nass. He's not as young and resilient as he once was." },
        ["text"] = "Не будь надто суворим до старого Насса. Він уже не такий молодий і витривалий, як колись.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2617962294] = {
        ["english"] = { [1] = "This blue leather does draw the eye, I know. You see, we have a great many eager recruits running around here, hunting and slaying with more enthusiasm than wisdom. One must take precautions." },
        ["text"] = "Ця синя шкіра й справді впадає в око, знаю. Розумієте, тут у нас повно завзятих новобранців, які бігають довкола, полюють і вбивають із більшим запалом, ніж розумом. Треба ж якось убезпечитися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3801245296] = {
        ["english"] = { [1] = "The dead rise and seek vengeance on any that dare pass through their domain. Turn back!$B" },
        ["text"] = "Мертві підіймаються й прагнуть помсти всім, хто насмілиться пройти їхніми землями. Поверни назад!$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2388004810] = {
        ["english"] = { [1] = "This bear wanders a path close to where the Talondeep Path lies, due west of Mystral Lake and the Alliance outpost of Silverwind Refuge.  While he is the easiest of the three creatures you will face on the Ashenvale Hunt, he should not be trifled with.  His presence is a constant threat to travelers who sojourn between Ashenvale and the Stonetalon Mountains." },
        ["text"] = "Цей ведмідь блукає стежкою поблизу проходу Глибокого Кігтя, на захід від озера Містрал і альянського форпосту Срібновітряного притулку. Хоча з трьох створінь, з якими ви зіткнетеся під час Ясенедільського полювання, він найпростіший супротивник, недооцінювати його не слід. Його присутність — постійна загроза мандрівникам, що прямують між Ясенедолом і Кам’янистими горами.",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["greeting"] = true },
    },
    [2104689822] = {
        ["english"] = { [1] = "The air battle rages close, $n.  Both we and the Horde send bombers into the Bombardment and the Valley of Lost Hope.  Will you enter the fray?" },
        ["text"] = "Повітряна битва вирує зовсім поруч, $n. І ми, і Орда посилаємо бомбардувальники в Зону обстрілу та Долину Втраченої Надії. Вступиш у бій?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3584115040] = {
        ["english"] = { [1] = "The Sunspire held a beautiful vantage of the Sunwell... once.  Our lives have been turned upside down, $N, but we nonetheless carry on.  It is our way; we are survivors.$B$BIf you are to survive this upheaval... to carry on in your own right, then you MUST learn how to survive.  All blood elves must do this.  You must master your insatiable hungering for magic before it masters you." },
        ["text"] = "Сонячний Шпиль колись відкривав прекрасний вид на Сонячний Колодязь... колись. Наше життя перевернулося догори дриґом, $N, та ми й далі тримаємося. Такий наш шлях; ми — вцілілі.$B$BЯкщо хочеш пережити цей переворот... і далі йти власним шляхом, ти МУСИШ навчитися виживати. Це має зробити кожен ельф крові. Ти мусиш приборкати ненаситний голод до магії, перш ніж він приборкає тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [902730296] = {
        ["english"] = { [1] = "The blessings of Cenarius be yours, $c.  Our leader, Arch Druid Staghelm, guides us and all of Teldrassil to a renewed life!" },
        ["text"] = "Нехай благословення Кенарія буде з тобою, $c. Наш ватажок, Верховний друїд Оленешолом, веде нас і весь Тельдрассіль до нового життя!",
        ["npcs"] = { [1] = 3602, [2] = 4218, [3] = 4219 },
        ["roles"] = { ["greeting"] = true },
    },
    [2865065636] = {
        ["english"] = { [1] = "The Horde Embassy is in the Valley of Strength on the west side." },
        ["text"] = "Посольство Орди розташоване на західному боці Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [4002335389] = {
        ["english"] = { [1] = "Tell me more, Trenton." },
        ["text"] = "Розкажи ще, Трентоне.",
        ["npcs"] = { [1] = 7804 },
        ["roles"] = { ["reply"] = true },
    },
    [1910129549] = {
        ["english"] = { [1] = "That's troll business.  Look for Un'Thuwa in Sen'jin Village down south." },
        ["text"] = "То троляча справа. Шукай Ун'Туву в селищі Сен'джин на півдні.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [46552620] = {
        ["english"] = { [1] = "Their manifest forms weak from eons of battle, imprisoned beneath the world - the world that they themselves created - the corruption of the Titan Shapers would permeate through the surface and befoul the Old Gods.$B$BIt was then and there that the brothers did turn. For five millennia a battle was fought at the core of this world.\010" },
        ["text"] = "Їхні тілесні форми, ослаблені еонами битв і ув'язнені під світом — світом, який вони самі створили, — несли осквернення Титанів-Формотворців до самої поверхні й заражали Старих Богів.$B$BСаме тоді брати відступили від свого шляху. П'ять тисячоліть у ядрі цього світу тривала битва.\010",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [3751521367] = {
        ["english"] = { [1] = "The title is misleading. I'm really a very nice person once you get to know me." },
        ["text"] = "Назва вводить в оману. Насправді я дуже приємна людина, якщо мене пізнати.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [1927698554] = {
        ["english"] = { [1] = "The Shattered Hand will see the Horde to their former glory, unhindered by the timidness of the Warchief." },
        ["text"] = "Розтрощена Десниця поверне Орді колишню славу, не скута боягузтвом Вождя.",
        ["npcs"] = { [1] = 3155, [2] = 3170, [3] = 3327, [4] = 3328 },
        ["roles"] = { ["greeting"] = true },
    },
    [116514906] = {
        ["english"] = { [1] = "Stratholme" },
        ["text"] = "Стратгольм",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [907222297] = {
        ["english"] = { [1] = "Thank you for your help in making the salve, $N. Once it's had a chance to dull the pain, I'm going to see how far I can get on this leg." },
        ["text"] = "Дякую, що допоміг приготувати мазь, $N. Щойно вона трохи втамує біль, спробую подивитися, як далеко зможу зайти на цій нозі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [371303288] = {
        ["english"] = { [1] = "Thank you for rescuing me, $N. I will never forget your courage and determination." },
        ["text"] = "Дякую, що врятував мене, $N. Я ніколи не забуду твоєї відваги й рішучості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [148217843] = {
        ["english"] = { [1] = "This barrel of ale is guarded by Jarven Thunderbrew.  As long as he's in the basement, no barrels may be disturbed." },
        ["text"] = "Цю бочку елю охороняє Джарвен Громовар. Поки він у підвалі, жодної бочки не можна чіпати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3779122427] = {
        ["english"] = { [1] = "Think you could help me to get out of here?" },
        ["text"] = "Гадаєш, зможеш допомогти мені вибратися звідси?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1135844341] = {
        ["english"] = { [1] = "Think you could get me out of here, $c?" },
        ["text"] = "Гадаєш, зможеш витягти мене звідси, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2854596373] = {
        ["english"] = { [1] = "Think him in Royal Quarter.  Kurden Bloodclaw is little orc.", [2] = "Think him in Royal Quarter. Kurden Bloodclaw is little orc." },
        ["text"] = "Думаю, він у Королівському кварталі. Курден Кровокіготь — маленький орк.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3668593655] = {
        ["english"] = { [1] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold latent signatures of magic used by the old Empire.$B$BYou'll more than likely discover three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with some of the finest items we Zandalar have ever crafted.", [2] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold latent signatures of magic used by the old Empire.$B$BYou'll more than likely discover three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with some of the finest items we Zandalar have ever crafted.\010" },
        ["text"] = "Зразки Могутності — рештки давньої Імперії Ґурубаші. Ми, зандалари, шукаємо їх не лише через величезну колекційну цінність, а й тому, що вважаємо: вони зберігають приховані сліди магії старої Імперії.$B$BУ Зул'Ґурубі, найімовірніше, знайдеш три види Зразків: монети, біжу та первісні предмети. Принось їх у потрібній кількості, й отримаєш у нагороду одні з найкращих речей, які коли-небудь створювали зандалари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1516120088] = {
        ["english"] = { [1] = "The mightiest of all the beasts that make up the Ashenvale Hunt, Sharptalon is let to wander freely by the self-proclaimed guardians of this land, the night elves.  Sharptalon patrols for prey to the south of here, taking delight in rending the unsuspecting and unaware traveler limb from limb.$B$BTo bring down such a beast would be the mightiest of hauls, $N.  I wish you luck in the hunt for this creature!" },
        ["text"] = "Наймогутніша з усіх істот Ясенедільського Полювання — Гострокіготь — вільно блукає завдяки самопроголошеним охоронцям цих земель, нічним ельфам. Гострокіготь полює на південь звідси й залюбки розриває необережних мандрівників на шматки.$B$BЗдолати такого звіра — ось справжній трофей, $N. Бажаю удачі на полюванні!",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["greeting"] = true },
    },
    [3190143990] = {
        ["english"] = { [1] = "That's odd." },
        ["text"] = "Дивно.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [489726799] = {
        ["english"] = { [1] = "The zeppelin should have just arrived at Grom'gol... " },
        ["text"] = "Дирижабль щойно мав прибути до Ґром'ґола... ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2018819222] = {
        ["english"] = { [1] = "The merchant known as Griftah has been exiled from this city for his fraudulent activities. We plan to go over these little knick-knacks he sells extremely carefully. Please, leave his stall undisturbed and let us do our work." },
        ["text"] = "Торговця на ім'я Ґріфта вигнали з міста за шахрайство. Ми збираємося дуже ретельно перевірити всі дрібнички, які він продає. Будь ласка, не чіпай його ятку й дай нам працювати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2164714269] = {
        ["english"] = { [1] = "They've been stolen, $r! Three of our most prized volumes. Should you return the tomes, a reward will most certainly be yours." },
        ["text"] = "Їх украли, $r! Три наші найцінніші томи. Якщо повернеш книги, без нагороди точно не лишишся.",
        ["npcs"] = { [1] = 14383 },
        ["roles"] = { ["greeting"] = true },
    },
    [1371275569] = {
        ["english"] = { [1] = "The land of Azshara." },
        ["text"] = "Землі Азшари.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["reply"] = true },
    },
    [2277137978] = {
        ["english"] = { [1] = "The Deathforge is run by the Shadow Council, under the watchful eye of the Legion." },
        ["text"] = "Кузнею Смерті керує Рада Тіней під пильним оком Легіону.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [754751322] = {
        ["english"] = { [1] = "Thank you again for replenishing our healing crystals. I hear that you're helping out all over the place. Keep up the good work!" },
        ["text"] = "Ще раз дякую, що поповнили наш запас цілющих кристалів. Чув, ти допомагаєш усім довкола. Так тримати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1338502744] = {
        ["english"] = { [1] = "The Earth Mother provides, but at times, a $c needs a little extra help to survive. Thus, I am collecting all of the runecloth bandages that we can in preparation for the looming war at Ahn'Qiraj. As of now we have gathered $2089w on our way to collecting a total of $2090w." },
        ["text"] = "Матір-Земля дає нам усе необхідне, але часом $c потребує трохи додаткової допомоги, щоб вижити. Тож я збираю всі бинти з рунічної тканини, які тільки можемо знайти, готуючись до близької війни в Ан'Кіражі. Наразі ми зібрали $2089w із загалом потрібних $2090w.",
        ["npcs"] = { [1] = 15532 },
        ["roles"] = { ["greeting"] = true },
    },
    [3340712239] = {
        ["english"] = { [1] = "They's in Magic Quarter.  Look for them in scary skull building." },
        ["text"] = "Вони в Кварталі Магії. Шукай їх у страшній будівлі з черепом.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3672082921] = {
        ["english"] = { [1] = "The Darkmoon Faire is right now located in Elwynn Forest, just south of Goldshire.  Don't miss it!" },
        ["text"] = "Ярмарок Темного Місяця зараз розташований в Ельвинському лісі, трохи на південь від Злотохрестя. Не пропусти!",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["greeting"] = true },
    },
    [2143395055] = {
        ["english"] = { [1] = "That bum Leland... all he does is sit out on the dock outside the Trade District and fish all day.  I sure hope he's good at it for all the time he spends fishing.  If you want to learn, why don't you go talk to him?" },
        ["text"] = "Той нероба Леланд... цілими днями сидить на причалі за Торговим районом і рибалить. Сподіваюся, він хоч добре це вміє, зважаючи, скільки часу на це витрачає. Якщо хочеш навчитися, чому б не поговорити з ним?",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [943487604] = {
        ["english"] = { [1] = "They're giving candies and treats at the inn!  Guardian Grimwatch says if they don't give us a treat... then we get to play a trick on them!" },
        ["text"] = "У корчмі роздають цукерки й ласощі! Вартовий Похмурозір каже: якщо не дадуть ласощі... тоді ми влаштуємо їм капость!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [688946720] = {
        ["english"] = { [1] = "The tag on this present reads: \"For ages 20 and up.\"" },
        ["text"] = "На бирці цього подарунка написано: «Для осіб від 20 років».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1401646402] = {
        ["english"] = { [1] = "Talk to Saru Steelfury at The Burning Anvil.  Go to the Valley of Honor.  It's at the end of the path to the right of Red Canyon Mining." },
        ["text"] = "Поговори із Сару Сталелюттю в «Палаючому ковадлі». Іди до Долини Честі. Це в кінці стежки праворуч від копальні Червоного Каньйону.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1952832665] = {
        ["english"] = { [1] = "Thank you, mortal. There is but one service that I may offer to you before I return to the Dream.$B$BThe door to Zevrim's master, Alzzin, blocks your path. I shall act as your instrument of destruction. The door will be opened, I merely await your command." },
        ["text"] = "Дякую, смертний. Перед поверненням до Сну я можу надати тобі лише одну послугу.$B$BДвері до господаря Зевріма, Алззіна, перекривають твій шлях. Я стану твоїм знаряддям руйнування. Двері буде відчинено — я лише чекаю твого наказу.",
        ["npcs"] = { [1] = 11491, [2] = 14241 },
        ["roles"] = { ["greeting"] = true },
    },
    [3686714343] = {
        ["english"] = { [1] = "Then let us pretend that you undergo the long and arduous task of creating the bane necessary to break through the demonic wards placed upon the triad. What would be your next course of action? To face the Defiler in his lair?$B$B<Loramus laughs.>\010" },
        ["text"] = "Тоді уявімо, що ти виконав довге й виснажливе завдання та створив згубу, потрібну для прориву демонічних оберегів навколо тріади. Що робитимеш далі? Підеш до Осквернителя в його лігво?$B$B<Лорамос сміється.>\010",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [2526073786] = {
        ["english"] = { [1] = "The High Priestess could not leave Darnassus. Fandral is in a very foul mood." },
        ["text"] = "Верховна жриця не могла покинути Дарнас. Фандрал зараз у дуже поганому настрої.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3559069520] = {
        ["english"] = { [1] = "The day of judgement has come, fiend!  I challenge you to battle!" },
        ["text"] = "День суду настав, потворо! Я викликаю тебе на бій!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [261232748] = {
        ["english"] = { [1] = "They say the barrel and buckets are for fighting fires.  Are you a fire fighter?" },
        ["text"] = "Кажуть, бочка й відра потрібні для гасіння пожеж. Ти пожежник?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3340782805] = {
        ["english"] = { [1] = "Standing this close to the blade that ended my life... The pain... It is renewed." },
        ["text"] = "Стояти так близько до клинка, що обірвав моє життя... Біль... Він повернувся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1339048016] = {
        ["english"] = { [1] = "Thanks to you, we'll be able to proceed with our plans for the Ruins of Farahlon." },
        ["text"] = "Завдяки тобі ми зможемо продовжити наші плани щодо руїн Фаралону.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2058442077] = {
        ["english"] = { [1] = "That cursed Jonah Sterling will lead us right into doom.  If he spent more time outside of his cave, he would realize the folly of attacking professional navies in a time of war." },
        ["text"] = "Цей проклятий Джона Стерлінґ приведе нас просто до загибелі. Якби він частіше вилазив зі своєї печери, то зрозумів би всю дурість нападів на професійні флоти під час війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3489509617] = {
        ["english"] = { [1] = "The best defense is a good offense; anyone can tell you that." },
        ["text"] = "Найкращий захист — це напад; це всі знають.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3127072160] = {
        ["english"] = { [1] = "The egg appears resilient as an egg of the Black Dragonflight rightfully should.  Perhaps if you were to place a great many apexis shards next to it, their vibrations would cause it to crack open?$B$BToo bad that you don't appear to have the thirty-five apexis shards necessary to do the job." },
        ["text"] = "Яйце виглядає міцним, як і належить яйцю Чорної драконячої зграї. Можливо, якщо покласти поруч багато апекситових уламків, їхні коливання змусять шкаралупу тріснути?$B$BШкода, але в тебе, схоже, немає потрібних тридцяти п'яти апекситових уламків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3650419335] = {
        ["english"] = { [1] = "The Scourge are a fearless machine set to bring about the end of all life on this world." },
        ["text"] = "Скара — безстрашна машина, створена, щоб покласти край усьому життю в цьому світі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3000138133] = {
        ["english"] = { [1] = "The entrance to Warsong Gulch stands before you. Will you fight the wretched Alliance there?" },
        ["text"] = "Перед тобою вхід до Ущелини Пісні Війни. Битимешся там із жалюгідним Альянсом?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3998662859] = {
        ["english"] = { [1] = "Sprinkle some of the reindeer dust onto Metzen." },
        ["text"] = "Посипте Метцена оленячим пилом.",
        ["npcs"] = { [1] = 15664 },
        ["roles"] = { ["reply"] = true },
    },
    [2798457173] = {
        ["english"] = { [1] = "The forest told me of your presence, but not why you were here. So, speak and enlighten me." },
        ["text"] = "Ліс розповів мені про твою присутність, але не сказав, навіщо ти тут. Тож говори й просвіти мене.",
        ["npcs"] = { [1] = 7870 },
        ["roles"] = { ["greeting"] = true },
    },
    [3085967836] = {
        ["english"] = { [1] = "The ground upon which the Scholomance was built was given to Kel'Thuzad by the Barov family. In exchange for this land - a place where the Cult of the Damned could learn the foul magics of the Scourge - Kel'Thuzad granted the Barov's immortality through undeath.$B$BIt is in Shadow Vault that you will find both the skin of shadow and its owner, Lady Illucia Barov.$B$BA finer mirror for the vain and dead never existed." },
        ["text"] = "Землю, на якій збудовано Некроситет, родина Барових віддала Кел'Тузаду. В обмін на місце, де Культ Проклятих міг вивчати огидну магію Скари, Кел'Тузад дарував Баровим безсмертя через невмертя.$B$BУ Сховищі Тіней ти знайдеш і шкіру тіні, і її власницю — пані Іллюсію Барову.$B$BКращого дзеркала для марнославних мерців годі й шукати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3617013472] = {
        ["english"] = { [1] = "They know how to throw a party here in Moonglade.  Who would have thought so?" },
        ["text"] = "Тут, у Місячній галявині, вміють влаштовувати свята. Хто б міг подумати?",
        ["npcs"] = { [1] = 15694 },
        ["roles"] = { ["greeting"] = true },
    },
    [1720371276] = {
        ["english"] = { [1] = "The Lunar Festival celebration being held by the druids is taking place in Moonglade. If that's too far for you to travel, they are offering transportation from the moonwell at the Park." },
        ["text"] = "Місячний фестиваль, який проводять друїди, відбувається в Місячній галявині. Якщо це надто далеко, вони пропонують перевезення від місячного колодязя в Парку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2781711271] = {
        ["english"] = { [1] = "Studying and understanding the Colossus will give us a needed advantage over the Qiraji." },
        ["text"] = "Вивчення й розуміння Колоса дасть нам необхідну перевагу над кіражами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [962511395] = {
        ["english"] = { [1] = "Stonetalon Mountain has many perilous caves through out this region.  Exploring these caves can hold many adventures for those willing to risk life for glory.$B$B$C, perhaps you seek riches that only following your heart and soul can garnish." },
        ["text"] = "У Кам'янистих горах по всьому краю безліч небезпечних печер. Їх дослідження обіцяє чимало пригод тим, хто готовий ризикувати життям заради слави.$B$B$C, можливо, ти шукаєш багатств, які здобувають лише ті, хто йде за покликом серця й душі.",
        ["npcs"] = { [1] = 11861 },
        ["roles"] = { ["greeting"] = true },
    },
    [4166006028] = {
        ["english"] = { [1] = "The humans definitely need all of our help in Arathi Basin.  The one that you wish to speak to is named Keras Wolfheart.  He stands ready to assist you on the Warrior's Terrace." },
        ["text"] = "Людям справді потрібна вся наша допомога в Низині Араті. Того, з ким треба поговорити, звати Керас Вовчесерд. Він чекає на Терасі Воїнів і готовий допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1067660452] = {
        ["english"] = { [1] = "There is nothing left for us here." },
        ["text"] = "Тут для нас нічого не лишилося.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4161475364] = {
        ["english"] = { [1] = "Thank you $N!  You will find Keras Wolfheart on the Warrior's Terrace near the trainers there.  He will guide your way to Arathi Basin.  Good luck and great honor upon thee." },
        ["text"] = "Дякую, $N! Кераса Вовчесерда знайдеш на Терасі Воїнів біля тамтешніх наставників. Він покаже тобі шлях до Низини Араті. Удачі тобі й великої честі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [810229665] = {
        ["english"] = { [1] = "Then it is with great pride that I tell you that Brakgul Deathbringer stands ready in the Hall of Arms to aid you on your way to Warsong Gulch.  Seek him out in the Valley of Honor." },
        ["text"] = "Тоді з великою гордістю повідомляю: Бракґул Смертеносець чекає в Залі Зброї й готовий допомогти тобі дістатися Ущелини Пісні Війни. Шукай його в Долині Честі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3930980167] = {
        ["english"] = { [1] = "That all sounds very complicated..." },
        ["text"] = "Усе це звучить дуже складно...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2205325457] = {
        ["english"] = { [1] = "The Fanglords are dead! All hope is not lost!$b$bThe awakening ritual is quite complex, however. It cannot be done alone.$b$bI will handle all of the necessary preparations but I will need you to protect me. The nightmares summoned from Naralex's journey through the Emerald Dream prove to be quite formidable. Without your help, this mission is doomed.$b$bWhen you are ready to defend me, say the word, and I shall lead the way to Naralex's chamber." },
        ["text"] = "Володарі Ікла мертві! Не вся надія втрачена!$b$bТа ритуал пробудження дуже складний. Самотужки його не провести.$b$bЯ зроблю всі потрібні приготування, але мені знадобиться твій захист. Кошмари, викликані мандрівкою Наралекса крізь Смарагдовий Сон, надзвичайно небезпечні. Без твоєї допомоги місія приречена.$b$bКоли будеш готовий мене захищати, скажи слово, і я поведу тебе до покоїв Наралекса.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [17025135] = {
        ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" },
        ["text"] = "Великі війни, може, й скінчилися — поки що, — але майстерність треба підтримувати гострою!",
        ["npcs"] = { [1] = 912, [2] = 1229, [3] = 1901 },
        ["roles"] = { ["greeting"] = true },
    },
    [1877609455] = {
        ["english"] = { [1] = "The work that you did for me at the Ruins of Farahlon has got me back on schedule.  I'm assembling my team to head out there now.$B$BThank you, $N." },
        ["text"] = "Те, що ти зробив для мене в руїнах Фаралону, повернуло мене до графіка. Я вже збираю команду, щоб вирушити туди.$B$BДякую, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2985011048] = {
        ["english"] = { [1] = "There are only 3 kinds of people in this world: competitors, customers, and employees. Competitors are to be crushed ruthlessly, customers indulged, and employees strictly supervised.$B$BIndependent contractors are a myth.They want to be paid better than employees, but treated like customers. Never trust one who calls himself by that title." },
        ["text"] = "У світі є лише три типи людей: конкуренти, клієнти й працівники. Конкурентів треба безжально нищити, клієнтів — задовольняти, а працівників — суворо контролювати.$B$BНезалежні підрядники — міф. Вони хочуть отримувати більше, ніж працівники, але щоб до них ставилися як до клієнтів. Ніколи не довіряй тому, хто так себе називає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1246606016] = {
        ["english"] = { [1] = "They hand the corpses to me, I toss them in the pit." },
        ["text"] = "Вони віддають мені трупи, а я кидаю їх у яму.",
        ["npcs"] = { [1] = 11038 },
        ["roles"] = { ["greeting"] = true },
    },
    [3222584386] = {
        ["english"] = { [1] = "Throm'ka, $gbrother:sister;! Welcome to Outland. The Horde needs all the strength it can muster in this broken world. I promise you, if it's glorious battle you've come seeking, you'll have your fill of it here." },
        ["text"] = "Тром’ка, $gбрате:сестро;! Ласкаво просимо до Позамежжя. Орді потрібна вся сила, яку вона може зібрати в цьому розбитому світі. Обіцяю: якщо ви прийшли сюди по славну битву, тут матимете її досхочу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [639893012] = {
        ["english"] = { [1] = "They're going to show fireworks all night long.  From 6PM until dawn, the sky will blaze over Booty Bay!" },
        ["text"] = "Феєрверки запускатимуть усю ніч. Від 18:00 до світанку небо над Бухтою Наживи палатиме!",
        ["npcs"] = { [1] = 15723 },
        ["roles"] = { ["greeting"] = true },
    },
    [1343580954] = {
        ["english"] = { [1] = "Still alive? You do surprise. Watch me as I flee!" },
        ["text"] = "Досі живий? Ти дивуєш. А тепер дивись, як я тікаю!",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["greeting"] = true },
    },
    [3201933447] = {
        ["english"] = { [1] = "Sylann, one of the finest cooks in the city, can be found upstairs in the Wayfarer's Rest tavern. You can purchase cooking supplies from here assistant there, too." },
        ["text"] = "Сіланн, одна з найкращих кухарок міста, живе нагорі в таверні «Притулок Подорожнього». Там же в її помічниці можна придбати кухарські припаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1166198894] = {
        ["english"] = { [1] = "They say these fireworks use the power of the moon!" },
        ["text"] = "Кажуть, ці феєрверки використовують силу місяця!",
        ["npcs"] = { [1] = 15905 },
        ["roles"] = { ["greeting"] = true },
    },
    [335292721] = {
        ["english"] = { [1] = "There aren't many of us left, $N.  The return of our old enemy is a cause for great concern." },
        ["text"] = "Нас залишилося небагато, $N. Повернення нашого давнього ворога — серйозний привід для тривоги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1867012207] = {
        ["english"] = { [1] = "The Bash'ir crystalforge can be used to transform your apexis shards into unstable flasks of the sorcerer.  These flasks make the imbiber more intelligent, heartier, and increase the effectiveness of their damaging and healing magics.$B$BIt appears, however, that you do not have the requisite ten shards to purchase even a single flask." },
        ["text"] = "Кристалокузня Баш'іру може перетворювати твої апекситові уламки на нестабільні флакони чаклуна. Ці флакони роблять того, хто їх вип'є, розумнішим і витривалішим, а також посилюють його закляття шкоди й зцілення.$B$BАле, схоже, в тебе немає необхідних десяти уламків навіть на один флакон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1741479422] = {
        ["english"] = { [1] = "Thanks, $N! You're the hero of Ungoro Crater!" },
        ["text"] = "Дякую, $N! Ти герой кратера Ун'Ґоро!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1622429277] = {
        ["english"] = { [1] = "The Darkmoon Faire is the greatest event on all of Azeroth!" },
        ["text"] = "Ярмарок Темного Місяця — найвеличніша подія в усьому Азероті!",
        ["npcs"] = { [1] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [792988019] = {
        ["english"] = { [1] = "They are exactly what you need to destroy in order to free the regiment! As I had told you earlier, Kirith had a plan.$B$BEach of the servants does have a weakness. Punish their physical form in proximity of their stones until they are near the state of disintegration. It is at that point, and that point alone, that the stones of binding are vulnerable to attack. You must hurry to destroy the stones, however, as once the enslaved regain their composure, they will be invulnerable to harm once more." },
        ["text"] = "Саме їх треба знищити, щоб звільнити полк! Як я вже казав, Кіріт мав план.$B$BКожен зі слуг має слабкість. Пошкодь їхню тілесну форму біля каменів, доки вони майже не розпадуться. Лише в цю мить камені зв'язування стають вразливими. Та поспішай їх знищити: щойно поневолені оговтаються, вони знову стануть невразливими.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [807048152] = {
        ["english"] = { [1] = "That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.  \010\010The Hall of Mysteries is just north of the gates of Ironforge." },
        ["text"] = "Та маленька чарівниця Бінк із Зали Таємниць, певно, зможе допомогти тобі з будь-якими магічними справами.  \010\010Зала Таємниць розташована одразу на північ від брами Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1978831227] = {
        ["english"] = { [1] = "The Silverwing Sentinels can use all the help they can get in their fight against the Warsong Outriders.  $N, go to Stormwind Keep and speak with Elfarran if you wish to assist them.", [2] = "The Silverwing Sentinels can use all the help they can get in their fight against the Warsong Outriders. $N, go to Stormwind Keep and speak with Elfarran if you wish to assist them." },
        ["text"] = "Срібнокрилим Вартовим потрібна будь-яка допомога в боротьбі проти Вершників Пісні Війни. $N, іди до фортеці Штормовію й поговори з Ельфарран, якщо хочеш їм допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [71917285] = {
        ["english"] = { [1] = "The siphoned energies would sustain the Highborne's magic, allowing those within the walls of Eldre'Thalas to feed their endless and growing magical pangs.$B$BThousands of years passed and the power required to keep Immol'thar imprisoned while sustaining life within Eldre'Thalas, began to shift. The cost to keep Immol'thar bound grew to overshadow the rate at which energy could be siphoned and distributed. The once net gain turned to loss." },
        ["text"] = "Висмоктана енергія підтримувала магію Високородних, дозволяючи мешканцям Елдре'Таласа втамовувати невпинний і дедалі сильніший магічний голод.$B$BМинали тисячоліття, й співвідношення сили, потрібної для утримання Імол'тара та підтримки життя в Елдре'Таласі, змінилося. Вартість утримання демона стала перевищувати кількість енергії, яку можна було висмоктувати й розподіляти. Колишній прибуток перетворився на збиток.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [4093267254] = {
        ["english"] = { [1] = "They almost sent my brother, Loksey, to this gathering. He cannot even take care of his hounds, let alone represent the Scarlet Crusade in a competent manner." },
        ["text"] = "На ці збори ледь не послали мого брата Локсі. Він навіть власних гончаків не здатен доглянути, не те що гідно представляти Багряний Похід.",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["greeting"] = true },
    },
    [1990286784] = {
        ["english"] = { [1] = "This sounds like a task worthy of the new king!" },
        ["text"] = "Це завдання гідне нового короля!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["reply"] = true },
    },
    [1741070686] = {
        ["english"] = { [1] = "There have been some complaints filed about this... individual. I'm told he's something of a shady character. I am here to determine whether or not this business of his is legitimate... and take action if it proves otherwise." },
        ["text"] = "На цього... суб'єкта надійшло кілька скарг. Кажуть, персонаж він доволі підозрілий. Я тут, щоб з'ясувати, чи законна його справа... і вжити заходів, якщо ні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1751793773] = {
        ["english"] = { [1] = "The Headless Horseman's undead mind is obsessed!  During Hallow's End, his attacks on this village are frequent, and terrible." },
        ["text"] = "Невмерлий розум Вершника без голови охоплений нав'язливою манією! Під час Тиквовину він часто й жахливо нападає на це селище.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4176004166] = {
        ["english"] = { [1] = "These Tears of the Goddess have been blessed by Elune, and their power will help you combat Archimonde's vile magics. Use their power well." },
        ["text"] = "Ці Сльози Богині благословила Елуна, і їхня сила допоможе тобі протистояти мерзотній магії Архімонда. Користуйся нею мудро.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2608773305] = {
        ["english"] = { [1] = "These Runestones protect the lands in Eversong from becoming tainted by the Scourge.  The Western Runestone failed long ago, forcing us to burn the ground around it.$B$BAs long as I live I won't allow the remaining Runestones to fail us.  That is my oath." },
        ["text"] = "Ці рунічні камені захищають землі Вічноспіву від осквернення Скарою. Західний рунічний камінь давно вийшов з ладу, тож нам довелося випалити землю навколо нього.$B$BПоки я живий, не дозволю, щоб решта рунічних каменів нас підвели. Це моя клятва.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3540980879] = {
        ["english"] = { [1] = "Tell me about the Cult of the Damned." },
        ["text"] = "Розкажи мені про Культ Проклятих.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [74935143] = {
        ["english"] = { [1] = "The waters of Westfall is where you must search, due west-northwest of where the Gold Coast Quarry meets with the shore.  An anchor shows where a boat has sunk beyond it, deep within the water.  The underwater pressure is fierce here; swimming too far will crush even the mightiest swimmer from fatigue.  $B$BLook for a natural formation to aid you, $N - a bubbly fissure is near here, offering deep-water swimmers a chance for renewed breath.$b" },
        ["text"] = "Шукати треба у водах Західного краю, точно на захід-північний захід від місця, де кар'єр Золотого узбережжя виходить до берега. Якір позначає місце, де далі в морі затонув човен, глибоко під водою. Тиск там шалений; якщо заплисти надто далеко, навіть найсильнішого плавця виснаження розчавить. $B$BШукай природну допомогу, $N — неподалік є тріщина з бульбашками, де глибоководний плавець може знову набрати повітря.$b",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["greeting"] = true },
    },
    [3643178581] = {
        ["english"] = { [1] = "This was the Ashbringer, fool! As the Scourge began to materialize around us, Mograine's blade began to glow... to hum... the younger Mograine would take that as a sign to make his escape. They descended upon us with a hunger the likes of which I had never seen. Yet..." },
        ["text"] = "Це був Попелитель, дурню! Коли навколо нас почала матеріалізуватися Скара, клинок Моґрейна засвітився... загудів... Молодший Моґрейн сприйняв це як знак до втечі. Вони накинулися на нас із голодом, якого я ще ніколи не бачив. І все ж...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [362134211] = {
        ["english"] = { [1] = "Thank you for your inquiry, $c, but we have all of the spotted yellowtail necessary. There are others here though that may still be gathering materiel for the upcoming war. Seek them out, and may the goddess shine upon you." },
        ["text"] = "Дякую за цікавість, $c, але ми вже маємо всю потрібну плямисту жовтохвостку. Проте інші тут, можливо, досі збирають припаси для майбутньої війни. Знайди їх, і нехай богиня осяє твій шлях.",
        ["npcs"] = { [1] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [1297651344] = {
        ["english"] = { [1] = "The presence of blue dragons." },
        ["text"] = "Присутність синіх драконів.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["reply"] = true },
    },
    [176668405] = {
        ["english"] = { [1] = "There are still lessons you must learn from others before my knowledge may be shared with you. Be diligent, and do not give up hope." },
        ["text"] = "Тобі ще треба засвоїти уроки від інших, перш ніж я зможу поділитися своїми знаннями. Будь старанним і не втрачай надії.",
        ["npcs"] = { [1] = 11073 },
        ["roles"] = { ["greeting"] = true },
    },
    [2739649640] = {
        ["english"] = { [1] = "The Lich King's cruel reign has inflicted great suffering on all of Northrend's inhabitants, particularly the children. If you are a friend to the Oracles or Frenzyheart Tribe of Sholazar, perhaps you might consider caring for an orphan for a week." },
        ["text"] = "Жорстоке правління Короля-ліча принесло великі страждання всім мешканцям Нортренду, особливо дітям. Якщо ти друг Оракулів або племені Шаленого Серця з Шолазару, можливо, погодишся доглянути сироту протягом тижня.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2989844753] = {
        ["english"] = { [1] = "The wisps and I watch the seas for any lost souls." },
        ["text"] = "Ми з вогниками стежимо за морем, шукаючи загублені душі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2550128662] = {
        ["english"] = { [1] = "The Winterfall furbolg that reside here in Winterspring were once our allies... But one day, that all changed.$B$BDriven by the strange demands of their high chief, they began to attack all others that they came in contact with, including our tribe. They keep to themselves now..." },
        ["text"] = "Фурболґи Зимопаду, що живуть тут, у Зимоключі, колись були нашими союзниками... Та одного дня все змінилося.$B$BПідкорившись дивним вимогам свого верховного вождя, вони почали нападати на всіх, кого зустрічали, зокрема на наше плем'я. Тепер вони тримаються осторонь...",
        ["npcs"] = { [1] = 11556 },
        ["roles"] = { ["greeting"] = true },
    },
    [1136487929] = {
        ["english"] = { [1] = "The elements are with us in force, $N. With their help, we will do all that is in our power to stop Varimathras and Putress! LOK'TAR OGAR!" },
        ["text"] = "Стихії з нами й підтримують нас усією силою, $N. З їхньою допомогою ми зробимо все можливе, щоб зупинити Варіматраса й Путресса! ЛОК'ТАР ОҐАР!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2809011999] = {
        ["english"] = { [1] = "These papers are guarded.  Speak with Zamek to create a distraction!" },
        ["text"] = "Ці папери охороняють. Поговори із Замеком, щоб влаштувати відволікання!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1074024536] = {
        ["english"] = { [1] = "These orcs must really be eager to stake their claim in Outland! If I told you how much they were paying for my allegiance, you'd kill me out of jealousy!" },
        ["text"] = "Ці орки справді дуже хочуть застовпити собі місце в Позамежжі! Якби я сказав, скільки вони платять мені за вірність, ти б убив мене від заздрощів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2872589519] = {
        ["english"] = { [1] = "Sul'thraze... the first time I heard the word uttered I was around your age. It meant nothing to me then, as it means nothing to you now. It was not until a warband of trolls coming from Zul'Farrak laid waste to the land that I understood... and feared.$B$BMany will tell you that the Splitblade of Suffering does not exist. That it's a myth; a rumor started to scare children 'straight.' But believe me, $r, it exists.$B$B<Trenton loses focus as he runs his hand across the jagged scar on his face.>" },
        ["text"] = "Суль'траз... уперше я почув це слово, коли був приблизно твого віку. Тоді воно нічого для мене не означало — так само, як і для тебе зараз. Лише коли загін тролів із Зул'Фаррака спустошив ці землі, я зрозумів... і злякався.$B$BБагато хто скаже, що Розколотого Клинка Страждань не існує. Що це міф, чутка, вигадана, аби лякати неслухняних дітей. Але повір мені, $r, він існує.$B$B<Трентон завмирає, проводячи рукою по рваному шраму на обличчі.>",
        ["npcs"] = { [1] = 7804 },
        ["roles"] = { ["greeting"] = true },
    },
    [4034334042] = {
        ["english"] = { [1] = "These once beautiful woods suffer under a terrible curse!  Corrupting forces twist the life here into shadows of their former selves.  If you are not an agent of this corruption, then perhaps you can aid me in reclaiming Felwood!" },
        ["text"] = "Ці колись прекрасні ліси потерпають від страшного прокляття! Осквернювальні сили спотворюють усе живе, перетворюючи на тінь колишньої суті. Якщо ти не служиш цьому оскверненню, можливо, допоможеш мені повернути Сквернолісся!",
        ["npcs"] = { [1] = 9528, [2] = 9529 },
        ["roles"] = { ["greeting"] = true },
    },
    [1212795550] = {
        ["english"] = { [1] = "The markings on this tablet show ancient diagrams and dire words of power, used to create  Gurubashi Mojo Madness..." },
        ["text"] = "Позначки на цій табличці утворюють стародавні схеми й зловісні слова сили, які використовуються для створення Ґурубашського Божевілля Моджо...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2472327803] = {
        ["english"] = { [1] = "These monsters killed my father and kidnapped my sister.  They're going to pay for this!" },
        ["text"] = "Ці чудовиська вбили мого батька й викрали сестру. Вони за це заплатять!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1066347418] = {
        ["english"] = { [1] = "The strongest hides come from those kodo that have laid themselves to rest in this wasteland." },
        ["text"] = "Найміцніші шкури — у тих кодо, які знайшли останній спочинок у цій пустці.",
        ["npcs"] = { [1] = 3703, [2] = 8153 },
        ["roles"] = { ["greeting"] = true },
    },
    [4033529821] = {
        ["english"] = { [1] = "Take my advice, don't sit close to the shadows." },
        ["text"] = "Послухай моєї поради: не сідай близько до тіней.",
        ["npcs"] = { [1] = 1305 },
        ["roles"] = { ["greeting"] = true },
    },
    [1344650236] = {
        ["english"] = { [1] = "These great beasts know paths that ye can't find on foot, they'll get ye there fast and maybe show ye something new at the same time." },
        ["text"] = "Ці великі звірі знають шляхи, яких пішки не знайдеш. Вони швидко доправлять тебе й, може, дорогою покажуть щось нове.",
        ["npcs"] = { [1] = 352 },
        ["roles"] = { ["greeting"] = true },
    },
    [1736848788] = {
        ["english"] = { [1] = "The Dude, over yonder, is pretty upset about his rug." },
        ["text"] = "Той Чувак он там дуже засмучений через свій килим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3439793923] = {
        ["english"] = { [1] = "The armor of Redemption was worn by our most pious knights - armor worthy of the Lightbringer himself!$B$BThousands fell in the last war; their vestments stripped from their corpses and taken to the dread citadel of Naxxramas.$B$BIt is said that the death knights of Naxxramas corrupt the Redemption plate mail for their own use.$B$BSuch tragedy... " },
        ["text"] = "Обладунки Спокути носили наші найпобожніші лицарі — обладунки, гідні самого Світлоносця!$B$BТисячі полягли в останній війні; їхні шати зняли з тіл і забрали до моторошної цитаделі Наксрамаса.$B$BКажуть, лицарі смерті Наксрамаса оскверняють латні обладунки Спокути для власних потреб.$B$BЯка трагедія... ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [484096289] = {
        ["english"] = { [1] = "The zeppelin should just have arrived at Undercity." },
        ["text"] = "Дирижабль щойно мав прибути до Підмістя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1683861263] = {
        ["english"] = { [1] = "These fireworks sure make a nice BOOM, don't you think?" },
        ["text"] = "Ці феєрверки добряче БАБАХАЮТЬ, правда?",
        ["npcs"] = { [1] = 15906 },
        ["roles"] = { ["greeting"] = true },
    },
    [855391072] = {
        ["english"] = { [1] = "There is much work left to be done, $N! Continue to strike down our enemies!" },
        ["text"] = "Ще багато роботи, $N! Продовжуй нищити наших ворогів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1274240864] = {
        ["english"] = { [1] = "These dwarves are the same ones today, yes?  Do dwarves maintain any other links to the Earthen?" },
        ["text"] = "Це ті самі дворфи, що й сьогодні, так? Дворфи зберігають якісь інші зв'язки із земельниками?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [1656509535] = {
        ["english"] = { [1] = "Teach you the ways of gnomish engineering? Not going to happen! Not this gnome, anyway. You have a stink on you, $N. Maybe this is the pity talking but I will offer some advice.$B$BIn the Tanaris desert you'll find a hut that belongs to Narain Soothfancy. In that hut is a magical book that has been known to do wonderous things. Find that book and you may yet learn the gnomish way." },
        ["text"] = "Навчити тебе гномської інженерії? І не мрій! Принаймні не від цього гнома. Від тебе тхне, $N. Може, це жалість у мені говорить, але я дам тобі одну пораду.$B$BУ пустелі Танаріс знайдеш хатину Нарайна Всезная. У ній є магічна книга, здатна творити дивовижні речі. Знайди її — і, можливо, ще навчишся гномського ремесла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1097502439] = {
        ["english"] = { [1] = "The Forest Lord is aware of the destruction in this valley, $N. Soon we must make our way to the Circle of Calling. Prepare yourself!" },
        ["text"] = "Володар Лісу знає про руйнування в цій долині, $N. Незабаром нам треба вирушити до Кола Виклику. Приготуйся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3818212959] = {
        ["english"] = { [1] = "These druids have tapped a tremendous source of power!  They can turn into animals... project  lightning and intense moonlight... I must discover how they do it!$B$BPerhaps they're wearing batteries underneath those robes..." },
        ["text"] = "Ці друїди під'єдналися до неймовірного джерела сили! Вони можуть перетворюватися на тварин... метати блискавки й потужне місячне світло... Я мушу з'ясувати, як вони це роблять!$B$BМоже, під мантіями в них батарейки...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [592819250] = {
        ["english"] = { [1] = "The Lorekeeper is an ancient. He has served under our glorious Queen!" },
        ["text"] = "Хранитель знань — один із Древніх. Він служив нашій славетній Королеві!",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [1096189619] = {
        ["english"] = { [1] = "These are good blades you make, $N. Cut a stone and still sharp enough to slit a throat. I have seen better though, an orc named Kelgrum Bloodaxe makes them, go and learn all he can teach you." },
        ["text"] = "Добрі клинки ти робиш, $N. Камінь розрубають і все одно лишаються гострими, щоб перерізати горло. Але я бачив і кращі. Їх кує орк на ім'я Келґрум Кровосокира. Іди й навчися в нього всього, що зможеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1435073006] = {
        ["english"] = { [1] = "The Orgrimmar Auction House is in the Valley of Strength.  Look for it on the east side next to Boomstick Imports." },
        ["text"] = "Аукціонний дім Орґріммара розташований у Долині Сили. Шукай на східному боці, поруч із «Імпортом Вибухопалиці».",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [572139771] = {
        ["english"] = { [1] = "They say an army travels on its stomach, and that's the truth.  For any offensive to succeed, your troops have to be well-fed and well supplied." },
        ["text"] = "Кажуть, армія марширує на повному шлунку — і це правда. Щоб наступ мав успіх, війська мусять бути ситими й добре забезпеченими.",
        ["npcs"] = { [1] = 12096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1716192857] = {
        ["english"] = { [1] = "These appear to be the remains of Thalorien Dawnseeker, the last wielder of Quel'Delar." },
        ["text"] = "Схоже, це останки Талорієна Світанкового Шукача, останнього власника Кель'Делара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1847787327] = {
        ["english"] = { [1] = "These Alliance pondsuckers sure are gutsy!  Boarding fully-manned Forsaken destroyers... now that's suicidal behavior if I ever heard of it." },
        ["text"] = "Оці альянсові болотососи мають неабияку відвагу! Брати на абордаж повністю укомплектовані есмінці Відречених... це вже чисте самогубство.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2509190657] = {
        ["english"] = { [1] = "Therum Deepforge is the dwarf you want to talk to. One of the finest blacksmiths around if you ask me. You can find him in the heart of the Dwarven District." },
        ["text"] = "Терум Глибококов — той дворф, із яким тобі треба поговорити. Один із найкращих ковалів, якщо спитаєш мене. Знайдеш його в самому серці Дворфівського району.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [649511437] = {
        ["english"] = { [1] = "The village of Dolanaar atop Teldrassil is home to Elder Bladeleaf." },
        ["text"] = "Селище Доланаар на Тельдрассілі — домівка старійшини Листоклинка.",
        ["npcs"] = { [1] = 15598, [2] = 15600 },
        ["roles"] = { ["greeting"] = true },
    },
    [2588391959] = {
        ["english"] = { [1] = "This sign contains various announcements and notices of rewards for performing dangerous sounding tasks.  Nothing particularly catches your eye; perhaps you should check again at a later time." },
        ["text"] = "На цій дошці висять різні оголошення й повідомлення про винагороди за небезпечні на вигляд завдання. Ніщо особливо не привертає уваги; можливо, варто навідатися пізніше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3527044587] = {
        ["english"] = { [1] = "The finest preservative of flesh known to man and Scourge alike - Frostwhisper's embalming fluid.  Only one place an adventurer could find this and one would think that the lich the fluid is named after would not take too kindly to anyone going to said place.$B$BBut... if it's the fluid you want, the Scholomance you'll haunt..." },
        ["text"] = "Найкращий засіб для збереження плоті, відомий і людям, і Скарі, — бальзамувальна рідина Морозошепота. Є лише одне місце, де шукач пригод може її знайти, і навряд чи ліч, на честь якого названо рідину, зрадіє гостям.$B$BАле... якщо потрібна рідина — Некроситет тебе кличе...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [788847142] = {
        ["english"] = { [1] = "There's something here.  It's in the rocks and the earth!" },
        ["text"] = "Тут щось є. У камені й землі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2345036630] = {
        ["english"] = { [1] = "The Headless Horseman lives in the Scarlet Monastery.  Sometimes he comes out and scares the grown ups, but not me!" },
        ["text"] = "Вершник без голови живе в Багряному монастирі. Іноді він виходить і лякає дорослих, але не мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1171413180] = {
        ["english"] = { [1] = "The nether drake looks upon you approvingly." },
        ["text"] = "Дракон Підсвітньої Крутоверті схвально дивиться на тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1077288997] = {
        ["english"] = { [1] = "The praise is well deserved. Tirion will want to praise you himself, shortly. Hey, have you noticed it getting a bit cold all of a sudden?" },
        ["text"] = "Похвала цілком заслужена. Тіріон скоро захоче подякувати тобі особисто. Гей, ти не помітив, що раптом стало якось холодно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3035524805] = {
        ["english"] = { [1] = "Tell me more about the Eastern Crystal Pylon." },
        ["text"] = "Розкажи мені більше про Східний Кришталевий Пілон.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["reply"] = true },
    },
    [4133662704] = {
        ["english"] = { [1] = "There's something fishy about new King Mrgl-Mrgl, but I can't quite put my finger on it." },
        ["text"] = "У новому королі Мрґл-Мрґлі щось підозріле, але ніяк не второпаю що саме.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1758217237] = {
        ["english"] = { [1] = "That's what I like to hear." },
        ["text"] = "Оце я люблю чути.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [4250519402] = {
        ["english"] = { [1] = "The natural beauty of these hills belies a great darkness below.  Tread carefully, friend." },
        ["text"] = "Природна краса цих пагорбів приховує велику темряву під землею. Ступай обережно, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3656780781] = {
        ["english"] = { [1] = "The days we've spent here in Azshara are not among our best and most glorious, but we are still young and blood still courses through our veins--we shall find victory here. It is only a matter of time." },
        ["text"] = "Дні, проведені тут, в Азшарі, не належать до наших найкращих і найславніших, але ми ще молоді, а кров тече в жилах — ми здобудемо тут перемогу. Це лише питання часу.",
        ["npcs"] = { [1] = 8576 },
        ["roles"] = { ["greeting"] = true },
    },
    [862542400] = {
        ["english"] = { [1] = "There's one of those inside the barracks on the east side of Razor Hill.  Look for Rawrk." },
        ["text"] = "Один такий є в казармах на східному боці Колючого Пагорба. Шукай Раврка.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1137439358] = {
        ["english"] = { [1] = "The Wretched are a constant thorn in my side, $N.  When they're not being a danger to themselves by tapping unstable arcane sources to satisfy their cravings, they're cooking up half-brained schemes against our respectable society." },
        ["text"] = "Злиденні постійно муляють мені очі, $N. Коли вони не наражають себе на небезпеку, висмоктуючи нестабільні джерела таємної магії заради своєї залежності, то вигадують дурнуваті змови проти нашого пристойного суспільства.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1965346448] = {
        ["english"] = { [1] = "There's one in Orgrimmar.  Go north and talk to one of their grunts." },
        ["text"] = "Один такий є в Орґріммарі. Іди на північ і поговори з одним із рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1263797251] = {
        ["english"] = { [1] = "The corporeal form of Ragnaros must be destroyed. From the remnants, his essence shall emerge. In this weakened state, Ragnaros' grip on the prison of Thunderaan is loosed. The essence itself acting as a key..." },
        ["text"] = "Тілесну форму Раґнароса треба знищити. З решток постане його сутність. У такому ослабленому стані хватка Раґнароса на в'язниці Тундераана послабне. Сама сутність стане ключем...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1238993775] = {
        ["english"] = { [1] = "There's nothing quite like communing with nature... or at least that's what the night elves tell me.  I'm not much for talking to flowers and trees, but I'm sure Tannysa could help you out.  She's over in the Mage Quarter outside of Alchemy Needs." },
        ["text"] = "Ніщо не зрівняється зі спілкуванням із природою... принаймні так кажуть нічні ельфи. Я не дуже люблю говорити з квітами й деревами, але Танниса точно зможе допомогти. Вона в Кварталі Магів, біля «Алхімічних потреб».",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1239421209] = {
        ["english"] = { [1] = "The ashes from the burning wickerman radiate magical power." },
        ["text"] = "Попіл від палаючого Опудала випромінює магічну силу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3256201261] = {
        ["english"] = { [1] = "The Headless Horseman was scared away!" },
        ["text"] = "Вершника без голови налякали й прогнали!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1857011426] = {
        ["english"] = { [1] = "The esteemed Doctor Gustaf VanHowzen can train you further.  He can be found in Theramore treating the wounded at the barracks." },
        ["text"] = "Шановний доктор Ґустаф Ван-Говзен може навчати тебе далі. Його знайдеш у Тераморі, де він лікує поранених у казармах.",
        ["npcs"] = { [1] = 2326, [2] = 2327, [3] = 2329, [4] = 3181, [5] = 4211, [6] = 5150, [7] = 6094 },
        ["roles"] = { ["greeting"] = true },
    },
    [788823471] = {
        ["english"] = { [1] = "There is a symmetry in the idea of the hide of your enemy providing you with protection.  To further your leatherworking skills look for Una inside the Thunder Bluff Armorers on the middle rise." },
        ["text"] = "Є певна симетрія в тому, що шкура ворога дає тобі захист. Щоб удосконалити шкірництво, знайди Уну в «Зброярах Громового Бескиду» на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [488759158] = {
        ["english"] = { [1] = "That's Rupert Boch you're looking for.  He and his entourage have a room upstairs at the Gallows' End Tavern on the southeast end of Brill." },
        ["text"] = "Ти шукаєш Руперта Боча. Він зі своєю свитою винайняв кімнату нагорі в таверні «Кінець Шибениці» на південно-східному краю Брілля.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2552339045] = {
        ["english"] = { [1] = "The Royal Apothecary Society welcomes you to Northrend, $c.  Now, what is it that you will do to aid us in Sylvanas' service?" },
        ["text"] = "Королівське товариство аптекарів вітає тебе в Нортренді, $c. А тепер — що ти зробиш, щоб допомогти нам у службі Сильвані?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2468954115] = {
        ["english"] = { [1] = "There's nothing like a little Lunar celebration to warm your bones!" },
        ["text"] = "Ніщо так не зігріває кістки, як невелике святкування Місячного фестивалю!",
        ["npcs"] = { [1] = 15907 },
        ["roles"] = { ["greeting"] = true },
    },
    [3833903689] = {
        ["english"] = { [1] = "The druids say that it is only a matter of time until nature itself drives the Horde from Kalimdor. Yet corruption continues to spread throughout our lands, even here on Teldrassil." },
        ["text"] = "Друїди кажуть, що природа сама з часом вижене Орду з Калімдору. Та осквернення й далі шириться нашими землями, навіть тут, на Тельдрассілі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1231698590] = {
        ["english"] = { [1] = "They say a stitch in time saves... what, eleven? Ah, I can't remember. Stupid saying anyway." },
        ["text"] = "Кажуть, один вчасний стібок рятує... що, одинадцять? Ех, не пам'ятаю. Дурна приказка.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [439722681] = {
        ["english"] = { [1] = "Take your time, look the weapons over.  I also repair weapons and armor if you need such services." },
        ["text"] = "Не поспішай, роздивися зброю. Я також лагоджу зброю й обладунки, якщо тобі потрібні такі послуги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [692493706] = {
        ["english"] = { [1] = "The end draws nigh! Even as we speak the last of our supplies are being shipped to Silithus and should arrive within a day. Once there I am sure that all we be assembled in quick order, and then we'll be awaiting the ringing of the gong at the gates to Ahn'Qiraj to start the war. I look forward to analyzing whether our preparatory efforts will make a difference." },
        ["text"] = "Кінець близько! Поки ми говоримо, останні наші припаси везуть до Силітуса, і вони мають прибути менш ніж за день. Упевнений, там усе швидко зберуть, і тоді ми чекатимемо удару в гонг біля брам Ан'Кіражу, що почне війну. Цікаво буде проаналізувати, чи дадуть результат наші підготовчі зусилля.",
        ["npcs"] = { [1] = 15512 },
        ["roles"] = { ["greeting"] = true },
    },
    [1514108996] = {
        ["english"] = { [1] = "The large shrine was built many years ago by the night elves that once inhabited this land.$B$BWhat secrets could it hold?" },
        ["text"] = "Велике святилище збудували багато років тому нічні ельфи, які колись жили на цій землі.$B$BЯкі таємниці воно приховує?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3332808127] = {
        ["english"] = { [1] = "There's an herbalist that lives in the hills east of Stormwind with our alchemist. Quite the handy pairing don't you think?" },
        ["text"] = "У пагорбах на схід від Штормовію живе травник разом із нашим алхіміком. Зручна пара, хіба ні?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2378941945] = {
        ["english"] = { [1] = "Thank you for helping Thrall escape, friends. Now I only hope you can help me as well. I awoke this morning to find myself trapped in this magical prison. A strange wizard told me that I would have to stay here for a while." },
        ["text"] = "Дякую, друзі, що допомогли Траллу втекти. Тепер сподіваюся, ви допоможете й мені. Сьогодні вранці я прокинувся й виявив, що опинився в цій магічній в'язниці. Дивний чарівник сказав, що мені доведеться трохи тут посидіти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3498383225] = {
        ["english"] = { [1] = "Thank you for your help, $n.  These frostberries are literally the fruits of your labor." },
        ["text"] = "Дякую за допомогу, $n. Ці морозниці — буквально плоди твоєї праці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2081111865] = {
        ["english"] = { [1] = "Such wisdom is steeped in a mystery that can only be found in great Thunder Bluff.  Follow the path north out of Bloodhoof Village until you come to an elevator at the base of the bluffs.  Ride it to the top and ask one of the Bluffwatchers for further assistance." },
        ["text"] = "Така мудрість оповита таємницею, яку можна віднайти лише у величному Громовому Бескиді. Іди стежкою на північ від селища Криваве Копито, доки не дістанешся підіймача біля підніжжя бескидів. Піднімись нагору й попроси одного з вартових Бескиду про подальшу допомогу.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1737245761] = {
        ["english"] = { [1] = "The Darkmoon Faire is coming!  There is fun for children of ALL ages!  Come one, come all!" },
        ["text"] = "Ярмарок Темного Місяця наближається! Розваги для дітей УСІХ вікових категорій! Приходьте всі!",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["greeting"] = true },
    },
    [2883916232] = {
        ["english"] = { [1] = "The generals tell us that we've collected everything that we need for the upcoming Ahn'Qiraj War. Now we're just waiting for the Horde to finish their stockpiling and the transport of the war materiel can begin." },
        ["text"] = "Генерали кажуть, що ми зібрали все необхідне для майбутньої війни в Ан'Кіражі. Тепер лише чекаємо, доки Орда завершить свої запаси, після чого можна починати перевезення військових припасів.",
        ["npcs"] = { [1] = 15452 },
        ["roles"] = { ["greeting"] = true },
    },
    [3828543728] = {
        ["english"] = { [1] = "There's an excellent skinner that lives up in the house by Crystal Lake.  She's bound to be able to show you how to get started in the skinner's profession." },
        ["text"] = "У будинку біля Кришталевого озера живе чудова шкурниця. Вона точно покаже тобі основи зняття шкур.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2080656525] = {
        ["english"] = { [1] = "There's always a need for more kegs at Brewfest!$b$bI'll lend you the reins to one of my personal rams.$b$bEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!  $B$BTake heed! Once you start this, you won't be able to do it again until tomorrow.$B$BAre you sure you're ready to do this?" },
        ["text"] = "На Хмільному фестивалі завжди потрібні нові барила!$b$bЯ позичу тобі вуздечку одного зі своїх особистих баранів.$b$bЗа кожне принесене барило дам жетони. І за кожне барило дозволю трохи довше користуватися бараном!$B$BЗапам'ятай: щойно почнеш, повторити це знову зможеш лише завтра.$B$BТочно готовий?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2151553604] = {
        ["english"] = { [1] = "Tauren have a passion for hunting; it is something that runs deep with our kind." },
        ["text"] = "Таурени мають пристрасть до полювання; це закладено глибоко в нашій природі.",
        ["npcs"] = { [1] = 3039, [2] = 3065 },
        ["roles"] = { ["greeting"] = true },
    },
    [3748973220] = {
        ["english"] = { [1] = "The Shattered Hand has been able to place spies throughout the upper citadel of Blackrock. Though the information gathering process has been slow, we have made discoveries that cannot be ignored." },
        ["text"] = "Розтрощена Десниця змогла розмістити шпигунів по всій верхній цитаделі Чорнокаменю. Збір відомостей іде повільно, але ми зробили відкриття, які не можна ігнорувати.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [84544529] = {
        ["english"] = { [1] = "There's a whole vast forest out there, $c. Let the shaman play with the spirits and the warriors toy with their swords. Terokkar is where I'll make my fortune." },
        ["text"] = "Там цілий величезний ліс, $c. Нехай шамани бавляться з духами, а воїни — з мечами. У Тероккарі я наживу статок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1754945714] = {
        ["english"] = { [1] = "The Matrix Punchograph Technologic Huerist-o-meter has detected your aptitude in engineering.  You may now choose from the following option(s):$b$b01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001" },
        ["text"] = "Матричний Перфографічний Технологічний Еврист-o-метр виявив твої здібності до інженерії. Тепер можеш обрати з таких варіантів:$b$b01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4065396330] = {
        ["english"] = { [1] = "The Irondeep Mine is in Alliance territory, north of the Stormpike Graveyard.$B$BIt is controlled by the Troggs." },
        ["text"] = "Копальня Залізної Глибини розташована на території Альянсу, на північ від кладовища Бурешпиля.$B$BЇї контролюють троґґи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3782319955] = {
        ["english"] = { [1] = "The battle is over, and the people of Darrowshire are saved.$B$BThey are saved, $N, because of you.  You are truly a hero of Darrowshire." },
        ["text"] = "Битва закінчилась, і жителів Дерроуширу врятовано.$B$BЇх врятовано, $N, завдяки тобі. Ти справжній герой Дерроуширу.",
        ["npcs"] = { [1] = 10945 },
        ["roles"] = { ["greeting"] = true },
    },
    [3783297871] = {
        ["english"] = { [1] = "There's a Skinning Trainer in Orgrimmar.  To get there head north up the road out of Razor Hill.  Ask an Orgrimmar Grunt for directions when you arrive." },
        ["text"] = "В Орґріммарі є наставник зі зняття шкур. Іди дорогою на північ від Колючого Пагорба. Коли прибудеш, попроси рубаку Орґріммара показати шлях.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3775190670] = {
        ["english"] = { [1] = "The tag on this present reads: \"For ages 40 and up.\"" },
        ["text"] = "На бирці цього подарунка написано: «Для осіб від 40 років».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [295432404] = {
        ["english"] = { [1] = "There's a mage at the Thunderbrew Distillery who might be able to teach you some new spells.  I believe his name is Magis Sparkmantle." },
        ["text"] = "Біля гуральні Громовара є маг, який може навчити тебе нових заклять. Здається, його звати Маґіс Іскромантія.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [779246171] = {
        ["english"] = { [1] = "The Bravery's crew will do its best to make your journey as swift and pleasant as possible." },
        ["text"] = "Екіпаж «Відваги» зробить усе можливе, щоб твоя подорож була швидкою й приємною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [565561061] = {
        ["english"] = { [1] = "There you go, $N. Good thing my powers of divination and summoning still work in this ghostly state, huh?" },
        ["text"] = "Ось і все, $N. Добре, що мої здібності до ворожіння й виклику все ще працюють у примарному стані, га?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3159789679] = {
        ["english"] = { [1] = "This is a great day, $c!" },
        ["text"] = "Чудовий день, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4087501282] = {
        ["english"] = { [1] = "There you are! I was beginning to think that the Sunreavers had intercepted you. Are you ready to deliver the tome to our representatives in Icecrown?" },
        ["text"] = "Ось ти де! Я вже думав, що Сонячні Викрадачі тебе перехопили. Готовий доставити фоліант нашим представникам у Крижаній Короні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [444798831] = {
        ["english"] = { [1] = "The Argent Dawn coordinates the Scourge's opposition at Light's Hope Chapel in the Eastern Plaguelands.  Go there for instructions." },
        ["text"] = "Сріблястий Світанок координує опір Скарі біля Каплиці Останньої Надії у Східному Чумнозем'ї. Іди туди по накази.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1032651460] = {
        ["english"] = { [1] = "The Warchief has instructed me to study all kinds of weapons and armor. He has sent me here to the hub of both the tauren and orc cultures in the Barrens to meet as many travelers as possible, and to learn about the cultures of the Barrens.$B$BHe feels there's something to be learned from even the most pathetic of cultures... like the quilboar or centaur." },
        ["text"] = "Вождь наказав мені вивчати всі види зброї та обладунків. Він послав мене сюди, в осередок тауренської та орчої культур Степів, щоб я зустрів якомога більше мандрівників і дізнався про культури цих земель.$B$BВін вважає, що можна чогось навчитися навіть у найжалюгідніших народів... наприклад, свинобразів чи кентаврів.",
        ["npcs"] = { [1] = 3433 },
        ["roles"] = { ["greeting"] = true },
    },
    [3018548165] = {
        ["english"] = { [1] = "The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain. " },
        ["text"] = "Некроситет міститься в склепах під фортецею Каєр-Дарроу. Колись фортеця належала шляхетній родині Барових, але після Другої війни занепала. Коли чарівник Кел'Тузад набирав послідовників до Культу Проклятих, він часто обіцяв безсмертя тим, хто служитиме його Королю-лічу. Барови потрапили під його вплив і віддали фортецю, але культисти вбили родину й перетворили склепи на школу некромантії. Хоч Кел'Тузад там більше не живе, культисти й наставники досі лишилися.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [4055095755] = {
        ["english"] = { [1] = "The Deadmines can be found beneath Moonbrook in the south of Westfall." },
        ["text"] = "Мертві копальні розташовані під Місячним Струмком на півдні Західного краю.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3152176495] = {
        ["english"] = { [1] = "There is something that you wish to buy?  There is something that you wish to sell?$B$BThis is why we are here, my friend.$B$BPlease, tell me your pleasure." },
        ["text"] = "Хочеш щось купити? Хочеш щось продати?$B$BСаме для цього ми тут, друже.$B$BСкажи, чого бажаєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1866469097] = {
        ["english"] = { [1] = "This party is just the best!  Don't you agree?" },
        ["text"] = "Ця гулянка просто найкраща! Згодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3397536933] = {
        ["english"] = { [1] = "The Apexis Monument looms above you." },
        ["text"] = "Монумент Апекситів височіє над тобою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1700582849] = {
        ["english"] = { [1] = "The bank" },
        ["text"] = "Банк",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 3571, [25] = 4262, [26] = 5624, [27] = 5725, [28] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [2992980332] = {
        ["english"] = { [1] = "The closest gryphon master is located up in Ironforge near The Great Forge itself.  Ye'll need to head to Ironforge if ye want to travel by gryphon." },
        ["text"] = "Найближчий майстер грифонів — у Залізогарті, біля самої Великої Кузні. Якщо хочеш літати на грифонах, доведеться йти до Залізогарта.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [277907261] = {
        ["english"] = { [1] = "The Vault in Ironforge is the closest bank ye'll find in these parts." },
        ["text"] = "Сховище в Залізогарті — найближчий банк у цих краях.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1592759314] = {
        ["english"] = { [1] = "Sure thing, $N. You look like you can be trusted... Trustworthy! I can spot that a mile away...$B$BAnyway, back to what I was sayin'. Takes one Evoroot plant to make the Videre Elixir. The rest 'a the ingredients are trivial really, but the Evoroot, well, that can be a bit tricky to get." },
        ["text"] = "Авжеж, $N. Схоже, тобі можна довіряти... Надійна людина! Я таких за версту бачу...$B$BТа повернімося до справи. Для еліксиру Відірі потрібна одна рослина вічнокореня. Решта складників — дрібниці, а от вічнокорінь дістати буває непросто.",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["greeting"] = true },
    },
    [3301743218] = {
        ["english"] = { [1] = "Tell me about the Portals Deck." },
        ["text"] = "Розкажи мені про Колоду Порталів.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["reply"] = true },
    },
    [1105919754] = {
        ["english"] = { [1] = "Stefan told me you would demonstrate the purpose of this item." },
        ["text"] = "Стефан сказав, що ти продемонструєш призначення цього предмета.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3915243105] = {
        ["english"] = { [1] = "There is nothing to see here. Move along." },
        ["text"] = "Тут немає на що дивитися. Проходь далі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1489732988] = {
        ["english"] = { [1] = "The Melee Target trains Aspirants in both mounted attack and defense.$B$BApproach the Melee Target and strike it with a Thrust attack. The force of the blow often spins the target hard enough to injure you or your mount. This is where defense comes into play.$B$BBe certain to have at least one layer of Defend before attacking the target, and continue to stack and refresh Defend throughout the training exercise. Otherwise, you may well find yourself dismounted.$B$BThe same holds true in actual mounted combat: Balance attack and defense, Thrusting at every opportunity and maintaining your layers of Defend as best you can." },
        ["text"] = "Мішень ближнього бою навчає претендентів і атаки верхи, і захисту.$B$BПідійди до мішені й атакуй її Випадом. Сила удару часто розкручує мішень достатньо сильно, щоб травмувати тебе або твого скакуна. Саме тут потрібен захист.$B$BПеред атакою переконайся, що маєш принаймні один шар Захисту, і постійно накопичуй та поновлюй Захист під час тренування. Інакше тебе цілком можуть вибити із сідла.$B$BТе саме справедливо й у справжньому кінному бою: урівноважуй атаку й захист, роби Випади за кожної нагоди й підтримуй шари Захисту якнайкраще.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [438785652] = {
        ["english"] = { [1] = "Thank you, Omarion. You have taken a fatal blow for the team on this day." },
        ["text"] = "Дякую, Омаріоне. Сьогодні ти прийняв смертельний удар за всю команду.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [4222568928] = {
        ["english"] = { [1] = "There is not much more to tell. Dalaran was nearly wholly destroyed by Archimonde, the staff lost, presumably shattered by the barrier's fail-safe mechanisms.$B$BThere are those that believe the staff to be the cause of Archimonde's reprisal." },
        ["text"] = "Більше майже нічого розповідати. Даларан майже повністю знищив Архімонд, а посох було втрачено — ймовірно, його розбили аварійні механізми бар'єра.$B$BДехто вважає, що саме посох став причиною помсти Архімонда.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [2640756557] = {
        ["english"] = { [1] = "There is no greater way to clear the mind than to weave." },
        ["text"] = "Ніщо так не очищує розум, як ткацтво.",
        ["npcs"] = { [1] = 11050 },
        ["roles"] = { ["greeting"] = true },
    },
    [3382096806] = {
        ["english"] = { [1] = "The Royal Apothecary Society has little patience for fools, as do I.  Perhaps the next time you and I speak of my steeds, you will be considered exalted by the Undercity.  Until then..." },
        ["text"] = "Королівське товариство аптекарів не терпить дурнів — як і я. Можливо, коли наступного разу говоритимемо про моїх скакунів, Підмістя вважатиме тебе превознесеним. А до того часу...",
        ["npcs"] = { [1] = 4731 },
        ["roles"] = { ["greeting"] = true },
    },
    [123781480] = {
        ["english"] = { [1] = "There is no finer cook in Thunder Bluff than Aska Mistrunner.  Mmmmm, I can smell what she is cooking from here.  Head over to her kitchen located on the high rise.\010\010Drat... now I am hungry." },
        ["text"] = "У Громовому Бескиді немає кращої кухарки за Аску Туманну Бігунку. М-м-м, я звідси відчуваю запах її страв. Іди до її кухні на верхньому виступі.\010\010Дідько... тепер я голодний.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [788041395] = {
        ["english"] = { [1] = "There is an Engineering Trainer in Razor Hill.  He is called Mukdrak and can usually be found standing over near the forge." },
        ["text"] = "У Колючому Пагорбі є наставник інженерії. Його звати Мукдрак, і зазвичай він стоїть біля кузні.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3040903018] = {
        ["english"] = { [1] = "There is bound to be a gnome in Stormwind that can teach you the profession.  I'm sure one of the Stormwind Guards could point you in the right direction." },
        ["text"] = "У Штормовії точно знайдеться гном, який навчить тебе цієї професії. Упевнений, будь-який вартовий Штормовію покаже правильний шлях.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1457001088] = {
        ["english"] = { [1] = "There is more to magic than just arcane gesticulations... but I am speaking to someone who already knows this, yes?$B$BYou've come to me to learn, and learn you will... just so long as you pay attention and do as I say.  The secrets of the demons do not cater to fools, and neither do I." },
        ["text"] = "Магія — це не лише жести таємної школи... але ж я говорю з тим, хто це вже знає, так?$B$BТи прийшов до мене вчитися — і вчитимешся, якщо уважно слухатимеш і робитимеш, як я кажу. Таємниці демонів не терплять дурнів. Як і я.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [33220670] = {
        ["english"] = { [1] = "There is an alchemist that lives up in the hills between Northshire and Stormwind that might be of some help.  Why don't you go pay him a visit?" },
        ["text"] = "У пагорбах між Північнокраєм і Штормовієм живе алхімік, який, можливо, зможе допомогти. Чому б не навідатися до нього?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3357522306] = {
        ["english"] = { [1] = "Tell me what you want, and make it quick." },
        ["text"] = "Кажи, чого хочеш, і швидше.",
        ["npcs"] = { [1] = 3314 },
        ["roles"] = { ["greeting"] = true },
    },
    [2599863918] = {
        ["english"] = { [1] = "There is a Wind Rider Master in the great city of Thunder Bluff to the north.  Ride the elevator from the base of Thunder Bluff to the top and ask one of the Bluffwatchers there for further instructions." },
        ["text"] = "У великому місті Громовий Бескид на півночі є майстер вітровершників. Піднімись ліфтом від підніжжя Громового Бескиду нагору й попроси одного з вартових Бескиду про подальші вказівки.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3117369989] = {
        ["english"] = { [1] = "The zeppelin should just have departed from Grom'gol." },
        ["text"] = "Дирижабль щойно мав вирушити з Ґром'ґола.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2069983304] = {
        ["english"] = { [1] = "There is a time and a place for all things, including relaxation.  On the west side of Bloodhoof Village Innkeeper Kauth maintains a long house for those who seek to rest.  You will find him there." },
        ["text"] = "Для всього є свій час і місце, навіть для відпочинку. На західному боці селища Криваве Копито корчмар Каут тримає довгий будинок для тих, хто хоче перепочити. Там його й знайдеш.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3107634100] = {
        ["english"] = { [1] = "Thanks again for returning my lucky measuring tape, $N.  I swear it helps me catch bigger fish!" },
        ["text"] = "Ще раз дякую, що повернув мою щасливу мірну стрічку, $N. Присягаюся, з нею я ловлю більшу рибу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3665156825] = {
        ["english"] = { [1] = "That crash between here and Razor Hill really messed up the brew flow!  It doesn't help that Dark Iron dwarves seem to be attacking every hour or so!$b$bSo if you want to help, here's the deal.  I'll let you borrow some reins and one of my rams.$b$bEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!$b$bBUT, once you start this, you won't be able to do it again until tomorrow.$b$bAre you sure you're ready to do this?" },
        ["text"] = "Та аварія між цим місцем і Колючим Пагорбом добряче порушила постачання випивки! А ще дворфи Темного Заліза нападають мало не щогодини!$b$bЯкщо хочеш допомогти, ось умови. Я позичу тобі вуздечку й одного зі своїх баранів.$b$bЗа кожне принесене барило дам тобі жетони. І за кожне барило дозволю трохи довше користуватися бараном!$b$bАЛЕ, щойно почнеш, повторити це знову зможеш лише завтра.$b$bТочно готовий?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1577049123] = {
        ["english"] = { [1] = "Surprised to see an orc here? Don't be.$b$bThe forsaken need watching. If we'd been paying closer attention from the start, maybe the Wrath Gate wouldn't have happened." },
        ["text"] = "Дивуєшся, що бачиш тут орка? Не варто.$b$bЗа Відреченими треба наглядати. Якби ми пильнували їх від самого початку, можливо, Брами Гніву не сталося б.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2283465431] = {
        ["english"] = { [1] = "There is a powerful infernal named Kroshius northeast of this camp. It is why Niby is here. Kroshius is a greater infernal - an infernal that has lasted longer than expected. You see, nub, an infernal crashes down into the earth with great intensity to serve its master but this intensity fades fast. Once the blazing flames have died down, the infernal crumbles." },
        ["text"] = "На північний схід від цього табору є могутній інфернал на ім'я Крошіус. Саме через нього Нібі тут. Крошіус — великий інфернал, тобто інфернал, що протримався довше, ніж мав би. Розумієш, недоумку, інфернал із шаленою силою падає на землю, щоб служити господареві, але ця сила швидко згасає. Коли палаючий вогонь вщухає, інфернал розсипається.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["greeting"] = true },
    },
    [3119328017] = {
        ["english"] = { [1] = "That would be Shelene Rhobart.  Take the road southeast out of Brill then head east at the intersection.  She's at a camp along the side of the road." },
        ["text"] = "Це Шелена Робарт. Вийди з Брілля дорогою на південний схід, а на перехресті поверни на схід. Вона в таборі край дороги.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1165071681] = {
        ["english"] = { [1] = "This nightsaber is rumored to be docile in the presence of night elves and their allies, which makes her an even more worthy opponent.  Shadumbra's hunting path takes her from the Raynewood Retreat to our west, ultimately to lands due west of there.  Her fur is the color of pitch, and her speed is not to be underestimated." },
        ["text"] = "Подейкують, що ця нічна шаблезубка сумирна в присутності нічних ельфів та їхніх союзників, а отже, вона ще гідніша супротивниця. Мисливська стежка Шадумбри веде від Прихистку Дощолісся на захід, а далі — до земель іще далі на захід. Її хутро чорне, мов смола, а швидкість не варто недооцінювати.",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["greeting"] = true },
    },
    [2732069603] = {
        ["english"] = { [1] = "There is a mailbox outside of the Bank which you'll find in the center of Darnassus." },
        ["text"] = "Поштова скринька стоїть біля Банку, який знайдеш у центрі Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3625647048] = {
        ["english"] = { [1] = "There are fundamental things you must learn before I can aid you. Speak to my apprentice, Vhan. He is kind and patient and will teach you what you need to know." },
        ["text"] = "Є фундаментальні речі, які ти мусиш засвоїти, перш ніж я зможу тобі допомогти. Поговори з моїм учнем Вганом. Він добрий і терплячий та навчить тебе всього потрібного.",
        ["npcs"] = { [1] = 3004 },
        ["roles"] = { ["greeting"] = true },
    },
    [3974967650] = {
        ["english"] = { [1] = "The time has come for Horde and Alliance to look towards the north and the invasion of the Scourge. In recent days, territories across Kalimdor and the Eastern Kingdoms have come under attack. Will you take up arms to save your land from destruction at their hands?" },
        ["text"] = "Настав час Орді й Альянсу звернути погляд на північ і вторгнення Скари. Останніми днями нападів зазнали землі по всьому Калімдору й Східних Королівствах. Візьмеш зброю, щоб урятувати свою землю від знищення?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [3062380681] = {
        ["english"] = { [1] = "The god that the Atal'ai trolls had brought forth is to blame for this.  We destroyed the god's physical manifestation and sunk the temple, but the god was much stronger than even we had anticipated.  Its seed of corruption ran deep, twisting everything in its path.$B$BEranikus was charged to watch over the sunken temple to ensure that neither the simple Atal'ai nor their god would rise again.  He was an unwitting victim of this corruption, and we in underestimating its potency." },
        ["text"] = "У всьому цьому винен бог, якого тролі Атал'ай покликали у світ. Ми знищили його тілесне втілення й затопили храм, але бог виявився значно сильнішим, ніж ми гадали. Насіння його осквернення проросло глибоко, спотворюючи все на своєму шляху.$B$BЕранікусу доручили стерегти затонулий храм, щоб ані прості Атал'ай, ані їхній бог більше не постали. Він став мимовільною жертвою цієї скверни, а ми — жертвами власної недооцінки її сили.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["greeting"] = true },
    },
    [756791143] = {
        ["english"] = { [1] = "There exist in Outland demonic presences much more powerful than anything we'd ever seen in the old world.$B$BGreat power shall come to those who do not shy away from it, but learn to harness and master its strength." },
        ["text"] = "У Позамежжі є демонічні сили, значно могутніші за все, що ми бачили у старому світі.$B$BВелика сила дістанеться тим, хто не тікає від неї, а вчиться її приборкувати й опановувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3879438938] = {
        ["english"] = { [1] = "The extent of the corruption in Outland is truly astonishing, $c. The Cenarion Circle hopes to understand how these creatures have managed to survive. Studying this broken, tortured land and its inhabitants may yet teach us how to heal ailing parts of our own world." },
        ["text"] = "Масштаб осквернення Позамежжя справді вражає, $c. Кенарієве Коло прагне зрозуміти, як цим істотам вдалося вижити. Вивчення цієї зламаної, змученої землі та її мешканців, можливо, навчить нас лікувати хворі частини власного світу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [170289097] = {
        ["english"] = { [1] = "Take this ledger to an old acquaintance of mine in Tanaris. His name is Narain Soothfancy - terrible, terrible, psychic but an amazing engineer! He should be able to make sense of it all.$B$BNo need to thank me, $N. It's the least I could do.$B$BGood day!" },
        ["text"] = "Віднеси цю книгу обліку моєму давньому знайомому в Танаріс. Його звати Нарайн Всезнай — жахливий, просто жахливий провидець, зате неймовірний інженер! Він має розібратися в усьому цьому.$B$BНе дякуй, $N. Це найменше, що я міг зробити.$B$BЩасти!",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [852896078] = {
        ["english"] = { [1] = "They called me stupid, but I'll show them. I'm going to watch every pot I have and prove that they can all boil stuff anyway. Yeah, I'm on a roll! Who's stupid now, huh? Huh!?" },
        ["text"] = "Вони називали мене дурнем, але я їм покажу. Я дивитимуся на кожен свій казан і доведу, що вони все одно можуть щось варити. Ага, мене не спинити! Ну хто тепер дурень, га? Га?!",
        ["npcs"] = { [1] = 11046 },
        ["roles"] = { ["greeting"] = true },
    },
    [2872389126] = {
        ["english"] = { [1] = "Tell me." },
        ["text"] = "Розкажи мені.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [3928525844] = {
        ["english"] = { [1] = "There aren't any enchanters out here in Dun Morogh that I know of.  Ye're going to have to visit Ironforge if ye want to learn the enchanter's profession." },
        ["text"] = "Наскільки я знаю, тут, у Дун-Морозі, немає жодного заклинача. Якщо хочеш вивчити зачарування, доведеться навідатися до Залізогарта.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1531427429] = {
        ["english"] = { [1] = "The skill with which Telonis crafts armor is beyond compare.  You should be grateful that he does not charge more for the knowledge he passes to others.  Go now and seek him out in the Craftsmen's Terrace in the northeast section of Darnassus." },
        ["text"] = "Майстерність, з якою Телоніс виготовляє обладунки, не має рівних. Будь вдячний, що він не бере більше за знання, якими ділиться. Іди й знайди його на Ремісничій терасі в північно-східній частині Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [941647470] = {
        ["english"] = { [1] = "Step carefully mortal.  You tread where mightier beings have met their fate." },
        ["text"] = "Ступай обережно, смертний. Тут знайшли свою загибель істоти могутніші за тебе.",
        ["npcs"] = { [1] = 15502 },
        ["roles"] = { ["greeting"] = true },
    },
    [2689527880] = {
        ["english"] = { [1] = "The Darkmoon Faire has arrived, you say? And where is she now?" },
        ["text"] = "Кажеш, прибув ярмарок Темного Місяця? І де він зараз?",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["reply"] = true },
    },
    [2232318818] = {
        ["english"] = { [1] = "There are ways to strengthen steel beyond the hammer and forge, young wanderer. Care to learn more?" },
        ["text"] = "Сталь можна зміцнювати не лише молотом і кузнею, юний мандрівнику. Хочеш дізнатися більше?",
        ["npcs"] = { [1] = 11065 },
        ["roles"] = { ["greeting"] = true },
    },
    [4208878186] = {
        ["english"] = { [1] = "There are two prominent bills tacked up on the board here; one from Papa Wheeler and one from Rocket-Chief Fuselage.$B$BPapa's looks like it's a wanted ad for a machine part.  The rocket-chief's has something to do with a bounty on the head of an immense mountain giant!$B$BThe details for both are provided in very small goblin handwriting, which is, of course, barely legible." },
        ["text"] = "На дошці приколото два помітні оголошення: одне від Татка Вілера, друге від ракетного шефа Фюзеляжу.$B$BОголошення Татка схоже на розшук деталі машини. У ракетного шефа йдеться про винагороду за голову величезного гірського велетня!$B$BПодробиці обох написані дуже дрібним ґоблінським почерком, який, звісно, майже неможливо розібрати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [954319375] = {
        ["english"] = { [1] = "The spirit looks upon you with a sense of completeness and cognizance that had not been present before.$B$B\"I feel as though a great burden has been lifted from my soul.  Soon I will rest forever in peace.  I now know this, and I await this time patiently.$B$BThank you, stranger.\"" },
        ["text"] = "Дух дивиться на тебе з відчуттям завершеності й усвідомлення, яких раніше не було.$B$B«Ніби великий тягар упав із моєї душі. Скоро я назавжди спочину в мирі. Тепер я це знаю й терпляче чекаю цього часу.$B$BДякую, незнайомцю».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2107680203] = {
        ["english"] = { [1] = "There are demons to kill, $c.  Do you have the backbone to do what needs to be done?" },
        ["text"] = "Є демони, яких треба вбити, $c. Вистачить духу зробити те, що необхідно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [570474432] = {
        ["english"] = { [1] = "This is a waste of time, mine and yours! Go see Graham Van Talen if you want to begin your instruction! He's standing to my left over there." },
        ["text"] = "Це марнування часу — і мого, і вашого! Якщо хочете розпочати навчання, йдіть до Ґрема Ван Талена! Він стоїть он там ліворуч від мене.",
        ["npcs"] = { [1] = 11031 },
        ["roles"] = { ["greeting"] = true },
    },
    [272342334] = {
        ["english"] = { [1] = "There are those that attempt to follow the path of the Rogue, but only the night elves are truly embraced by the night.  If you seek to walk the shaded path then find Syurna in the Cenarion Enclave." },
        ["text"] = "Є ті, хто намагається йти шляхом розбійника, але лише нічних ельфів справді приймає ніч. Якщо прагнеш іти затіненим шляхом, знайди Сюрну в Кенарійському анклаві.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [852153198] = {
        ["english"] = { [1] = "There are stable masters just outside both the draenei and blood elf inns on Aldor Rise and Scryer's Tier." },
        ["text"] = "Господарі стайні є прямо біля обох корчм — дренейської та ельфів крові — на Висоті Алдорів і Ярусі Провидців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3922696077] = {
        ["english"] = { [1] = "That reminds me, I'm going to need to find something to eat soon. As to what the Alliance has been cooking up, I'm told that $2092w out of $2093w rainbow fin albacore have been packed away. As well, $2098w of $2099w roast raptor and $2101w out of $2103w spotted yellowtail have been prepared and are currently in cold storage awaiting transport to Cenarion Hold in Silithus." },
        ["text"] = "До речі, скоро треба буде знайти щось поїсти. А щодо того, що там наготував Альянс: кажуть, уже запаковано $2092w із $2093w райдужних альбакорів. Також приготовано $2098w із $2099w смажених рапторів і $2101w із $2103w плямистих жовтохвосток; усе це лежить у холодному сховищі й чекає перевезення до Кенарійської цитаделі в Силітусі.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2260762281] = {
        ["english"] = { [1] = "There are several prominent bills tacked up on the board here.$B$BHowever, the fine-print indicates that you're not quite ready for either of the tasks at hand.  You should definitely check back later!" },
        ["text"] = "На дошці приколото кілька помітних оголошень.$B$BАле дрібним шрифтом зазначено, що ти ще не готовий до жодного із цих завдань. Обов'язково заглянь пізніше!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4237990817] = {
        ["english"] = { [1] = "Take pride, $c, in the fact that the Alliance has completed all of the gathering tasks set before it. The finished products are stored and preserved, and our tradeskill professionals are hard at work molding those raw materials into war materiel that will be shipped to Silithus as soon as the Horde finishes their collections." },
        ["text"] = "Пишайся, $c: Альянс виконав усі поставлені завдання зі збору. Готові вироби вже складено й збережено, а наші майстри невтомно перетворюють сировину на військове спорядження, яке відправлять до Силітуса, щойно Орда завершить свої збори.",
        ["npcs"] = { [1] = 15451 },
        ["roles"] = { ["greeting"] = true },
    },
    [2036051859] = {
        ["english"] = { [1] = "There comes a time when the life we know falls short.  We are trapped and look for answers, and we find hope burning in dark places.$B$BOnly then, $N, do we take our first steps to freedom." },
        ["text"] = "Настає мить, коли звичного життя стає недостатньо. Ми опиняємося в пастці й шукаємо відповіді, а тоді знаходимо надію, що палає в темних місцях.$B$BЛише тоді, $N, ми робимо перші кроки до свободи.",
        ["npcs"] = { [1] = 14436 },
        ["roles"] = { ["greeting"] = true },
    },
    [1695843254] = {
        ["english"] = { [1] = "There are quite a few trainers available in Elwynn.  Which one are you looking for?" },
        ["text"] = "В Ельвині є чимало наставників. Кого саме ти шукаєш?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [843495749] = {
        ["english"] = { [1] = "Starting at 6PM, they will show fireworks from the highest bluff!" },
        ["text"] = "Починаючи з 18:00, вони запускатимуть феєрверки з найвищого бескиду!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2986773362] = {
        ["english"] = { [1] = "The voices are talking to me." },
        ["text"] = "Голоси говорять зі мною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3027219078] = {
        ["english"] = { [1] = "There are mysteries in this place that we, the orcs, are desperate to uncover.  Mysteries of our past, mysteries of our future, and mysteries that offer glimpses inside us.$B$BIt is my hope to pierce these mysteries... will you walk that path with me?" },
        ["text"] = "У цьому місці є таємниці, які ми, орки, відчайдушно прагнемо розкрити. Таємниці нашого минулого, нашого майбутнього й ті, що дозволяють зазирнути всередину себе.$B$BЯ хочу проникнути в ці таємниці... пройдеш цим шляхом зі мною?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4036119432] = {
        ["english"] = { [1] = "There are many secrets that may be unlocked with patience and determination. Now, let us begin..." },
        ["text"] = "Є багато таємниць, які відкриваються терпінням і рішучістю. А тепер почнімо...",
        ["npcs"] = { [1] = 11071 },
        ["roles"] = { ["greeting"] = true },
    },
    [765046998] = {
        ["english"] = { [1] = "Stay back! Children should not be here! Be gone, child!" },
        ["text"] = "Назад! Дітям тут не місце! Геть звідси, дитино!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3898949188] = {
        ["english"] = { [1] = "That's right friend!  The Darkmoon Faire is going to be right here.  Just as soon as I unload those huge wagons, put up all the tents, erect the zoo and pour the drinks.  Make sure you come back!" },
        ["text"] = "Саме так, друже! Ярмарок Темного Місяця буде просто тут. Щойно я розвантажу ці величезні вози, поставлю всі намети, облаштую звіринець і розіллю напої. Обов'язково повертайся!",
        ["npcs"] = { [1] = 14843, [2] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [1844363150] = {
        ["english"] = { [1] = "Stick around after the firework show is over.  Find a goblet and raise it to toast your hardy friends!" },
        ["text"] = "Затримайся після завершення феєрверків. Знайди келих і підніми його за своїх витривалих друзів!",
        ["npcs"] = { [1] = 15723 },
        ["roles"] = { ["greeting"] = true },
    },
    [748231710] = {
        ["english"] = { [1] = "There are many places that you might visit in Teldrassil.  Tell me what you seek." },
        ["text"] = "На Тельдрассілі є багато місць, які варто відвідати. Скажи, що ти шукаєш.",
        ["npcs"] = { [1] = 3571, [2] = 3601 },
        ["roles"] = { ["greeting"] = true },
    },
    [1592505302] = {
        ["english"] = { [1] = "The Light protect you, $c." },
        ["text"] = "Нехай Світло оберігає тебе, $c.",
        ["npcs"] = { [1] = 837, [2] = 1226, [3] = 5141, [4] = 5142, [5] = 5143, [6] = 11406 },
        ["roles"] = { ["greeting"] = true },
    },
    [1477951151] = {
        ["english"] = { [1] = "There is a large tent on the east side of Bloodhoof Village.  You will find Narm Skychaser awaiting you there." },
        ["text"] = "На східному боці селища Криваве Копито стоїть великий намет. Там на тебе чекає Нарм Небесний Переслідувач.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1112218501] = {
        ["english"] = { [1] = "There are FOUR lights!" },
        ["text"] = "Тут ЧОТИРИ вогні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2139623461] = {
        ["english"] = { [1] = "The station's mechanics had put him back together, bringing him back to \"life\".$B$BAnd now, by way of thanks, he was going to return the favor by curing all of us of what he called the \"Curse of the Flesh\".$B$BAccording to Mechazod, it's a condition that eventually befalls all of the creations of the Titans! In other words, we all supposedly start out as robots of some kind, and, over thousands of years, slowly turn into fleshy beings!$B$BPreposterous, I know." },
        ["text"] = "Механіки станції зібрали його назад і повернули до «життя».$B$BА тепер, на знак подяки, він збирався відплатити тим самим — вилікувати всіх нас від того, що називав «Прокляттям плоті».$B$BЗа словами Мехазода, це стан, який зрештою спіткає всі творіння титанів! Іншими словами, ми нібито всі починаємо як якісь роботи, а за тисячі років повільно перетворюємося на плотяних істот!$B$BАбсурд, я знаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3325881850] = {
        ["english"] = { [1] = "There are eight types of Darkmoon Cards; Beasts, Blessings, Elementals, Furies, Lunacy, Portals, Storms and Warlords, with eight cards, Ace to Eight in each suit. If you collect all eight of one suit then you can turn them into a deck that you can give to our Professor Thaddeus Paleo in exchange for a powerful trinket.$B" },
        ["text"] = "Є вісім типів карт Темного Місяця: Звірі, Благословення, Елементалі, Люті, Божевілля, Портали, Бурі та Воєводи. У кожній масті вісім карт — від туза до вісімки. Якщо збереш усі вісім однієї масті, можеш скласти з них колоду й віддати нашому професору Таддеусу Палео в обмін на могутню дрібничку.$B",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [2471265741] = {
        ["english"] = { [1] = "Stormwind is the pillar of the human race, maintained through strength of will and the edge of a sturdy blade." },
        ["text"] = "Штормовій — опора людського роду, що тримається на силі волі та вістрі міцного клинка.",
        ["npcs"] = { [1] = 911, [2] = 913, [3] = 914, [4] = 5479, [5] = 5480 },
        ["roles"] = { ["greeting"] = true },
    },
    [1601006803] = {
        ["english"] = { [1] = "That's right, um, $g lad : lass;, all of the war materiel is being transported to Silithus and the last of it should get there within a day. After that, we'll all just have to wait and see who puts forth a $g hero : heroine; to reconstitute the Scepter of the Shifting Sands and ring the gong on the Scarab Dais. Only when that occurs will the war begin to open the gates of Ahn'Qiraj." },
        ["text"] = "Саме так, е-е, $g хлопче : дівчино;, усі військові припаси везуть до Силітуса, і останні мають прибути менш ніж за день. Після цього нам лишиться чекати, хто висуне $g героя : героїню;, щоб відновити Скіпетр Мінливих Пісків і вдарити в гонг на Помості Скарабея. Лише тоді почнеться війна за відкриття брам Ан'Кіражу.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1976057018] = {
        ["english"] = { [1] = "There are two potential results when the Earthen's synthesis matrix destabilizes.  Initiating visual aid representation number one.$B$BThe first variant matrix is a degenerative product of synthesis, hereby designated with the common nomenclature of \"Trogg\".  This variant maintains strength and stamina comparable to the Earthen, but its cognitive processing power has been almost completely compromised.  Force of will and a strong sense of cunning are the only driving factors in the psyche of the trogg." },
        ["text"] = "Коли матриця синтезу земельників дестабілізується, можливі два результати. Запускаю візуальну демонстрацію номер один.$B$BПерший варіант матриці — дегенеративний продукт синтезу, надалі позначений загальноприйнятою назвою «троґґ». Цей варіант зберігає силу й витривалість, порівнянні із земельниками, але його когнітивні здібності майже повністю зруйновані. Сила волі й виразна хитрість — єдині рушійні чинники психіки троґґа.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [3711931500] = {
        ["english"] = { [1] = "There are those who would say that the Argent Crusade is a thing of the past. I am one of them, but not because the Scourge have fallen.$b$bNo... it is because of their stubborn ways.  They've become too much like the church that they seceded from: too rigid, too governed by honor and order.  This is what I'm trying to tell Barthalomew, anyhow.$b$bSure, it may sound a bit jingoistic, but it makes for a good debate." },
        ["text"] = "Дехто каже, що Сріблястий Похід уже залишився в минулому. Я один із них, але не тому, що Скара переможена.$b$bНі... через їхню впертість. Вони стали надто схожими на церкву, від якої відокремилися: надто негнучкими, надто залежними від честі й порядку. Принаймні це я намагаюся пояснити Бартоломею.$b$bМоже, звучить трохи войовничо, зате суперечка добра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1453975108] = {
        ["english"] = { [1] = "Take it easy, mon. I only train da warriors." },
        ["text"] = "Спокійно, мон. Я навчаю тільки воїнів.",
        ["npcs"] = { [1] = 3408 },
        ["roles"] = { ["greeting"] = true },
    },
    [849240935] = {
        ["english"] = { [1] = "These people arrived from Shattrath a few nights ago and they haven't stopped arguing since then.$B$BI'm glad to see that hasn't turned you away, I was beginning to think they were scaring off potential customers." },
        ["text"] = "Ці люди прибули із Шаттрата кілька ночей тому й відтоді не перестають сперечатися.$B$BРадий бачити, що тебе це не відлякало. Я вже починав думати, що вони розганяють потенційних клієнтів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1375011867] = {
        ["english"] = { [1] = "The Light be with ya, $c. How can I help ya?" },
        ["text"] = "Нехай Світло буде з тобою, $c. Чим можу допомогти?",
        ["npcs"] = { [1] = 926, [2] = 1232, [3] = 5147, [4] = 5148, [5] = 5149 },
        ["roles"] = { ["greeting"] = true },
    },
    [835547059] = {
        ["english"] = { [1] = "The content on the pages of this tome appear to be in constant flux. You feel as if your thoughts are being bled from your mind and consumed by the book." },
        ["text"] = "Зміст сторінок цього фоліанта постійно змінюється. Тобі здається, ніби думки витікають із твого розуму й поглинаються книгою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [516983449] = {
        ["english"] = { [1] = "Then what?" },
        ["text"] = "А далі що?",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [2327393076] = {
        ["english"] = { [1] = "The wind and trees whisper of unseen troubles.  The land appears healthy, but there's more going on here than meets the eye." },
        ["text"] = "Вітер і дерева шепочуть про невидимі біди. Земля здається здоровою, але тут відбувається більше, ніж видно оку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3945319750] = {
        ["english"] = { [1] = "Thank you for taking care of the lake, the lashers and the owlkin, $c." },
        ["text"] = "Дякую, що подбав про озеро, батожників і совозвірів, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [283670276] = {
        ["english"] = { [1] = "The Shaman Commander is not to be trifled with, $r." },
        ["text"] = "Із шаманом-командиром краще не жартувати, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3938314248] = {
        ["english"] = { [1] = "Tell me more about the Northern Crystal Pylon." },
        ["text"] = "Розкажи мені більше про Північний Кришталевий Пілон.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["reply"] = true },
    },
    [3420922792] = {
        ["english"] = { [1] = "This post is secure, $r.$b$bThe enemy has been cleared from the area for some time now." },
        ["text"] = "Цей пост у безпеці, $r.$b$bВорогів у цій місцевості вже давно немає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3509777618] = {
        ["english"] = { [1] = "Then listen well, $c.$B$BCan you feel the power radiating from me? Does your morale not swell? Aye, it is the same for the other side. To disrupt their defenses and thin out their troops will be no easy task, but it must be done! Victory will be ours!" },
        ["text"] = "Тоді слухай уважно, $c.$B$BВідчуваєш силу, що випромінюється від мене? Хіба твій бойовий дух не зростає? Так само й на іншому боці. Порушити їхню оборону й прорідити війська буде непросто, але це необхідно! Перемога буде нашою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3617109642] = {
        ["english"] = { [1] = "This hide isn't ready to work with yet. I wish it didn't take so long to make leather. There has to be some way to cut down on all this waiting. It can't be good for my health, you know?" },
        ["text"] = "Ця шкура ще не готова до обробки. Шкода, що виготовлення шкіри займає стільки часу. Мусить же бути спосіб скоротити все це очікування. Для здоров’я це точно не корисно, знаєте?",
        ["npcs"] = { [1] = 1466 },
        ["roles"] = { ["greeting"] = true },
    },
    [3523161415] = {
        ["english"] = { [1] = "The Syndicate have been reported to be nosing around in a cave on the eastern plateau. Find out what they're up to, soldier! Beware of Frostwolf activity!" },
        ["text"] = "Кажуть, Синдикат нишпорить у печері на східному плато. З'ясуй, що вони задумали, солдате! І стережися Морозних Вовків!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [366000299] = {
        ["english"] = { [1] = "The Lunar Festival is in full swing on Azeroth! Return there and honor your elders in this wonderful celebration! The main festivities can be found in Moonglade, but we've provided easy transportation from Stormwind, Ironforge, Darnassus, Thunder Bluff, Orgrimmar, and the Undercity. We hope to see you there!" },
        ["text"] = "Місячний фестиваль у самому розпалі по всьому Азероту! Повертайся й ушануй старійшин на цьому чудовому святі! Головні урочистості відбуваються в Місячній галявині, але ми забезпечили зручне перевезення зі Штормовію, Залізогарта, Дарнаса, Громового Бескиду, Орґріммара й Підмістя. Сподіваємося тебе там побачити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [282792857] = {
        ["english"] = { [1] = "Thanks to you our young ones will be safe, $N.  Go to Sporeggar and meet my people.  They've all heard great things about you." },
        ["text"] = "Завдяки тобі наші малята будуть у безпеці, $N. Іди до Спореґґара й познайомся з моїм народом. Вони вже чули про тебе багато доброго.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2810364685] = {
        ["english"] = { [1] = "Tell me about the Warlords Deck." },
        ["text"] = "Розкажи мені про Колоду Воєвод.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["reply"] = true },
    },
    [1631932197] = {
        ["english"] = { [1] = "Their minds are now tainted, $r. Yes, even more so than before. They live only to serve and protect Razelikh. The amulet fragments they each hold are the key to summoning the demon lord. What you do not understand is that none of them can be harmed through any conventional means." },
        ["text"] = "Їхні розуми тепер осквернені, $r. Так, ще більше, ніж раніше. Вони живуть лише для служіння й захисту Разеліха. Уламки амулета, які вони носять, — ключ до виклику повелителя демонів. Але ти не розумієш одного: жодного з них не можна поранити звичайними засобами.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [1027222491] = {
        ["english"] = { [1] = "The Lich King is attempting to make his presence known in our world. This must not be allowed to occur.\010" },
        ["text"] = "Король-ліч намагається заявити про свою присутність у нашому світі. Цього не можна допустити.\010",
        ["npcs"] = { [1] = 16113 },
        ["roles"] = { ["greeting"] = true },
    },
    [968929906] = {
        ["english"] = { [1] = "The continued sacrifice of the Ashen Verdict and heroes such as yourself bring us all closer to final victory. Now I have come to Icecrown Citadel to lend aid to those who fight against the Scourge. Together we will end the tyranny of the Lich King!" },
        ["text"] = "Невпинні жертви Попелястого Вироку й таких героїв, як ти, наближають нашу остаточну перемогу. Тепер я прибув до Цитаделі Крижаної Корони, щоб допомогти тим, хто бореться зі Скарою. Разом ми покладемо край тиранії Короля-ліча!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4191291929] = {
        ["english"] = { [1] = "This beam of greater moonlight will send you to Darnassus." },
        ["text"] = "Цей промінь посиленого місячного світла відправить тебе до Дарнаса.",
        ["npcs"] = { [1] = 15905 },
        ["roles"] = { ["greeting"] = true },
    },
    [464209329] = {
        ["english"] = { [1] = "This emitter is driving me nuts!  I'm missing all sorts of parts that I need to fix it." },
        ["text"] = "Цей випромінювач зводить мене з розуму! Мені бракує купи деталей, щоб його полагодити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1361144457] = {
        ["english"] = { [1] = "The zeppelin should just have departed from Undercity." },
        ["text"] = "Дирижабль щойно мав вирушити з Підмістя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2240321821] = {
        ["english"] = { [1] = "The zeppelin should just have arrived at Grom'gol." },
        ["text"] = "Дирижабль щойно мав прибути до Ґром'ґола.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2093036553] = {
        ["english"] = { [1] = "The zeppelin should have just reached Orgrimmar." },
        ["text"] = "Дирижабль щойно мав дістатися Орґріммара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2912401776] = {
        ["english"] = { [1] = "The Timberlings have made it too difficult for the fishermen to catch anything around Dolanaar.  You best look for someone to train you in Darnassus." },
        ["text"] = "Лісовики зробили риболовлю біля Доланаара майже неможливою. Краще пошукай когось, хто навчить тебе в Дарнасі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2823917026] = {
        ["english"] = { [1] = "The zeppelin should have just departed from Orgrimmar..." },
        ["text"] = "Дирижабль щойно мав вирушити з Орґріммара...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [495317558] = {
        ["english"] = { [1] = "The zeppelin should have just departed from Grom'gol..." },
        ["text"] = "Дирижабль щойно мав вирушити з Ґром'ґола...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [519547498] = {
        ["english"] = { [1] = "The Coldtooth Mine lies in Horde territory, in the mountains north of the Frostwolf Graveyard.$B$BIt is controlled by the Kobolds." },
        ["text"] = "Копальня Кригозубих лежить на території Орди, у горах на північ від кладовища Морозних Вовків.$B$BЇї контролюють кобольди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3153352046] = {
        ["english"] = { [1] = "Tell me your story again, Fizzcrank." },
        ["text"] = "Розкажи мені свою історію ще раз, Фіззкранку.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2818326267] = {
        ["english"] = { [1] = "The zeppelin should have just arrived at Orgrimmar..." },
        ["text"] = "Дирижабль щойно мав прибути до Орґріммара...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2589792738] = {
        ["english"] = { [1] = "The towers and bunkers in Alterac Valley are vital strategic locales.  If we control a tower, then our troops can fire great distances from it." },
        ["text"] = "Вежі й бункери Альтерацької долини — життєво важливі стратегічні об'єкти. Якщо ми контролюємо вежу, наші війська можуть вести з неї вогонь на великі відстані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1518948069] = {
        ["english"] = { [1] = "The yeti is a fierce, cunning creature, and this one is one of the strongest of his kind. We keep him asleep through herbs in his food.$b$bDo not think he will be lethargic in the ring, however." },
        ["text"] = "Єті — люта й хитра істота, а цей — один із найсильніших у своєму роді. Ми присипляємо його травами в їжі.$b$bАле не думай, що на арені він буде млявим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1826448057] = {
        ["english"] = { [1] = "The world is indebted to you and your allies, $N." },
        ["text"] = "Світ у боргу перед тобою й твоїми союзниками, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3488418310] = {
        ["english"] = { [1] = "Staff" },
        ["text"] = "Посох",
        ["npcs"] = { [1] = 11865, [2] = 11868, [3] = 11870, [4] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [623725733] = {
        ["english"] = { [1] = "Strength to the Clans, $c!  What brings you here?" },
        ["text"] = "Сили кланам, $c! Що привело тебе сюди?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [102553269] = {
        ["english"] = { [1] = "There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Alliance takes time to give something back to these innocents.  This time is called Children's Week.\010" },
        ["text"] = "Війна має свою ціну, $c... і про неї часто забувають. Ця ціна — сироти, діти, що втратили батьків у надто численних конфліктах, які вирують по всьому Азероту. Ті, кому більше нікуди йти, часто живуть тут, доки не стануть достатньо дорослими, щоб дбати про себе.$B$BОдин весняний тиждень на рік Альянс намагається щось повернути цим невинним. Цей час називається Дитячим тижнем.\010",
        ["npcs"] = { [1] = 14450 },
        ["roles"] = { ["greeting"] = true },
    },
    [3264077482] = {
        ["english"] = { [1] = "The Creators use visitation as a means to reestablish control over seeded worlds when forces, both external and internal, upset the matrix dynamics associated with it.  Such tactics are not to be taken lightly when executed by the Creators.$B$BFor additional information on this world's scheduled visitation, please consult the appropriate data repository that fields all Creator-related scheduling considerations." },
        ["text"] = "Творці здійснюють відвідини, щоб відновлювати контроль над засіяними світами, коли зовнішні чи внутрішні сили порушують пов'язану з ними динаміку матриці. Коли Творці вдаються до такого, це не варто сприймати легковажно.$B$BЩоб отримати додаткові відомості про заплановані відвідини цього світу, зверніться до відповідного сховища даних, що містить усі відомості про розклад Творців.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [3030353696] = {
        ["english"] = { [1] = "The first is a primal token that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.$B$BThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed Hoodoo piles.$B$BBring me these things and I will create a powerful enchantment for you!" },
        ["text"] = "Перше — первісний жетон, який треба забрати у наймогутніших помічників Гаккарі: Джин'до й Володаря Крові.$B$BДруге — проколота лялька вуду. Їх можна знайти в купах сміття по всьому цьому огидному місцю. Шукай у проклятих купах гуду.$B$BПринеси мені ці речі, і я створю для тебе могутнє зачарування!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2700549307] = {
        ["english"] = { [1] = "The Wind Rider Roost is atop the totem stairway in the center of town." },
        ["text"] = "Гніздо вітровершників розташоване нагорі тотемних сходів у центрі міста.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3779169238] = {
        ["english"] = { [1] = "The Rogue Trainer's name is Marion Call.  You can find her upstairs in the reading room at the Gallows' End Tavern at the town's southeast edge." },
        ["text"] = "Наставницю розбійників звати Маріон Колл. Її знайдеш нагорі в читальні таверни «Кінець Шибениці» на південно-східному краю міста.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2280052967] = {
        ["english"] = { [1] = "The wind rider master" },
        ["text"] = "Майстер вітровершників",
        ["npcs"] = { [1] = 3084, [2] = 3212, [3] = 3215, [4] = 3217, [5] = 3218, [6] = 3219, [7] = 3220, [8] = 3221, [9] = 3222, [10] = 3223, [11] = 3224, [12] = 3296, [13] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [3611156835] = {
        ["english"] = { [1] = "The Alliance has completed its gathering tasks, $c. Now, while we pack and prepare everything, we await the Horde's collections to be completed. Then we shall all transport our war materiel to Silithus." },
        ["text"] = "Альянс завершив усі завдання зі збору, $c. Тепер, поки ми пакуємо й готуємо все, лишається чекати, доки Орда завершить свої збори. Тоді всі разом перевеземо військові припаси до Силітуса.",
        ["npcs"] = { [1] = 15453 },
        ["roles"] = { ["greeting"] = true },
    },
    [831923632] = {
        ["english"] = { [1] = "Tell my family...$b$bMy last thoughts were of them..." },
        ["text"] = "Скажи моїй родині...$b$bОстанні мої думки були про них...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [937763213] = {
        ["english"] = { [1] = "Tell me about this proposal." },
        ["text"] = "Розкажи мені про цю пропозицію.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1739071953] = {
        ["english"] = { [1] = "Such a stark contrast, this holiday, to typical human behavior. Who'd have thought such a relentlessly voracious people would make a celebration of giving and sharing?$B$BIt's pleasant to see. Darnassus should do its utmost to support and encourage it." },
        ["text"] = "Який разючий контраст між цим святом і звичною людською поведінкою. Хто б міг подумати, що такий невситимий народ влаштує свято дарування й щедрості?$B$BПриємно це бачити. Дарнас має всіляко підтримувати й заохочувати таку традицію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3518419843] = {
        ["english"] = { [1] = "The war against the Horde has reached full tilt, $N.  This is a time of great need for the Alliance and it's quite necessary that all of us do our part to help." },
        ["text"] = "Війна проти Орди в розпалі, $N. Для Альянсу це час великої потреби, і кожен із нас мусить зробити свій внесок.",
        ["npcs"] = { [1] = 15351 },
        ["roles"] = { ["greeting"] = true },
    },
    [3846385460] = {
        ["english"] = { [1] = "Thank the Light for you!" },
        ["text"] = "Хвала Світлу за тебе!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [264144315] = {
        ["english"] = { [1] = "The past lives in these wastes, $c.  We must be careful to not awaken it." },
        ["text"] = "Минуле живе в цих пустках, $c. Треба бути обережними й не пробудити його.",
        ["npcs"] = { [1] = 13220 },
        ["roles"] = { ["greeting"] = true },
    },
    [731248162] = {
        ["english"] = { [1] = "The Waterlord Hydraxis hides off in Azshara, on an island in the Bay of Storms.  What kind of threat can the fool muster from there?" },
        ["text"] = "Володар Води Гідраксіс ховається в Азшарі на острові в затоці Штормів. Яку загрозу цей дурень узагалі може звідти створити?",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [1020599621] = {
        ["english"] = { [1] = "This book contains information on the plant species of Outland.  Most of the plants detailed are native to Zangarmarsh.$B$BThe charts and diagrams are a bit beyond your understanding.  Perhaps the author could give you some pointers." },
        ["text"] = "У цій книзі містяться відомості про рослинні види Позамежжя. Більшість описаних рослин походять із Занґарської трясовини.$B$BТаблиці й схеми дещо перевищують ваше розуміння. Можливо, автор зможе дати вам кілька порад.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2334402333] = {
        ["english"] = { [1] = "The wha-??$b$bWell, I refer to them as undefined floating obstructions. And where I'm from, most deny their existence entirely.$b$bBut I know better! I've even seen 'em up close! My recent years have been spent building this vessel to locate, track, document, and if needs be, eradicate them!" },
        ["text"] = "Що-о-??$b$bНу, я називаю їх невизначеними плавучими перешкодами. А там, звідки я родом, більшість узагалі заперечує їхнє існування.$b$bАле я знаю краще! Я навіть бачив їх зблизька! Останні роки я будував цей апарат, щоб знаходити, відстежувати, документувати й, за потреби, знищувати їх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3414008879] = {
        ["english"] = { [1] = "The spirits are greatly agitated. We must find the cause of this disturbance." },
        ["text"] = "Духи дуже схвильовані. Треба знайти причину цього неспокою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1733374874] = {
        ["english"] = { [1] = "This is a dangerous line of business!$B$BMiran just left with a delivery. He should be back in a few minutes." },
        ["text"] = "Небезпечна це справа!$B$BМіран щойно вирушив із доставкою. За кілька хвилин має повернутися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [901229847] = {
        ["english"] = { [1] = "The Bank of Orgrimmar is in the Valley of Strength. Look for it north of the main entrance to the city." },
        ["text"] = "Банк Орґріммара розташований у Долині Сили. Шукай на північ від головного входу до міста.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2486070655] = {
        ["english"] = { [1] = "The Thorium Brotherhood does not waste time on ants. Be gone!" },
        ["text"] = "Торієве братство не витрачає часу на мурах. Геть!",
        ["npcs"] = { [1] = 10637, [2] = 12944 },
        ["roles"] = { ["greeting"] = true },
    },
    [2693483906] = {
        ["english"] = { [1] = "The Darkmoon Faire will only be live for a short time before the curtains are drawn closed.  Be sure to visit it today!" },
        ["text"] = "Ярмарок Темного Місяця триватиме недовго, перш ніж завіса знову закриється. Обов'язково відвідай його сьогодні!",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["greeting"] = true },
    },
    [2293683231] = {
        ["english"] = { [1] = "The Trial of the Grand Crusader is a more difficult version of the Trial of the Crusader. Each encounter is more difficult, and you will not be able to freely attempt the encounters until you win. After 50 unsuccessful attempts, the Trial of the Grand Crusader will end for the week. After successfully completing the Trial of the Grand Crusader, you will receive an additional tribute chest of rewards as compensation. Are you prepared for this trial?" },
        ["text"] = "Випробування Великого Хрестоносця — складніша версія Випробування Хрестоносця. Кожна сутичка важча, і ти не зможеш безмежно повторювати спроби до перемоги. Після 50 невдалих спроб Випробування Великого Хрестоносця завершиться на цей тиждень. Після успішного проходження ти отримаєш додаткову скриню данини з нагородами. Готовий до цього випробування?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2261546553] = {
        ["english"] = { [1] = "The Ruins of Eldarath." },
        ["text"] = "Руїни Елдарата.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["reply"] = true },
    },
    [4080219888] = {
        ["english"] = { [1] = "The weapon master" },
        ["text"] = "Майстер зброї",
        ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [629444328] = {
        ["english"] = { [1] = "The Creators are cognizant of the magnitude of the information housed in this repository.  Subsequently, a portable copy of the data stored here will be made available to you once you are attuned with the Discs of Norgannon.$B$BPlease consider your cursory requirements for the assimilation of this knowledge to be complete.  At your leisure, access the Discs of Norgannon to begin synthesis of your discs." },
        ["text"] = "Творці усвідомлюють масштаб відомостей, що зберігаються в цьому сховищі. Тому після налаштування на Диски Норґаннона тобі буде надано переносну копію збережених тут даних.$B$BВважай початкові вимоги для засвоєння цих знань виконаними. Коли забажаєш, звернися до Дисків Норґаннона, щоб розпочати синтез власних дисків.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [4094198017] = {
        ["english"] = { [1] = "The Light of Elune shine upon thee $N!  You will find Aethalas, our battlemaster, on the Warrior's Terrace.  She will aid you on your way to Warsong Gulch." },
        ["text"] = "Нехай Світло Елуни осяює тебе, $N! Нашу воєначальницю Еталас знайдеш на Терасі Воїнів. Вона допоможе тобі дістатися Ущелини Пісні Війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1319397473] = {
        ["english"] = { [1] = "This monument is dedicated to all those who have fallen in the protection of Stormwind. Our people have weathered unbelievable hardships to retain their freedoms and to control their own destinies. It is here we remember every sacrifice our citizens have made during the first war that riddled our people." },
        ["text"] = "Цей пам’ятник присвячено всім, хто загинув, захищаючи Штормовій. Наш народ витримав неймовірні випробування, щоб зберегти свою свободу й право самим визначати власну долю. Тут ми пам’ятаємо кожну жертву, яку принесли наші громадяни під час Першої війни, що спустошила наш народ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4113300698] = {
        ["english"] = { [1] = "The preternatural ability of the crypt fiend to hunt and kill its foe is one studied and vaunted by men in my profession. I, myself, have slain thousands of the beasts in my crusade to rid this world of Scourge.$B$BWhile I loathe the crypt fiend for its merciless nature, its abilities must be admired. It has a job and it does it - very well." },
        ["text"] = "Надприродна здатність володаря склепу вистежувати й убивати ворога давно вивчається й шанується серед людей моєї професії. Я сам убив тисячі цих істот у своєму поході за очищення світу від Скари.$B$BЯ ненавиджу володарів склепу за їхню безжальність, але мушу захоплюватися їхніми здібностями. Вони мають роботу — і виконують її дуже добре.",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["greeting"] = true },
    },
    [2940111823] = {
        ["english"] = { [1] = "Thanks, $N.  If you hadn't shown up I'm sure we would have been dead meat!  Now the only thing between us and the chief troll is that door yonder..." },
        ["text"] = "Дякую, $N. Якби ти не з'явився, нас уже точно з'їли б! Тепер між нами й головним тролем стоять лише он ті двері...",
        ["npcs"] = { [1] = 7607 },
        ["roles"] = { ["greeting"] = true },
    },
    [682045478] = {
        ["english"] = { [1] = "The Royal Apothecary Society of the Undercity is eager to aid our orc allies here, in Outland.  It is an opportunity to strengthen our bonds, and to find new specimens and compounds for study.$B$BCompounds...such as poisons." },
        ["text"] = "Королівське товариство аптекарів Підмістя прагне допомогти нашим орчим союзникам тут, у Позамежжі. Це нагода зміцнити наші зв'язки й знайти нові зразки та сполуки для вивчення.$B$BСполуки... наприклад, отрути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [431780327] = {
        ["english"] = { [1] = "The waters of northern Sar'theris Strand in Desolace or the Angor Fortress in Badlands have locked boxes that can be picked open." },
        ["text"] = "У водах північної частини узбережжя Сар'теріс у Спустошищі або біля фортеці Анґора в Безплідних краях є замкнені скрині, які можна відімкнути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4224719556] = {
        ["english"] = { [1] = "The earth keeps many secrets, $c; it is our duty to ensure that those that must remain a secret for the good of all stays as such." },
        ["text"] = "Земля зберігає багато таємниць, $c; наш обов'язок — подбати, щоб ті, які мають лишитися таємницею задля загального добра, такими й лишилися.",
        ["npcs"] = { [1] = 5769 },
        ["roles"] = { ["greeting"] = true },
    },
    [1961114126] = {
        ["english"] = { [1] = "The Lord of Blackrock hangs from the arches!" },
        ["text"] = "Володар Чорнокаменю висить на арках!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3563274225] = {
        ["english"] = { [1] = "The Warchief brings change that will bring the Horde victory!  Look for Swart inside the barracks on the east side of town." },
        ["text"] = "Вождь несе зміни, що приведуть Орду до перемоги! Шукай Сварта в казармах на східному боці міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2338038478] = {
        ["english"] = { [1] = "Strength and honor, $c. We need eager soldiers like you in Alterac Valley; the territory of the Frostwolves must be defended! Will you return to Azeroth and lend your aid?" },
        ["text"] = "Сила й честь, $c. Нам потрібні завзяті воїни, як ти, в Альтерацькій долині; землі Морозних Вовків треба захистити! Повернешся до Азероту й допоможеш нам?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [786403702] = {
        ["english"] = { [1] = "The Wailing Caverns has its entrance at the Lushwater Oasis southwest of Crossroads in the Barrens.   " },
        ["text"] = "Вхід до Печер Стогону розташований біля оази Буйнозелень на південний захід від Роздоріжжя в Степах.   ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1504267905] = {
        ["english"] = { [1] = "Thank you for the inquiry, $c, but as you can see, I already have all of the linen bandages that the Alliance feels is necessary in preparation for the war at Ahn'Qiraj. Don't let that stop you from helping out with the other collections going on here though." },
        ["text"] = "Дякую за цікавість, $c, але, як бачиш, у мене вже є всі лляні бинти, які Альянс вважає потрібними для підготовки до війни в Ан'Кіражі. Та це не означає, що не треба допомагати з іншими зборами, які тут тривають.",
        ["npcs"] = { [1] = 15451 },
        ["roles"] = { ["greeting"] = true },
    },
    [2383454566] = {
        ["english"] = { [1] = "The Scourge infestation grows in Azshara. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2279W" },
        ["text"] = "Навала Скари посилюється в Азшарі. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2279W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [2325153797] = {
        ["english"] = { [1] = "The Order of the Shattered Hand existed before Thrall and shall exist after Thrall. " },
        ["text"] = "Орден Розтрощеної Десниці існував до Тралла й існуватиме після нього.",
        ["npcs"] = { [1] = 3401 },
        ["roles"] = { ["greeting"] = true },
    },
    [1880645976] = {
        ["english"] = { [1] = "There are plants in Felwood that may be saved from corruption when Cenarion plant salve is applied to them.  I know how to make the salve from several different kinds of items; based on your skill set, you may find that you have multiple options to assist me.$B$BYou will also need a Cenarion beacon for your work here; it is a device that allows you to see the taint and corruption of nature that the naked eye will miss." },
        ["text"] = "У Скверноліссі є рослини, які можна врятувати від осквернення, якщо застосувати до них кенарійську рослинну мазь. Я знаю, як виготовляти мазь із кількох видів предметів; залежно від твоїх умінь, у тебе може бути кілька способів допомогти.$B$BДля роботи тут тобі також знадобиться Кенарійський маяк — пристрій, який дозволяє бачити зараження й осквернення природи, невидимі неозброєним оком.",
        ["npcs"] = { [1] = 9528, [2] = 9529 },
        ["roles"] = { ["greeting"] = true },
    },
    [1843153027] = {
        ["english"] = { [1] = "The secrets behind the power of the Colossus could lead to all sorts of innovations in science!" },
        ["text"] = "Таємниці сили Колоса можуть привести до безлічі наукових відкриттів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1484059568] = {
        ["english"] = { [1] = "The console appears ancient though there is no sign of dilapidation or decay.  A single slot appears to fit large circular discs." },
        ["text"] = "Пристрій виглядає дуже стародавнім, хоча на ньому немає слідів занепаду чи руйнування. Один проріз, схоже, призначений для великих круглих дисків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4275022491] = {
        ["english"] = { [1] = "The Argent Dawn salutes you, $c!  The name's Lightspark, and I'm an authorized equipment and materiel quartermaster for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Officer Pureheart.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." },
        ["text"] = "Сріблястий Світанок вітає тебе, $c! Мене звати Світлоіскр, і я уповноважений квартирмейстер Світанку зі спорядження та припасів.$B$BБорючись зі злом за нашим дорученням і здобуваючи нашу повагу й довіру, ти отримуватимеш жетони доблесті від офіцера Чистосерда. Жетони мають два призначення: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде твоє становище у Світанку, то більше предметів стануть тобі доступні.",
        ["npcs"] = { [1] = 10857 },
        ["roles"] = { ["greeting"] = true },
    },
    [1682596249] = {
        ["english"] = { [1] = "There, there, $N, worry not! Which piece of the amulet have you misplaced?$B$BDid you check all of your bags and the bank?" },
        ["text"] = "Ну-ну, $N, не хвилюйся! Яку частину амулета ти загубив?$B$BПеревірив усі сумки й банк?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3261418748] = {
        ["english"] = { [1] = "The markings of this tablet show ancient diagrams and hold dire words of power, but their meaning is inscrutable to you." },
        ["text"] = "Позначки на цій табличці утворюють стародавні схеми й зловісні слова сили, але їхній зміст для тебе незрозумілий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [801179451] = {
        ["english"] = { [1] = "Sunken Temple" },
        ["text"] = "Затонулий храм",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [1159873942] = {
        ["english"] = { [1] = "Start making sense, dwarf. I don't want to have anything to do with your cracker, your pappy, or any sort of 'discreditin.'", [2] = "Start making sense, dwarf. I don't want to have anything to do with your cracker, your pappy, or any sort of 'discreditin.'\010" },
        ["text"] = "Говори до ладу, дворфе. Я не хочу мати нічого спільного ні з твоїм сухарем, ні з твоїм татусем, ні з якимось там «ганьбленням».",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [2657823202] = {
        ["english"] = { [1] = "The village of Astranaar in Ashenvale is Elder Riversong's current home." },
        ["text"] = "Селище Астранаар у Ясенедолі — теперішній дім старійшини Річкової Пісні.",
        ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15603 },
        ["roles"] = { ["greeting"] = true },
    },
    [1286636943] = {
        ["english"] = { [1] = "The Creators are... the Creators.$B$BThey are the beings that seeded and shaped this world by their own design.  They are the reason for this world's existence, as well as many other worlds.  They are the wellspring from which Azeroth flows." },
        ["text"] = "Творці — це... Творці.$B$BЦе істоти, які засіяли й сформували цей світ за власним задумом. Завдяки їм існує цей світ і багато інших. Вони — джерело, з якого бере початок Азерот.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1460291845] = {
        ["english"] = { [1] = "The view from the top of Telredor is magnificent, isn't it?" },
        ["text"] = "Вид із вершини Телредора величний, чи не так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3038857943] = {
        ["english"] = { [1] = "There is one master of the sword: Woo Ping. He can be found in Weller's Arsenal within Stormwind." },
        ["text"] = "Є лише один майстер меча — Ву Пін. Його знайдеш в Арсеналі Веллера в Штормовії.",
        ["npcs"] = { [1] = 11865, [2] = 11866, [3] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [436851306] = {
        ["english"] = { [1] = "There are basics that must be learned. Trianna is standing nearby, speak with her and return to me later." },
        ["text"] = "Є основи, які треба засвоїти. Тріанна стоїть неподалік; поговори з нею й повернися до мене пізніше.",
        ["npcs"] = { [1] = 4159 },
        ["roles"] = { ["greeting"] = true },
    },
    [1183489561] = {
        ["english"] = { [1] = "The Val'kyrs'  teamwork is rather astounding. I now see why we had such problems capturing the two of them." },
        ["text"] = "Злагодженість валь'кір справді вражає. Тепер я розумію, чому нам було так важко схопити їх обох.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4267140287] = {
        ["english"] = { [1] = "The Icewing Bunker holds the pass between Alliance territory and the Field of Strife.$B$BIt is controlled by the Alliance." },
        ["text"] = "Бункер Крижаного Крила утримує перевал між територією Альянсу й Полем Боротьби.$B$BЙого контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1406132556] = {
        ["english"] = { [1] = "This is incredible! You're covered in potent, virulent, fantastic blight! Please, allow me to harvest these pristine samples. I will remove any lingering infection from your allies as well, and reward you all for your bravery and self-sacrifice in the name of medicine! Let me know if you are ready to proceed.$B$B[Before proceeding, make sure that ALL raid members are nearby in order for them to receive credit for your accomplishment.]" },
        ["text"] = "Неймовірно! Ви вкриті могутньою, вірулентною, пречудовою пошестю! Дозвольте мені зібрати ці бездоганні зразки. Я також усуну рештки зараження з ваших союзників і винагороджу вас усіх за відвагу та самопожертву в ім’я медицини! Скажіть, коли будете готові продовжити.$B$B[Перш ніж продовжити, переконайтеся, що ВСІ учасники рейду перебувають поблизу, щоб вони також отримали зарахування вашого досягнення.]",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1993534243] = {
        ["english"] = { [1] = "The U.D.E.D. dispenser rumbles at you expectantly." },
        ["text"] = "Роздавальний пристрій U.D.E.D. очікувально гуркоче перед тобою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1030454293] = {
        ["english"] = { [1] = "The dragon hides behind a royal facade. The tablets will reveal her for what she is... If what I have seen holds true, I will not survive this battle, friend. It is you that must finish what I have started. Are your forces ready? Are you ready? We will begin on your command." },
        ["text"] = "Дракониця ховається за королівською личиною. Таблички покажуть її справжню сутність... Якщо моє видіння правдиве, я не переживу цієї битви, друже. Ти мусиш завершити те, що я почав. Твої сили готові? Ти готовий? Почнемо за твоїм наказом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3175165246] = {
        ["english"] = { [1] = "The corruption of a fallen titan. The corruption of the Destroyer. After all, the staff was forged from the seed of hate. That is, of course, what has brought me here..." },
        ["text"] = "Осквернення полеглого титана. Осквернення Руйнівника. Зрештою, посох викували з насіння ненависті. Саме це, звісно, й привело мене сюди...",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [4095640480] = {
        ["english"] = { [1] = "Thank you for freeing me, $r.$b$bI'm still a bit woozy from the venom. I think I'll stay here until my strength returns." },
        ["text"] = "Дякую, що звільнив мене, $r.$b$bВід отрути в голові ще трохи паморочиться. Думаю, я побуду тут, доки не повернуться сили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3313259288] = {
        ["english"] = { [1] = "The final battle will begin soon, $N. Stand at attention!" },
        ["text"] = "Остаточна битва скоро почнеться, $N. Струнко!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2845637525] = {
        ["english"] = { [1] = "The true believers have lived in shame since the day our treacherous cousins in Skettis stole the book from us, shattered its tablet, and buried the fragments in their wretched city!$B$BPray that the raven will choose you to restore it, my son. Be faithful and remember always the prophecy, \"From the dreams of his enemies shall the raven spring forth into the world.\"" },
        ["text"] = "Істинні віряни жили в ганьбі відтоді, як наші зрадливі родичі зі Скеттіса вкрали в нас книгу, розбили її табличку й поховали уламки у своєму жалюгідному місті!$B$BМолися, щоб ворон обрав тебе для її відновлення, сину мій. Будь вірним і завжди пам'ятай пророцтво: «Зі снів своїх ворогів ворон постане у світ».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [420939624] = {
        ["english"] = { [1] = "The trickster Mage-Lord Urom protects the third ring.  He will appear alone and defenseless, but do not be fooled by appearances!  Urom is a powerful conjurer who commands a menagerie of Phantasmal creatures.  Seek him out above.$B$BI can grant you the power to call upon a drake from the Red Fight.  Speak to Eternos or Verdisa if you prefer to draw on the power of the Bronze or the Green." },
        ["text"] = "Підступний маг-лорд Уром захищає третє кільце. Він з'явиться сам і беззахисний, але не дай зовнішності себе обманути! Уром — могутній заклинач, що керує цілою звіринцем примарних істот. Шукай його вище.$B$BЯ можу дарувати тобі силу покликати дракона Червоної зграї. Поговори з Етерносом або Вердісою, якщо волієш силу Бронзової чи Зеленої.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2640932714] = {
        ["english"] = { [1] = "Swords, claws, daggers, of course -- I've trained rogues in the use of them all. Now maces, I won't touch maces and I won't instruct any rogue who gets it in his head to wield one.$B$BThere's nothing stealthy about a mace. You're in for a noisy kill and a long cleanup if you go that route." },
        ["text"] = "Мечі, кігті, кинджали — звісно, я навчив розбійників користуватися ними всіма. А от булави — до булав я не торкнуся й не навчатиму жодного розбійника, якому заманеться таку взяти.$B$BУ булаві немає нічого непомітного. Якщо підеш цим шляхом, убивство буде гучним, а прибирання — довгим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3929503239] = {
        ["english"] = { [1] = "That's it!  I'm tired of helping you out.  It's time we settled things on the battlefield!" },
        ["text"] = "Годі! Я втомився тобі допомагати. Час з'ясувати стосунки на полі бою!",
        ["npcs"] = { [1] = 7604 },
        ["roles"] = { ["reply"] = true },
    },
    [3419319841] = {
        ["english"] = { [1] = "The Zandalarian trolls have traveled far and suffered much to reach this place, but to do nothing... is to invite our doom..." },
        ["text"] = "Зандаларські тролі подолали далекий шлях і багато вистраждали, щоб дістатися сюди, але нічого не робити... означає накликати на себе загибель...",
        ["npcs"] = { [1] = 15080 },
        ["roles"] = { ["greeting"] = true },
    },
    [1710142677] = {
        ["english"] = { [1] = "The tower's defenses are at their weakest right now. The patrollers, sentries, lookouts, and even Gallywix himself are all infected and highly vulnerable to your special abilities and attacks.$B$BI want to see you enter that tower and when you exit, I want to see you covered in the blood of your enemies, the head of Grand Foreman Puzik Gallywix in your hands, and the last of that poison in your pack. Take what you recover to Shenthul. He'll know what to do... I hope.$b" },
        ["text"] = "Захист вежі зараз найслабший. Патрульні, вартові, спостерігачі й навіть сам Ґаллівікс заражені й надзвичайно вразливі до твоїх особливих здібностей та атак.$B$BЯ хочу, щоб ти ввійшов у ту вежу, а коли вийдеш — був укритий кров'ю ворогів, тримав у руках голову головного виконроба Пузіка Ґаллівікса, а в наплічнику мав решту отрути. Віднеси все Шентулу. Він знатиме, що робити... сподіваюся.$b",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1373519328] = {
        ["english"] = { [1] = "The data stored in this repository does indeed correlate with your astute proclamation.$B$BThe dwarf maintains an affinity for the stone composition of Azeroth, but due to the high-stress environmental anomaly within the Earthen's synthesis matrix, the dwarf reverts to a default biomass composition as seen in the standard subterranean matrix.$B$BErgo, the dwarf variant does synthesize from the degeneration of the Earthen creation matrix, as you inferred with your query." },
        ["text"] = "Дані, що зберігаються в цьому сховищі, справді відповідають твоєму проникливому твердженню.$B$BДворф зберігає спорідненість із кам'яною будовою Азероту, але через високонавантажену аномалію середовища в матриці синтезу земельників дворф повертається до стандартного складу біомаси, як у звичайній підземній матриці.$B$BОтже, варіант дворфа дійсно синтезується внаслідок деградації матриці створення земельників, як ти й припустив у своєму запиті.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [2201403600] = {
        ["english"] = { [1] = "The title of this book reads with a handwritten flourish: Maureen Dalson's Diary." },
        ["text"] = "Назву цієї книги виведено рукописним розчерком: «Щоденник Морін Далсон».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2231073632] = {
        ["english"] = { [1] = "Thank you, Ironbark. We are ready for you to open the door." },
        ["text"] = "Дякую, Залізнокоре. Ми готові, відчиняй двері.",
        ["npcs"] = { [1] = 11491, [2] = 14241 },
        ["roles"] = { ["reply"] = true },
    },
    [565405596] = {
        ["english"] = { [1] = "Staves are taught by both Woo Ping, the master found at Weller's Arsenal in Stormwind, and Ilyenia Moonfire, who trains the night elves on the Warrior's Terrace in Darnassus." },
        ["text"] = "Володінню посохами навчають двоє: Ву Пін, майстер із Арсеналу Веллера у Штормовії, та Іленія Місячний Вогонь, яка тренує нічних ельфів на Терасі Воїнів у Дарнасі.",
        ["npcs"] = { [1] = 11865, [2] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3841232171] = {
        ["english"] = { [1] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold the strongest of mojo used by the old Empire.$B$BYa can expect to be findin' three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with the some of the finest items we Zandalar have ever crafted.$B$BCount on it, mon!\010\010" },
        ["text"] = "Зразки Могутності — рештки давньої Імперії Ґурубаші. Ми, зандалари, шукаємо їх не лише через величезну колекційну цінність, а й тому, що вважаємо: в них зберігається найсильніше моджо старої Імперії.$B$BУ Зул'Ґурубі ти, певно, знайдеш три види Зразків: монети, біжу та первісні предмети. Принось їх у потрібній кількості, й отримаєш у нагороду одні з найкращих речей, які коли-небудь створювали зандалари.$B$BМожеш на це розраховувати, мон!\010\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2603155103] = {
        ["english"] = { [1] = "Such sssorrow... The passst cannot be undone..." },
        ["text"] = "Ссстільки ссскорботи... Минулого не повернути...",
        ["npcs"] = { [1] = 10684 },
        ["roles"] = { ["greeting"] = true },
    },
    [2189334213] = {
        ["english"] = { [1] = "This Dimensional Imploder sounds dangerous!  How can I make one?" },
        ["text"] = "Цей Просторовий Імплодер звучить небезпечно! Як мені його зробити?",
        ["npcs"] = { [1] = 14742 },
        ["roles"] = { ["reply"] = true },
    },
    [173743912] = {
        ["english"] = { [1] = "Tell me what's going on out here, Fizzcrank." },
        ["text"] = "Розкажи, що тут відбувається, Фіззкранку.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [201661583] = {
        ["english"] = { [1] = "There is a Blacksmithing Trainer in our great home Thunder Bluff to the north.  If you seek such knowledge then head there and ask one of the Bluffwatchers for directions." },
        ["text"] = "У нашому великому домі, Громовому Бескиді на півночі, є наставник ковальства. Якщо шукаєш таких знань, вирушай туди й попроси одного з вартових Бескиду показати дорогу.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1044936271] = {
        ["english"] = { [1] = "The time for war is almost upon us, $c! Both the Horde and the Alliance have finished with their preparations. All of our war materiel is being shipped to Silithus as we speak. I'd expect the last of it to arrive within a day. When all is assembled there, the one who has completed the arduous task of reassembling the Scepter of the Shifting Sands will bang it against the Scarab Gong and open the gates to Ahn'Qiraj. Then battle shall be joined as has not been seen in ages!$B$BLok'tar Ogar!" },
        ["text"] = "Час війни майже настав, $c! І Орда, і Альянс завершили підготовку. Усі наші військові припаси вже везуть до Силітуса. Гадаю, останні прибудуть протягом дня. Коли там усе зберуть, той, хто виконав тяжке завдання відновлення Скіпетра Мінливих Пісків, ударить ним у Гонг Скарабея й відчинить брами Ан'Кіражу. Тоді почнеться битва, якої не бачили століттями!$B$BЛок'тар Оґар!",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [372199009] = {
        ["english"] = { [1] = "The time for war is almost upon us, $c! Both the Horde and the Alliance have finished with their preparations. All of our war materiel is being shipped to Silithus as we speak. I'd expect it all to arrive within $2113w days. When all is assembled there, the one who has completed the arduous task of reassembling the Scepter of the Shifting Sands will bang it against the Scarab Gong and open the gates to Ahn'Qiraj. Then battle shall be joined as has not been seen in ages!$B$BLok'tar Ogar!" },
        ["text"] = "Час війни майже настав, $c! І Орда, і Альянс завершили підготовку. Усі наші військові припаси вже везуть до Силітуса. Гадаю, все прибуде протягом $2113w днів. Коли там усе зберуть, той, хто виконав тяжке завдання відновлення Скіпетра Мінливих Пісків, ударить ним у Гонг Скарабея й відчинить брами Ан'Кіражу. Тоді почнеться битва, якої не бачили століттями!$B$BЛок'тар Оґар!",
        ["npcs"] = { [1] = 15700, [2] = 15704 },
        ["roles"] = { ["greeting"] = true },
    },
    [567463994] = {
        ["english"] = { [1] = "The Timbermaw furbolgs." },
        ["text"] = "Фурболґи Деревопащі.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["reply"] = true },
    },
    [542413680] = {
        ["english"] = { [1] = "The zeppelin should have just departed from Undercity." },
        ["text"] = "Дирижабль щойно мав вирушити з Підмістя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [458005951] = {
        ["english"] = { [1] = "This entire holiday is nonsensical. Colored eggs and \"life affirmation,\" bah." },
        ["text"] = "Усе це свято — суцільна нісенітниця. Кольорові яйця та «утвердження життя»... Пхе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4073657555] = {
        ["english"] = { [1] = "Thank you for your time" },
        ["text"] = "Дякую за твій час",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4292008422] = {
        ["english"] = { [1] = "The Burning Steppes is a dangerous place, but scholars like me will do almost anything to advance our knowledge." },
        ["text"] = "Палаючий степ — небезпечне місце, але вчені на кшталт мене готові майже на все заради нових знань.",
        ["npcs"] = { [1] = 10267 },
        ["roles"] = { ["greeting"] = true },
    },
    [3991022062] = {
        ["english"] = { [1] = "The land of Feralas has been through much, $r. The earth, the trees, the creatures; they are all changing what Feralas is and will be.$B$BThe Twin Colossals above us remain as a constant, though, throughout all that has happened here..." },
        ["text"] = "Фералас пережив багато, $r. Земля, дерева, істоти — усе це змінює те, чим Фералас є і чим стане.$B$BА два Колоси над нами лишаються незмінними попри все, що тут сталося...",
        ["npcs"] = { [1] = 7773 },
        ["roles"] = { ["greeting"] = true },
    },
    [2578933544] = {
        ["english"] = { [1] = "The things I have done... such horrible things...$B$B<Tarsis begins to sob.>\010" },
        ["text"] = "Те, що я зробив... такі жахливі речі...$B$B<Тарсіс починає ридати.>\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3880196443] = {
        ["english"] = { [1] = "The Thorium Brotherhood Fall Catalogue:$B$BInside you will find the hottest deals on all of your adventuring needs! We'll even show you where to pick up those difficult to find components and supplies." },
        ["text"] = "Осінній каталог Торієвого братства:$B$BУсередині знайдеш найгарячіші пропозиції на все необхідне для пригод! Ми навіть покажемо, де дістати рідкісні компоненти й припаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [692306611] = {
        ["english"] = { [1] = "The theory behind it is that we completely destroy you with a massive explosion wherever you are and send those particles through a dimensional rip and then re-implode you at the maschine here. Instant Transport! It might not work ALL the time, but what kind of goblin engineer are you! If survival was your first priority you could never be a real Goblin Engineer! Here is the recipe you will need to make the Dimensional Ripper and try it out!" },
        ["text"] = "Теорія така: де б ти не був, ми повністю знищуємо тебе величезним вибухом, пропускаємо частинки через просторовий розлом, а потім знову стягуємо тебе докупи в цій машині. Миттєве переміщення! Воно може спрацьовувати НЕ завжди, але який же ти тоді ґоблінський інженер! Якби виживання було твоїм головним пріоритетом, ти ніколи не став би справжнім ґоблінським інженером! Ось рецепт, потрібний для створення Просторового Роздирача. Спробуй!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4018614123] = {
        ["english"] = { [1] = "The Temple of the Moon is home to the priests of Elune.  There you will find Jandria and Lariia, who will provide you with further guidance in the path of priesthood." },
        ["text"] = "Храм Місяця — оселя жриць Елуни. Там знайдеш Джандрію та Ларію, які дадуть подальші настанови на шляху жерця.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3293815155] = {
        ["english"] = { [1] = "Stand at attention, captain!" },
        ["text"] = "Струнко, капітане!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3167662088] = {
        ["english"] = { [1] = "The taking of Crusaders' Pinnacle is only the first step in a long and dangerous journey. There is much left to do before we are able to assault Icecrown Citadel.$B$BIt can only be possible with help from you and others like you, hero." },
        ["text"] = "Захоплення Верхів'я Хрестоносців — лише перший крок у довгій і небезпечній подорожі. Ще багато чого треба зробити, перш ніж ми зможемо штурмувати Цитадель Крижаної Корони.$B$BЦе можливо лише з допомогою тебе й таких, як ти, герою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [680103353] = {
        ["english"] = { [1] = "The All Seeing Eye must be recovered!" },
        ["text"] = "Всевидяче Око треба повернути!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [354448695] = {
        ["english"] = { [1] = "They can't keep this up! Their wings will eventually give..." },
        ["text"] = "Вони не зможуть так довго! Крила зрештою не витримають...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2093690893] = {
        ["english"] = { [1] = "Tell me more about Forging Armor." },
        ["text"] = "Розкажи мені більше про кування обладунків.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [396504518] = {
        ["english"] = { [1] = "The Syndicate keeps many locked boxes of supplies in Durnholde Keep in Hillsbrad." },
        ["text"] = "Синдикат зберігає багато замкнених скринь із припасами у фортеці Дарнгольд у Гіллзбрадовому передгір'ї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3820931256] = {
        ["english"] = { [1] = "The first steps of our fight against the Scourge go well. We have had some successes, and hopefully my assistance can aid you in bringing future success to the battle." },
        ["text"] = "Перші кроки нашої боротьби зі Скарою йдуть добре. Ми вже досягли певних успіхів, і сподіваюся, моя допомога дасть тобі змогу здобути ще більше перемог.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2821257703] = {
        ["english"] = { [1] = "They have no respect for the dead, $r. The ogres must be taught a lesson." },
        ["text"] = "Вони не поважають мертвих, $r. Огрів треба провчити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3896719190] = {
        ["english"] = { [1] = "Terrible thing, what happened to them mules... Metz is gonna have my hide for this failure." },
        ["text"] = "Жахлива справа з тими мулами... Метц шкуру з мене спустить за цей провал.",
        ["npcs"] = { [1] = 16226 },
        ["roles"] = { ["greeting"] = true },
    },
    [1214104245] = {
        ["english"] = { [1] = "Stable Master" },
        ["text"] = "Господар стайні",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076, [14] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [4291021341] = {
        ["english"] = { [1] = "The auction house can be found on the central spire of Thunder Bluff.  Search near the bottom of the Windrider's Tower. May your ancestors watch over you." },
        ["text"] = "Аукціонний дім розташований на центральному шпилі Громового Бескиду. Шукай біля підніжжя Вежі Вітровершників. Нехай предки оберігають тебе.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1699658921] = {
        ["english"] = { [1] = "The door is open, Kharan. You are a free man." },
        ["text"] = "Двері відчинено, Харане. Ти вільний.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [1553605212] = {
        ["english"] = { [1] = "This beam of moonlight leads to the Undercity.  Retire when ready." },
        ["text"] = "Цей промінь місячного сяйва веде до Підміста. Повертайтеся, коли будете готові.",
        ["npcs"] = { [1] = 15907 },
        ["roles"] = { ["greeting"] = true },
    },
    [2591657221] = {
        ["english"] = { [1] = "The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows." },
        ["text"] = "Затонулий храм розташований посеред великого озера у східній частині Болота Скорботи.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [750809033] = {
        ["english"] = { [1] = "Stop - no. Slow down - maybe.$B$BThe Scholomance is their primary source of training and education. It is from there that the Cult members fan out and ultimately, make their way into our societies.$B$BThat is why we must strike at the source. The very heart of the Cult of the Damned!" },
        ["text"] = "Зупинитися — ні. Пригальмувати — можливо.$B$BНекроситет — їхнє головне місце навчання й підготовки. Саме звідти члени Культу розходяться світом і зрештою проникають у наше суспільство.$B$BТому ми мусимо вдарити по джерелу. У саме серце Культу Проклятих!",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [2323451589] = {
        ["english"] = { [1] = "The exiles of Gnomeregan find ourselves in even more dire straits by running low on cloth reserves!  Perhaps you can help us, eh?!$B$BBring me extra cloth pieces you might have to help us replenish our stocks.  By donating them, you'll be earning the respect and trust of gnomes everywhere.  That's something that money can't buy!  Well, I guess cloth does, but that's beside the point..." },
        ["text"] = "Ми, вигнанці з Гномреґана, потрапили в ще скрутніше становище — запаси тканини майже вичерпано! Може, допоможеш, га?!$B$BПринось зайві шматки тканини, які знайдеш, щоб поповнити наші запаси. Жертвуючи їх, ти здобуватимеш повагу й довіру гномів усюди. Такого за гроші не купиш! Ну, хіба що тканину можна... але то вже інше.",
        ["npcs"] = { [1] = 14724 },
        ["roles"] = { ["greeting"] = true },
    },
    [493989524] = {
        ["english"] = { [1] = "The sturdy crate sits in the middle of the lumber mill surrounded by debris and very zealous followers of the Scarlet Crusade." },
        ["text"] = "Міцна скриня стоїть посеред лісопильні, оточена уламками й надзвичайно завзятими послідовниками Багряного Походу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1529359094] = {
        ["english"] = { [1] = "These mines are a dreadful place.  Fortunately, I don't plan on being here long." },
        ["text"] = "Ці копальні — жахливе місце. На щастя, я не збираюся довго тут лишатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [341676555] = {
        ["english"] = { [1] = "The Headless Horseman attacks!  The fires threaten to consume the whole village!  What will we do?" },
        ["text"] = "Вершник без голови атакує! Вогонь ось-ось поглине все селище! Що ж нам робити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [688525729] = {
        ["english"] = { [1] = "Thanks for getting me out of there. I owe you one!" },
        ["text"] = "Дякую, що витяг мене звідти. Я твій боржник!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [230101016] = {
        ["english"] = { [1] = "That's the second building on the right in the Valley of Strength north of the main city entrance.  Speak to Innkeeper Gryshka." },
        ["text"] = "Це друга будівля праворуч у Долині Сили, на північ від головного входу до міста. Поговори з корчмаркою Ґришкою.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2807267169] = {
        ["english"] = { [1] = "The celebration of the feast of Winter Veil is a source of great warmth during the cold seasons, and its heart is in Orgrimmar." },
        ["text"] = "Свято Зимового Покрову дарує велике тепло в холодну пору року, а його серце — в Орґріммарі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2970814180] = {
        ["english"] = { [1] = "This pie is so good, would you like some?" },
        ["text"] = "Цей пиріг такий смачний. Хочете шматочок?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1019491808] = {
        ["english"] = { [1] = "The opening of the Dark Portal brought news of my people's fate. In a way, my exile shielded me from sharing in their downfall, but to see the Farstriders throw their lot in with Kael'thas...$B$BI never imagined my one-time brethren capable of such a thing.$B$BThe homecoming I once dreamt of will never happen. This forest is the only home I have left." },
        ["text"] = "Відкриття Темного порталу принесло звістку про долю мого народу. У певному сенсі вигнання вберегло мене від їхнього падіння, але побачити, як Далекоходці стали на бік Кель'таса...$B$BЯ ніколи не думав, що мої колишні побратими здатні на таке.$B$BПовернення додому, про яке я колись мріяв, уже не станеться. Цей ліс — єдиний дім, що в мене лишився.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3374114541] = {
        ["english"] = { [1] = "The Park is where you want to go if you are looking for druid trainers. Theridan and Maldryn can usually be found by the moonwell in the center of the district." },
        ["text"] = "Якщо шукаєш наставників друїдів, тобі до Парку. Терідана й Малдріна зазвичай можна знайти біля місячного колодязя в центрі району.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1696818448] = {
        ["english"] = { [1] = "The Stormwind Stockades are found near the mage quarter in Stormwind." },
        ["text"] = "Штормовійська В'язниця розташована біля кварталу магів у Штормовії.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1545003478] = {
        ["english"] = { [1] = "The Horde is stockpiling a great many bandages. So far $2079w out of $2080w wool bandages have been collected. $2085w out of $2086w mageweave bandages have been created. And $2089w out of $2090w runecloth bandages have been gathered." },
        ["text"] = "Орда накопичує величезні запаси бинтів. Уже зібрано $2079w із $2080w вовняних бинтів, виготовлено $2085w із $2086w бинтів із маготканини й зібрано $2089w із $2090w бинтів із рунічної тканини.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [2018460519] = {
        ["english"] = { [1] = "The Darkmoon Faire is coming to town!  Don't miss it!" },
        ["text"] = "Ярмарок Темного Місяця скоро прибуде до міста! Не пропусти!",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["greeting"] = true },
    },
    [1841313760] = {
        ["english"] = { [1] = "The Stormpike Guard is in need of your assistance in the fight against the Frostwolf Clan, $N. Speak to Brogun Stoneshield on the Warrior's Terrace and he will help you find your way to Alterac Valley. Elune be praised!" },
        ["text"] = "Варті Бурешпиля потрібна твоя допомога в боротьбі проти клану Морозних Вовків, $N. Поговори з Броґуном Кам'яним Щитом на Терасі Воїнів, і він допоможе знайти шлях до Альтерацької долини. Хвала Елуні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [492263011] = {
        ["english"] = { [1] = "The Stormpike Guard is in need of your assistance in the fight against the Frostwolf Clan, $N.  Speak to Brogun Stoneshield on the Warrior's Terrace and he will help you find your way to Alterac Valley." },
        ["text"] = "Варті Бурешпиля потрібна твоя допомога в боротьбі проти клану Морозних Вовків, $N. Поговори з Броґуном Кам'яним Щитом на Терасі Воїнів, і він допоможе знайти шлях до Альтерацької долини.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1957016230] = {
        ["english"] = { [1] = "The Stormpike Graveyard is cut into the mountains, across the bridge east of Dun Baldar.$B$BThe Alliance currently controls it." },
        ["text"] = "Кладовище Бурешпиля висічене в горах за мостом на схід від Дун-Балдара.$B$BНаразі його контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3036935547] = {
        ["english"] = { [1] = "The Stormpike Aid Station is in Dun Baldar, right outside the Dun Baldar barracks.$B$BThe Alliance currently controls it." },
        ["text"] = "Станція допомоги Бурешпиля розташована в Дун-Балдарі, просто біля казарм.$B$BНаразі її контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1807383911] = {
        ["english"] = { [1] = "The assortment of images, shapes, and markings come together before your eyes. The book seems to know your skill with leatherworking and offers you a choice - but be warned - you may only select one and once you have done so, may not change your mind!:" },
        ["text"] = "Безліч зображень, форм і позначок зливаються перед очима в єдину картину. Книга ніби знає твій рівень шкірництва й пропонує вибір — але будь обережний: можна вибрати лише одне, і після цього змінити рішення вже не вдасться!:",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2601883962] = {
        ["english"] = { [1] = "The spirits have guided you to me. How may I be of service?" },
        ["text"] = "Духи привели тебе до мене. Чим можу прислужитися?",
        ["npcs"] = { [1] = 986, [2] = 3030, [3] = 3031, [4] = 3032, [5] = 3062, [6] = 3066, [7] = 3157, [8] = 3173, [9] = 3344, [10] = 13417 },
        ["roles"] = { ["greeting"] = true },
    },
    [1031984695] = {
        ["english"] = { [1] = "Steel isn't strong, exalted one, flesh is stronger. Steel gains its strength from the one who wields it. But enough of that... How can we help you exalted one?" },
        ["text"] = "Сталь не сильна, превознесений. Плоть сильніша. Сталь черпає силу від того, хто нею володіє. Але досить про це... Чим ми можемо допомогти тобі, превознесений?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2245762943] = {
        ["english"] = { [1] = "Thanks again, $N.  Rocknot and I are really hitting it off!" },
        ["text"] = "Ще раз дякую, $N. Ми з Рокнотом просто чудово ладнаємо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2833450988] = {
        ["english"] = { [1] = "The Shrine of Remulos is a sacred place for us in the Cenarion Circle here in Moonglade... so please conduct yourself in a manner befitting a visitor.$B$BA visitor who doesn't want my scimitar buried in them, that is." },
        ["text"] = "Святилище Ремулоса — священне місце для нас, Кенарієвого Кола, тут, у Місячній галявині... тож поводься як личить гостеві.$B$BГостеві, який не хоче отримати мій ятаган у живіт, якщо точніше.",
        ["npcs"] = { [1] = 11799 },
        ["roles"] = { ["greeting"] = true },
    },
    [1113658956] = {
        ["english"] = { [1] = "The Stars of this time are bent on new paths, beacons of hope and strength for the coming ages." },
        ["text"] = "Зорі цього часу схиляються на нові шляхи — маяки надії й сили для прийдешніх віків.",
        ["npcs"] = { [1] = 15587, [2] = 15592, [3] = 15593, [4] = 15594, [5] = 15595, [6] = 15596, [7] = 15597, [8] = 15598, [9] = 15599, [10] = 15600, [11] = 15601, [12] = 15602, [13] = 15603, [14] = 15604, [15] = 15605, [16] = 15606, [17] = 15607 },
        ["roles"] = { ["greeting"] = true },
    },
    [3574632843] = {
        ["english"] = { [1] = "The stable master" },
        ["text"] = "Господар стайні",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [1985397171] = {
        ["english"] = { [1] = "Sumthin' I can do fer ya, $c?$B" },
        ["text"] = "Чим можу помогти, $c?$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2919621232] = {
        ["english"] = { [1] = "The archmage Allistarj of the Shadowsworn was granted three. Lady Sevine, warlock of the Shadowsworn was also granted three. The remaining three were given to Grol the Destroyer, lord of the Dreadmaul ogres of these blasted lands.$B$BYou see, $N, without a soul, the body cannot be killed. The remnants of my men are now indestructible fighting units. Thankfully, they are bound in how far they can travel by the stones of binding." },
        ["text"] = "Архімаг Аллістарж із Тінеклятих отримав три. Пані Севіна, чорнокнижниця Тінеклятих, також отримала три. Решту три віддали Ґролу Руйнівнику, володарю огрів Жахобою з цих Спустошених земель.$B$BРозумієш, $N, без душі тіло не можна вбити. Рештки моїх людей тепер — незнищенні бойові одиниці. На щастя, камені зв'язування обмежують відстань, на яку вони можуть відходити.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [1232947937] = {
        ["english"] = { [1] = "These babies may look like scrap, but they can rush ahead, knocking enemies aside. The front ram has been overloaded with a electroscopic hyper capacitor, letting it discharge electrical blasts. $B$BEven the turret has been upgraded with anti-air rockets, providing it with a definitive edge over those blasted demolishers." },
        ["text"] = "Ці крихітки можуть виглядати як брухт, але вони здатні рвонути вперед і розкидати ворогів. Передній таран перевантажено електроскопічним гіперконденсатором, що дозволяє випускати електричні розряди.$B$BНавіть турель посилили протиповітряними ракетами, що дає їй явну перевагу над тими клятими нищителями.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4259915937] = {
        ["english"] = { [1] = "Thank you for the offer, $c.  Unfortunately you are not yet experienced enough to weather the hazards of Arathi Basin." },
        ["text"] = "Дякую за пропозицію, $c. На жаль, тобі поки бракує досвіду, щоб витримати небезпеки Низини Араті.",
        ["npcs"] = { [1] = 14991 },
        ["roles"] = { ["greeting"] = true },
    },
    [1870249318] = {
        ["english"] = { [1] = "Thank you for what you have done, $N.$B$BKeep the scepter safe; may it aid you in your toil against the evils that have invaded this place..." },
        ["text"] = "Дякую за все, що ти зробив, $N.$B$BБережи скіпетр; нехай він допоможе тобі в боротьбі зі злом, яке вторглося сюди...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1951885742] = {
        ["english"] = { [1] = "Thank you for choosing the Bank of Silvermoon. What may I do for you today?" },
        ["text"] = "Дякуємо, що обрали Банк Срібномісяця. Чим можу допомогти сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2316836901] = {
        ["english"] = { [1] = "The Earth Mother calls and you answer.  You will find the Hall of Spirits on the Spirit Rise." },
        ["text"] = "Матір-Земля кличе, а ти відповідаєш. Залу Духів знайдеш на Висоті Духів.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [919230670] = {
        ["english"] = { [1] = "That's very kind of you to ask, but it would appear that we've collected all of the silk bandages that we'll need. You could ask around though and see if anyone else needs help with their collections." },
        ["text"] = "Дуже люб'язно з твого боку запитати, але, схоже, ми вже зібрали всі потрібні шовкові бинти. Можеш розпитати довкола — раптом комусь іншому ще потрібна допомога зі зборами.",
        ["npcs"] = { [1] = 15452 },
        ["roles"] = { ["greeting"] = true },
    },
    [662256140] = {
        ["english"] = { [1] = "Such a pity, and here I'll wager that you sharpened your knife special in anticipation of slicing a few skins for me. Alas, we've already gathered all of the rugged leather necessary, $c. Do make yourself useful though, and check with the others here to see if they have any other collection tasks to send you on." },
        ["text"] = "Яка прикрість. Б'юся об заклад, ти спеціально нагострив ніж, сподіваючись нарізати для мене кілька шкур. Та ми вже зібрали всю потрібну грубу шкіру, $c. Утім, не стій без діла: розпитай інших, може, їм ще потрібна допомога зі зборами.",
        ["npcs"] = { [1] = 15525 },
        ["roles"] = { ["greeting"] = true },
    },
    [1820816940] = {
        ["english"] = { [1] = "The Greatmother raised all of us. Any Mag'hari that you see has had their life touched in some special way by the Greatmother. We will miss her greatly when she passes." },
        ["text"] = "Праматір виховала всіх нас. Кожного маґ'гара, якого ти зустрінеш, вона торкнулася чимось особливим. Коли її не стане, нам усім дуже її бракуватиме.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3985888003] = {
        ["english"] = { [1] = "The Stonehearth Graveyard lies east of the Stonehearth Outpost in the Field of Strife.$B$BThe Alliance currently controls it." },
        ["text"] = "Кладовище Кам'яного Вогнища лежить на схід від застави Кам'яного Вогнища на Полі Боротьби.$B$BНаразі його контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [189419405] = {
        ["english"] = { [1] = "The Western Pylon accepts red, green, and blue crystals.$B$BThe Pylon focuses on the energy that can be created using red crystals as the main source of power. There are two possible effects: one that increases your protection from damage, and one that weakens an enemy's defenses.$B$BCrystal Ward requires red and green crystals. This will provide you with an increase to armor.$B$BCrystal Yield requires blue and red crystals. This can lower the armor of a specific target." },
        ["text"] = "Західний пілон приймає червоні, зелені й сині кристали.$B$BВін зосереджується на енергії, яку можна створити, використовуючи червоні кристали як головне джерело сили. Є два можливі ефекти: один посилює захист від шкоди, інший послаблює захист ворога.$B$BДля Кришталевого оберега потрібні червоні й зелені кристали. Він підвищить твою броню.$B$BДля Кришталевої віддачі потрібні сині й червоні кристали. Вона може знизити броню вибраної цілі.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [4045470594] = {
        ["english"] = { [1] = "Subordinates?" },
        ["text"] = "Підлеглі?",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [2798172997] = {
        ["english"] = { [1] = "The Nightmare is finally over!  Darrowshire, forgive me!" },
        ["text"] = "Кошмар нарешті скінчився! Дерроушире, пробач мені!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2600569028] = {
        ["english"] = { [1] = "Tell me what drives this vengeance?" },
        ["text"] = "Розкажи, що живить цю жагу помсти?",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["reply"] = true },
    },
    [413465252] = {
        ["english"] = { [1] = "That child gives me chills. He stands there all day long communing with his grandfather. He'll then turn to tell his mother what the grandfather told him and she - of course - just smiles and nods her head.$B$BLambs! Lemmings! All of them!$B" },
        ["text"] = "Від тієї дитини мороз по шкірі. Він цілий день стоїть там і розмовляє зі своїм дідусем. Потім іде до матері, переказує слова дідуся, а вона — звісно ж — лише усміхається й киває.$B$BЯгнята! Лемінги! Всі до одного!$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [786095393] = {
        ["english"] = { [1] = "The slain spirit of Lunaclaw stares at you intently, as though wanting something from you." },
        ["text"] = "Убитий дух Місяцекігтя пильно дивиться на тебе, ніби чогось хоче.",
        ["npcs"] = { [1] = 12144 },
        ["roles"] = { ["greeting"] = true },
    },
    [2531517554] = {
        ["english"] = { [1] = "The Midsummer Fire Festival has something for everyone to enjoy!" },
        ["text"] = "На Святі Вогню Сонцестояння кожен знайде собі розвагу!",
        ["npcs"] = { [1] = 16781 },
        ["roles"] = { ["greeting"] = true },
    },
    [51730773] = {
        ["english"] = { [1] = "These wastes are scarred by terrible magic.  We must do what we can to heal this great wound." },
        ["text"] = "Ці пустки понівечені страшною магією. Ми мусимо зробити все, щоб зцілити цю велику рану.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1268253730] = {
        ["english"] = { [1] = "This is what I have gathered from the information that you collected from the survey.$B$BThere are two primary forge camps: Forge Camp: Hate, directly west of where we stand and Forge Camp: Fear, directly southwest. Each camp has a Legion transporter, one forge, and several spell warding towers. Additionally, the camps are guarded by wrathguards manning fel cannons. Lastly, each camp has a pit lord overseer.$B$BRight then, this should be no problem at all...$B$B<Altruis laughs.>" },
        ["text"] = "Ось що мені вдалося з’ясувати з відомостей, які ви зібрали під час розвідки.$B$BЄ два головні табори кузні: Табір кузні: Ненависть — просто на захід звідси, і Табір кузні: Страх — просто на південний захід. У кожному таборі є транспортер Легіону, одна кузня та кілька веж із магічними оберегами. Крім того, табори охороняють гнівостражі, що обслуговують гармати Скверни. І нарешті, кожен табір має наглядача — володаря ями.$B$BГаразд, це взагалі не має бути проблемою...$B$B<Альтруїс сміється.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2527203566] = {
        ["english"] = { [1] = "Stormwind's resident engineer trainer is an ingenious gnome by the name of Lilliam Sparkspindle. He can be found in the back of the Dwarven District." },
        ["text"] = "Місцева наставниця інженерії Штормовію — геніальна гномка на ім'я Лілліам Іскроверетено. Її можна знайти в глибині Дворфівського району.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1139667747] = {
        ["english"] = { [1] = "Stay sharp, $n.$b$bWe're not out of the woods yet...." },
        ["text"] = "Не втрачай пильності, $n.$b$bМи ще не вибралися з халепи....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3886577221] = {
        ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the south edge of Thunder Bluff's Hunter Rise. She'll aim you at the target far to south on Stonebull Lake!" },
        ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на південному краю Висоти Мисливців у Громовому Бескиді. Вона націлить тебе на мішень далеко на південь, на озері Кам'яного Бика!",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [468531668] = {
        ["english"] = { [1] = "Students are a bit like sheep.  They're useful and even likeable when you guide and pay close attention to them.$B$BYou leave them alone for a minute and they end up falling down a cliff or drowning in a shallow river." },
        ["text"] = "Учні трохи схожі на овець. Вони корисні й навіть милі, коли їх ведеш і пильно за ними стежиш.$B$BЗалиш їх самих на хвилину — і вони або зваляться зі скелі, або втопляться в мілкій річці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2943898068] = {
        ["english"] = { [1] = "The Argent Dawn might be impotent idealists but their delusional leader knows that they are outmatched. I have been sent here as an emissary of the Scarlet Crusade. An ambassador, if you will... It is doubtful that we could even dent the armies of Kel'Thuzad - united or not - but we might be able to contain them long enough for some sort of miracle to happen.$B$BAs for me? I'll die in battle...$B$B<Marjhan shrugs.>\010" },
        ["text"] = "Сріблястий Світанок, може, й безпорадні ідеалісти, але навіть їхній засліплений ватажок розуміє, що сили нерівні. Мене послали сюди емісаром Багряного Походу. Послом, якщо хочеш... Сумніваюся, що ми зможемо бодай помітно зашкодити арміям Кел'Тузада — разом чи порізно, — але, можливо, стримаємо їх достатньо довго, щоб сталося якесь диво.$B$BА я? Я загину в бою...$B$B<Маржан знизує плечима.>\010",
        ["npcs"] = { [1] = 16114 },
        ["roles"] = { ["greeting"] = true },
    },
    [1303741051] = {
        ["english"] = { [1] = "The elements speak to us, $c.  They share knowledge that we must learn, and they share secrets that must be kept." },
        ["text"] = "Стихії говорять до нас, $c. Вони діляться знанням, якого ми маємо навчитися, і таємницями, які мусимо берегти.",
        ["npcs"] = { [1] = 12736 },
        ["roles"] = { ["greeting"] = true },
    },
    [845459090] = {
        ["english"] = { [1] = "The boy had picked up the Ashbringer and driven it through his father's heart as his back was turned. His last words will haunt me forever: \"What have you done, Renault? Why would you do this?\"" },
        ["text"] = "Хлопець підняв Спопелителя й встромив його в серце батька, коли той відвернувся. Останні слова батька переслідуватимуть мене до кінця життя: «Що ти накоїв, Рено? Навіщо ти це зробив?»",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [979258284] = {
        ["english"] = { [1] = "Tell me more." },
        ["text"] = "Розкажи ще.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [2452182298] = {
        ["english"] = { [1] = "The situation out here is worse than I thought! The zeppelin is little better than a heap of twisted metal and burning fuel!" },
        ["text"] = "Тут усе ще гірше, ніж я думав! Дирижабль майже не відрізняється від купи скрученого металу й палаючого пального!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [348083654] = {
        ["english"] = { [1] = "The Barov house sure does keep me busy. Always some sort of refuse coming out of there." },
        ["text"] = "Дім Барових не дає мені перепочити. Звідти вічно виносять якесь сміття.",
        ["npcs"] = { [1] = 11316 },
        ["roles"] = { ["greeting"] = true },
    },
    [1003064389] = {
        ["english"] = { [1] = "The situation is more grim than many have been led to believe. The Forsaken are here as allies in the fight against our common enemy, the Scourge.$B$BTrust me when I say this, without them the Ghostlands would be lost and the Scourge would already have overrun all of Eversong Woods!$B$BBut more than anything else, we need your help in reclaiming our once proud lands!" },
        ["text"] = "Ситуація значно похмуріша, ніж багатьом розповідають. Відречені тут як союзники в боротьбі проти нашого спільного ворога — Скари.$B$BПовір: без них Примарні землі було б втрачено, а Скара вже заполонила б увесь Ліс Вічноспіву!$B$BТа понад усе нам потрібна твоя допомога, щоб повернути наші колись горді землі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [973680883] = {
        ["english"] = { [1] = "The Fleshwerks is the heart of the Scourge's ghoul, abomination, and flesh giant production. If we can take it out, the Lich King will be greatly weakened." },
        ["text"] = "Плотеробня — серце виробництва гулів, мерзотищ і плотяних велетнів для Скари. Якщо знищимо її, Король-ліч значно ослабне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3407255747] = {
        ["english"] = { [1] = "The silithid are no match for the sons and daughters of Orgrimmar.  Soon all that will be left of them are their crushed limbs and wings under our feet, $N." },
        ["text"] = "Силітиди не рівня синам і дочкам Орґріммара. Скоро від них лишаться лише розчавлені кінцівки й крила під нашими ногами, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [371990145] = {
        ["english"] = { [1] = "The stone radiates a bitter cold, chilling the air around it and the platform on which it sits. Deep within its facets, a blue light pulses, waiting." },
        ["text"] = "Камінь випромінює гіркий холод, охолоджуючи повітря навколо й поміст, на якому лежить. Глибоко в його гранях пульсує синє світло, чекаючи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2787116791] = {
        ["english"] = { [1] = "The Apexis Relic shimmers, betraying a hidden intelligence within." },
        ["text"] = "Реліквія Апекситів мерехтить, видаючи прихований усередині розум.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3153848729] = {
        ["english"] = { [1] = "The pages of the journal seem to be filled with information about trades, buyers  and other miscellaneous business related events." },
        ["text"] = "Сторінки журналу, здається, заповнені відомостями про торги, покупців та інші ділові події.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [79257675] = {
        ["english"] = { [1] = "The Scourge must be stopped at any cost. We cannot permit them to field the army they're constructing here." },
        ["text"] = "Скару треба зупинити за будь-яку ціну. Ми не можемо дозволити їм виставити армію, яку вони тут створюють.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3205030336] = {
        ["english"] = { [1] = "The secrets hidden within the Pylons of Un'Goro Crater are now yours. Visit the Pylons at any time to access their power and gain useful resources." },
        ["text"] = "Таємниці, приховані в пілонах кратера Ун'Ґоро, тепер твої. Відвідуй пілони будь-коли, щоб користуватися їхньою силою й отримувати корисні ресурси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3305306591] = {
        ["english"] = { [1] = "Thank you for the warning, $N. We will prepare our defenses." },
        ["text"] = "Дякую за попередження, $N. Ми підготуємо оборону.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [131807982] = {
        ["english"] = { [1] = "The secret to goblin engineering has nothing to do with keeping things from exploding. It has everything to do with directing the explosions exactly where you want them." },
        ["text"] = "Секрет ґоблінської інженерії не в тому, щоб речі не вибухали. Секрет у тому, щоб вибух відбувався саме там, де ти хочеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1545143646] = {
        ["english"] = { [1] = "The seasons turn for all in due time, but you are still in the springtime of your life.  Please return to us later, $c, when you have experienced more." },
        ["text"] = "Для кожного пора року змінюється у свій час, але ти ще у весні свого життя. Повернися до нас пізніше, $c, коли наберешся більше досвіду.",
        ["npcs"] = { [1] = 15102 },
        ["roles"] = { ["greeting"] = true },
    },
    [3488307193] = {
        ["english"] = { [1] = "The caverns below us are a source of strange and wondrous hides, but you must take care if you venture into their depths, $N. Remember that your own skin is far more valuable." },
        ["text"] = "Печери під нами — джерело дивних і дивовижних шкур, але будь обережний, якщо наважишся спуститися в їхні глибини, $N. Пам'ятай: твоя власна шкура значно цінніша.",
        ["npcs"] = { [1] = 5784 },
        ["roles"] = { ["greeting"] = true },
    },
    [1624049061] = {
        ["english"] = { [1] = "The ravasaur here in Un'Goro seem to be related to the raptors of the barrens--highly intelligent, volatile, and with a sense or code of conduct. The greatest of these that I have encountered is  Lar'korwi. He is one of the most dangerous beasts I've ever seen. In taurahe, Lar'korwi means \"sharp claw,\" but that does not do him justice.$B$BDo not underestimate Lar'korwi if you ever plan on hunting him, but I will help you in any way I can if you do." },
        ["text"] = "Равазаври тут, в Ун'Ґоро, схоже, споріднені з рапторами Степів — дуже розумні, запальні й мають певне відчуття правил. Найвеличніший із тих, кого я зустрічав, — Лар'корві. Це один із найнебезпечніших звірів, яких я бачив. Таураге «Лар'корві» означає «гострий кіготь», але ця назва навіть близько не передає його суті.$B$BНе недооцінюй Лар'корві, якщо колись надумаєш полювати на нього. А я допоможу всім, чим зможу.",
        ["npcs"] = { [1] = 9619 },
        ["roles"] = { ["greeting"] = true },
    },
    [1073317498] = {
        ["english"] = { [1] = "The Scourge's plague still dominates the zone, and we have a long way to go before the plague will be altered enough to affect them.  Collect the necessary resources and help out the war effort!" },
        ["text"] = "Чума Скари досі панує в цій зоні, й нам ще далеко до того, щоб змінити її настільки, аби вона почала діяти проти них. Збирай потрібні ресурси й допомагай воєнним зусиллям!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1101699125] = {
        ["english"] = { [1] = "This is going to be such fun!  Don't you think, my dear?" },
        ["text"] = "Це буде так весело! Хіба ні, любове моя?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3226290078] = {
        ["english"] = { [1] = "The Battle of Mount Hyjal is one of the most well-guarded events of this timeline.  Should an intruder alter its outcome, the impact would extend to all subsequent moments in history.$B$BAs the Aspect's prime mate I'm far more in tune with the flow of time than other bronze dragons.  I recently sensed a minute ripple in time emanating from the events surrounding the Battle of Mount Hyjal.  Someone or something is attempting to change this timeline and they must be stopped." },
        ["text"] = "Битва за гору Гіджал — одна з найпильніше захищених подій цієї часової лінії. Якщо сторонній змінить її результат, наслідки торкнуться всіх наступних миттєвостей історії.$B$BЯк головний супутник Аспекта, я значно краще за інших бронзових драконів відчуваю плин часу. Нещодавно я відчув ледь помітну хвилю в часі, що виходила з подій навколо Битви за гору Гіджал. Хтось або щось намагається змінити цю часову лінію, і це треба зупинити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1159174747] = {
        ["english"] = { [1] = "The Scourge infestation grows in the Eastern Plaguelands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2282W" },
        ["text"] = "Навала Скари посилюється у Східному Чумнозем'ї. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2282W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [357428700] = {
        ["english"] = { [1] = "Thank you!  The battle for Darrowshire doomed me, but you have set me free!" },
        ["text"] = "Дякую! Битва за Дерроушир прирекла мене, але ти звільнив мою душу!",
        ["npcs"] = { [1] = 11064 },
        ["roles"] = { ["greeting"] = true },
    },
    [1840465308] = {
        ["english"] = { [1] = "The Green Flight is in your debt." },
        ["text"] = "Зелена зграя в боргу перед тобою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2788138449] = {
        ["english"] = { [1] = "The Scourge are establishing small staging points in the places under attack, receiving communications and other assistance from the necropolises that fly overhead. From what we can tell, the only way to root them out is by killing the ground forces that surround the points." },
        ["text"] = "Скара створює невеликі опорні пункти в місцях нападів, отримуючи повідомлення й іншу допомогу від некрополів, що літають над головою. Наскільки ми розуміємо, єдиний спосіб викорінити їх — убивати наземні сили навколо цих пунктів.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [4233028475] = {
        ["english"] = { [1] = "This is where the cultists' orders are coming from.  Their leader is bound to show up soon.$B$BLet's not miss this opportunity." },
        ["text"] = "Саме звідси надходять накази культистам. Їхній ватажок неодмінно скоро з’явиться.$B$BНе проґавмо цю нагоду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2258078460] = {
        ["english"] = { [1] = "The Earthen's only anomaly in synthesis is the tendency for matrix destabilization while being utilized in high-stress environments.$B$BAddendum: deep earth sculpting was naturally suited to the new matrix design and thus never met the qualifications of duplicating a high-stress environment.$B$BDestabilization was not discovered until well into the Earthen's primary service cycle for the Creators.  The Creators began work on post-synthesis modification, rather than recall and re-synthesis." },
        ["text"] = "Єдина аномалія синтезу земельників — схильність матриці до дестабілізації під час використання в умовах високого навантаження.$B$BДодаток: формування глибин землі природно відповідало новій конструкції матриці й тому ніколи не створювало умов, достатніх для відтворення високонавантаженого середовища.$B$BДестабілізацію виявили лише далеко в основному циклі служби земельників Творцям. Творці почали роботу над модифікацією після синтезу замість відкликання й повторного синтезу.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1862218772] = {
        ["english"] = { [1] = "The ruins of Zul'Farrak are located in the northwestern corner of the Tanaris Desert." },
        ["text"] = "Руїни Зул'Фаррака розташовані в північно-західному кутку пустелі Танаріс.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2927523959] = {
        ["english"] = { [1] = "The weapon masters in the Valley of Honor within Orgrimmar, Sayoc and Hanashi, can teach you how to shoot a bow." },
        ["text"] = "Майстри зброї Сайок і Ганаші в Долині Честі Орґріммара можуть навчити тебе стріляти з лука.",
        ["npcs"] = { [1] = 11869, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [1669501986] = {
        ["english"] = { [1] = "The orb behind me was once capable of glimpsing into the happenings on Azeroth.$B$BKael'thas's curse changed all that, of course, but during our years of isolation many of the mages found solace in its images.$B$BSome scried to remember; some scried to forget. " },
        ["text"] = "Куля позаду мене колись дозволяла зазирати в події Азероту.$B$BПрокляття Кель'таса, звісно, все змінило, але протягом років ізоляції багато магів знаходили розраду в її образах.$B$BОдні дивилися, щоб пам'ятати; інші — щоб забути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [811326724] = {
        ["english"] = { [1] = "The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince's lips. The Ashbringer could be found!" },
        ["text"] = "Майстер дуже цікавиться лігвом Нефаріана. Якби хтось переміг дракона та його прислужників і переказав історію Принцові, б'юся об заклад, той став би балакучішим. Тоді, можливо, вдасться знайти Спопелителя!",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [116997591] = {
        ["english"] = { [1] = "The Forsaken are right to celebrate their freedom. What else is more important?" },
        ["text"] = "Відречені мають право святкувати свою свободу. Що може бути важливішим?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3383505753] = {
        ["english"] = { [1] = "Thanks for the information, Frankal." },
        ["text"] = "Дякую за відомості, Франкале.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [692722891] = {
        ["english"] = { [1] = "The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood." },
        ["text"] = "Зруйнований Стратгольм лежить у Східному Чумнозем'ї, на північ від Чумного лісу.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [724075058] = {
        ["english"] = { [1] = "The remains are covered in flies and maggots." },
        ["text"] = "Рештки вкриті мухами й опаришами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1058376114] = {
        ["english"] = { [1] = "There's nothing more I can teach you. I've heard of a night elf who might be able to, though. Her name is Ainethil, and she lives in the Craftsmen's Terrace of Darnassus." },
        ["text"] = "Мені більше нічого тебе навчити. Але я чув про нічну ельфійку, яка, можливо, зможе. Її звати Айнетіль, і вона живе на Ремісничій терасі Дарнаса.",
        ["npcs"] = { [1] = 4900 },
        ["roles"] = { ["greeting"] = true },
    },
    [107874079] = {
        ["english"] = { [1] = "The Cathedral of Light in Cathedral Square is home to the priests of Stormwind. There you will find High Priestess Laurena." },
        ["text"] = "Собор Світла на Соборній площі — оселя жерців Штормовію. Там знайдеш Верховну жрицю Лорену.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2248887251] = {
        ["english"] = { [1] = "The creatures in Winterspring are a good place ta start.$B$BHoweva', der may also be other places you can look..." },
        ["text"] = "Істоти Зимоключа — добрий початок.$B$BАле можуть бути й інші місця, де варто пошукати...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1946954940] = {
        ["english"] = { [1] = "The way of the Druid is sibling to the Shaman.  Gennia Runetotem is steeped in such knowledge.  Seek her out in the large tent on the east side of Bloodhoof Village." },
        ["text"] = "Шлях друїда споріднений зі шляхом шамана. Ґеннія Рунічний Тотем глибоко знається на цьому. Шукай її у великому наметі на східному боці селища Криваве Копито.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3815065122] = {
        ["english"] = { [1] = "The Ring of Trials was once of place of great glory and honor. But then, the Steamwheedle Cartel came, with their wagons of gold and quill pens sharper than any orc axe..." },
        ["text"] = "Коло Випробувань колись було місцем великої слави й честі. А потім прийшов картель Парової Шляхти зі своїми возами золота й перами, гострішими за будь-яку орчу сокиру...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1963648256] = {
        ["english"] = { [1] = "The Hunter Trainer's name is Thotar.  Seek him out inside the burrow on the southwest corner of Razor Hill." },
        ["text"] = "Наставника мисливців звати Тотар. Шукай його в норі в південно-західному кутку Колючого Пагорба.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4159401135] = {
        ["english"] = { [1] = "That Lumak... always fishing instead of fighting.  You'll find him out on his dock on the lake in the Valley of Honor.  While you're there say hi to Shankys for me." },
        ["text"] = "Той Лумак... завжди рибалить замість того, щоб битися. Знайдеш його на причалі біля озера в Долині Честі. А як будеш там, передай Шенкісу від мене привіт.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [888813871] = {
        ["english"] = { [1] = "The Dark Lady has said that knowledge will be our greatest weapon in this war." },
        ["text"] = "Темна Пані сказала, що знання буде нашою наймогутнішою зброєю в цій війні.",
        ["npcs"] = { [1] = 4586 },
        ["roles"] = { ["greeting"] = true },
    },
    [959715956] = {
        ["english"] = { [1] = "The draenei champion walks among us. This is a celebration for the savior of Azuremyst and Bloodmyst!" },
        ["text"] = "Чемпіон дренеїв серед нас. Це свято на честь рятівника островів Блакитної та Кривавої Мли!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2459111712] = {
        ["english"] = { [1] = "The Ahn'Qiraj War is on the horizon, $c, and in preparation the Alliance has asked my family to gather up a good deal of light leather for the war effort. Out of $2061w needed, we currently have $2060w. You look the type that might be able to help out." },
        ["text"] = "Війна в Ан'Кіражі вже на обрії, $c, і для підготовки Альянс доручив моїй родині зібрати чимало легкої шкіри. Потрібно $2061w, а зараз у нас лише $2060w. На вигляд ти той, хто може допомогти.",
        ["npcs"] = { [1] = 15446 },
        ["roles"] = { ["greeting"] = true },
    },
    [3134701936] = {
        ["english"] = { [1] = "Thanks a lot, $N.  We couldn't have made it without you.  Oh, and if I had mentioned before something about repaying you for saving us, well... you can forget it!" },
        ["text"] = "Велике спасибі, $N. Без тебе ми б не впоралися. О, а якщо я раніше щось казав про винагороду за наш порятунок, то... забудь!",
        ["npcs"] = { [1] = 7604 },
        ["roles"] = { ["greeting"] = true },
    },
    [2950813702] = {
        ["english"] = { [1] = "The relics are truly a great mystery.  Perhaps by studying them regularly, you will gain a finer appreciation of their capabilities." },
        ["text"] = "Реліквії справді велика таємниця. Можливо, регулярно вивчаючи їх, ти краще зрозумієш їхні можливості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1333987671] = {
        ["english"] = { [1] = "That would be Dwukk.  Find him next to the heated forge at the northwest corner of town." },
        ["text"] = "Це Двукк. Знайдеш його біля розпеченої кузні в північно-західному кутку міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1426958465] = {
        ["english"] = { [1] = "The ashes from the burning wickerman radiate magical power.  You have already applied the ashes to your face." },
        ["text"] = "Попіл від палаючого Опудала випромінює магічну силу. Ти вже наніс цей попіл собі на обличчя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2492432873] = {
        ["english"] = { [1] = "Tell me about dungeons I could explore." },
        ["text"] = "Розкажи мені про підземелля, які я можу дослідити.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [995790239] = {
        ["english"] = { [1] = "The profession of Enchanting displays the cycle of destruction and creation that is at the heart of nature.  Teg at the Dawnstrider Enchanters on the middle rise will show you how." },
        ["text"] = "Професія зачарування відображає цикл руйнування й творення, що лежить у серці природи. Теґ у «Зачаруваннях Світанкового Мандрівника» на середньому виступі покаже тобі як.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3579184189] = {
        ["english"] = { [1] = "The Wayfarer's Rest tavern is located between the Walk of Elders and the Bazaar. You can reach it from either location." },
        ["text"] = "Таверна «Притулок Подорожнього» розташована між Алеєю Старійшин і Базаром. Дістатися можна з будь-якого боку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4141072055] = {
        ["english"] = { [1] = "Stormwind Stockade" },
        ["text"] = "Штормовійська В'язниця",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2227003251] = {
        ["english"] = { [1] = "The fabric of which our world is woven is most delicate. It merely takes some knowledge and the application of said knowledge to tear the fabric. It is thusly that rifts are born. " },
        ["text"] = "Тканина, з якої зіткана наша реальність, надзвичайно тендітна. Достатньо знань і правильного їх застосування, щоб її розірвати. Так і народжуються розломи. ",
        ["npcs"] = { [1] = 14387 },
        ["roles"] = { ["greeting"] = true },
    },
    [4105556566] = {
        ["english"] = { [1] = "Taking care of animals is something that Ulbrek Firehand takes quite seriously.  He usually hangs out with the hunters at the Hall of Arms if ye want him to look after a pet or two." },
        ["text"] = "Ульбрек Вогнерук дуже серйозно ставиться до догляду за тваринами. Зазвичай він крутиться біля мисливців у Залі Зброї, якщо хочеш доручити йому вихованця-другого.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3640121234] = {
        ["english"] = { [1] = "The Headless Horseman had been driven away, for now.  We may breath easy for a time, but must remain ever vigilant." },
        ["text"] = "Вершника без голови прогнали — поки що. Можемо трохи перевести подих, але мусимо завжди бути насторожі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3039422796] = {
        ["english"] = { [1] = "Stray arcane forces can do strange things to the land, the elements and even the spirits of the dead." },
        ["text"] = "Некеровані сили таємної магії можуть чинити дивні речі із землею, стихіями й навіть духами мертвих.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3839222611] = {
        ["english"] = { [1] = "They are lost, $r. Librams written by the elven masters. Scattered across the world when the Scourge was unleashed upon Quel'Thalas.$B$BNow we search for these librams. Search to find the secrets they hold - to restore power once had.$B$BI search for the ten written by Master Kariel Winthalus. Should you find a libram, allow me to absorb its magical properties and for you I shall craft an amalgamation of power... of course, all things come at some cost. You will find my cost to be high; but pay you shall." },
        ["text"] = "Вони загублені, $r. Лібрами, написані ельфійськими майстрами. Розсіяні по світу, коли Скару випустили на Кель'Талас.$B$BТепер ми шукаємо ці лібрами. Шукаємо приховані в них таємниці — щоб повернути колишню силу.$B$BЯ шукаю десять, написаних майстром Каріелем Вінталусом. Якщо знайдеш лібрам, дозволь мені поглинути його магічні властивості, і я створю для тебе сплав сили... звісно, усе має свою ціну. Моя ціна висока; але ти заплатиш.",
        ["npcs"] = { [1] = 9836 },
        ["roles"] = { ["greeting"] = true },
    },
    [4115455118] = {
        ["english"] = { [1] = "Test not my patience, mortal." },
        ["text"] = "Не випробовуй мого терпіння, смертний.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2407376016] = {
        ["english"] = { [1] = "Tales of your exploits spread.  Your name is not unknown to us, $N." },
        ["text"] = "Слава про твої подвиги шириться. Твоє ім'я нам відоме, $N.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [2173824649] = {
        ["english"] = { [1] = "Throm'ka, $c. All of the war materiel is in final preparation and being sent to Silithus. The last of it should arrive in less than a day. With the equipment readied, and our forces arrayed, all we will be waiting for is someone to ring the gong on the Scarab Dais, which should open the gates of Ahn'Qiraj and start the war.$B$BLok'tar Ogar!" },
        ["text"] = "Тром’ка, $c. Усі військові припаси проходять останню підготовку й вирушають до Силітуса. Останні з них мають прибути менш ніж за день. Коли спорядження буде готове, а наші сили розгорнуті, залишиться тільки дочекатися, доки хтось ударить у гонг на Помості Скарабея, що має відкрити брами Ан’Кіражу й розпочати війну.$B$BЛок’тар Оґар!",
        ["npcs"] = { [1] = 15522 },
        ["roles"] = { ["greeting"] = true },
    },
    [1043433179] = {
        ["english"] = { [1] = "The battle is won. For the time being, the Scourge threat has been pushed back. Our resources can be channeled into aiding you, in thanks and preparation for the future." },
        ["text"] = "Битву виграно. Принаймні на якийсь час загрозу Скари відкинуто. На знак вдячності й у підготовці до майбутнього ми можемо спрямувати ресурси на допомогу тобі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [192710567] = {
        ["english"] = { [1] = "The pile of skulls reeks of foulness.  You fear the arakkoa have made an addition to the pile fairly recently." },
        ["text"] = "Купа черепів смердить скверною. Ти підозрюєш, що араккоа зовсім недавно додали до неї новий трофей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [782714387] = {
        ["english"] = { [1] = "The people in Nighthaven sure know how to party!" },
        ["text"] = "Люди в Нічній Гавані вміють святкувати!",
        ["npcs"] = { [1] = 15906 },
        ["roles"] = { ["greeting"] = true },
    },
    [786613124] = {
        ["english"] = { [1] = "The Gordunni are a large ogre tribe that has control over considerable portions of forests in Feralas. Their dark magic seeps into the elements around them, damaging both the environment and the creatures that inhabit it.$B$BIf you do decide to travel to Feralas, please be mindful of these ogres -- they are quite nasty and many are able to wield powerful dark magic. " },
        ["text"] = "Ґордунні — велике плем'я огрів, що контролює значні частини лісів Фераласа. Їхня темна магія просочується в навколишні стихії, шкодячи і природі, і живим істотам.$B$BЯкщо вирішиш подорожувати Фераласом, остерігайся цих огрів — вони дуже люті, а багато хто володіє могутньою темною магією. ",
        ["npcs"] = { [1] = 7763 },
        ["roles"] = { ["greeting"] = true },
    },
    [1108188710] = {
        ["english"] = { [1] = "The path of those who undertake a profession is long and rewarding.  Which path do you choose to walk?" },
        ["text"] = "Шлях того, хто обирає професію, довгий і щедрий на винагороди. Яким шляхом підеш ти?",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2527422559] = {
        ["english"] = { [1] = "Tailoring" },
        ["text"] = "Кравецтво",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [1642630883] = {
        ["english"] = { [1] = "That sounds dangerous." },
        ["text"] = "Звучить небезпечно.",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [745025109] = {
        ["english"] = { [1] = "The tinkerer's craft for you is it?  No doubt ye'll want to go see Springspindle Fizzlegear in Tinker Town.  \010\010Just head east from the gates of Ironforge, or follow the sound of the explosions." },
        ["text"] = "То тебе цікавить ремесло механіка? Тоді без сумніву варто навідатися до Пружиноверетена Шестеренка в Місті Механіків.  \010\010Просто йди на схід від брами Залізогарта або на звук вибухів.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2749178272] = {
        ["english"] = { [1] = "Things can get a little stuffy here in Nethergarde.  Sometimes a dwarf just needs a brew to take her mind off her duty for a bit." },
        ["text"] = "Тут, у Стражі Підсвіття, часом буває задушливо. Іноді дворфці просто треба кухоль пива, щоб ненадовго забути про обов'язок.",
        ["npcs"] = { [1] = 9540 },
        ["roles"] = { ["greeting"] = true },
    },
    [3346415903] = {
        ["english"] = { [1] = "The Shattered Sun Offensive has made great progress in the outer areas of the Isle of Quel'Danas. Kil'jaeden's forces are being pushed back, and in the chaos I was able to lead a small scouting force here inside the Sunwell Plateau. My troops proceeded through Parhelion Plaza, spotted a group of Sunblade blood elves, and we then engaged the enemy. That fight quickly turned into a disaster." },
        ["text"] = "Наступ Розколотого Сонця досяг значного успіху на зовнішніх ділянках острова Кель'Данас. Сили Кіл'джедена відступають, і в цій метушні я зміг провести невеликий розвідувальний загін усередину Плато Сонячного Колодязя. Мої війська пройшли площею Паргеліона, помітили групу ельфів крові Сонячного Клинка, і ми вступили в бій. Він дуже швидко обернувся катастрофою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1257802813] = {
        ["english"] = { [1] = "The outhouse appears to be occupied at the moment." },
        ["text"] = "Схоже, нужник зараз зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4245401707] = {
        ["english"] = { [1] = "The crystal is covered in intricate glyphs and runes. You can't make sense of any of it." },
        ["text"] = "Кристал вкритий складними гліфами й рунами. Ти не розумієш жодного з них.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [854816543] = {
        ["english"] = { [1] = "Thank you, little $r!" },
        ["text"] = "Дякую тобі, маленький $r!",
        ["npcs"] = { [1] = 8767 },
        ["roles"] = { ["greeting"] = true },
    },
    [917423205] = {
        ["english"] = { [1] = "The orphans we have taken in come from war torn Sholazar Basin. You can choose to care for either an orphaned Oracle hatchling or a Frenzyheart pup. Either will be happy to make a new friend, but you will only be able to care for one of them." },
        ["text"] = "Сироти, яких ми прихистили, походять із спустошеної війною Шолазарської долини. Можеш доглядати або осиротіле дитинча Оракула, або маля Шаленого Серця. Кожне зрадіє новому другові, але доглядати можна лише одне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2887022987] = {
        ["english"] = { [1] = "The orb's markings match the brand on your hand." },
        ["text"] = "Позначки на кулі збігаються з тавром на твоїй руці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3150205532] = {
        ["english"] = { [1] = "The final sanctum of crazed zealots. 'Tis where they create their scarlet uniforms, magically imbued by the enchanted scarlet thread!$B$BTo Stratholme, adventurer!" },
        ["text"] = "Останнє святилище навіжених фанатиків. Саме там вони шиють свої багряні однострої, магічно насичені зачарованою багряною ниткою!$B$BДо Стратгольма, шукачу пригод!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1734211899] = {
        ["english"] = { [1] = "The details of the posting call for the execution of an enormous wolf.  She apparently keeps her den to the south of the Jagged Ridge, near the Horde stronghold." },
        ["text"] = "У подробицях оголошення сказано, що треба вбити величезну вовчицю. Її лігво, схоже, розташоване на південь від Зубчастого кряжа, неподалік оплоту Орди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1367736669] = {
        ["english"] = { [1] = "The only reason that you still live is because of my curiosity." },
        ["text"] = "Ти досі живий лише завдяки моїй цікавості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3088349840] = {
        ["english"] = { [1] = "The feralfen that dwell in Zangarmarsh have wicker baskets with clever locks on them.  Surely they would challenge even your skill." },
        ["text"] = "Фералфени, що мешкають у Занґарських болотах, мають плетені кошики з хитрими замками. Вони точно стануть випробуванням навіть для твоєї майстерності.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [851219380] = {
        ["english"] = { [1] = "The ogres, they bury me here up to my neck and then forget to come back.$B$BYah, mon, funny.  Laugh it up.  Disembodied ghost head here.$B$BOf course, if you want to help me out, I might be able to make it worth your while.$B$BBut no, keep laughing." },
        ["text"] = "Огри закопують мене тут по шию, а потім забувають повернутися.$B$BАга, мон, смішно. Смійся-смійся. Тут, бачте, безтілесна примарна голова.$B$BЗвісно, якщо хочеш допомогти мені вибратися, я можу віддячити.$B$BАле ні, продовжуй сміятися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4017554041] = {
        ["english"] = { [1] = "Tell me about the cannon." },
        ["text"] = "Розкажи мені про гармату.",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [543353972] = {
        ["english"] = { [1] = "The Cult of the Damned has grown large in scope. Nearly every city, from the capitals to the small hamlets and hovels of both the Horde and Alliance, have Cult members hidden amongst their citizenry.$B$BDo not look so surprised. The Cult only wears a uniform for ritual and ceremony. It is quite possible that you have interacted with one during your adventures and not even known." },
        ["text"] = "Культ Проклятих розрісся до величезних масштабів. Майже в кожному місті — від столиць до маленьких сіл і халуп Орди та Альянсу — серед жителів ховаються члени Культу.$B$BНе дивуйся так. Культ носить уніформу лише під час ритуалів і церемоній. Цілком можливо, що в пригодах ти вже спілкувався з кимось із них і навіть не здогадувався про це.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [2118554028] = {
        ["english"] = { [1] = "That's the spirit, $g laddy : lassie;!  Yer making all of us proud with all o' the work ye be doing!$B$BAnd ya know, if ya want a quick trip ta our other base in the Skethyl Mountains, go down an talk ta Skyguard Handler Irena.  She'll set ya up nicely." },
        ["text"] = "Оце дух, $g хлопче : дівчино;! Ти робиш усіх нас гордими своєю працею!$B$BІ знаєш, якщо хочеш швидко дістатися нашої іншої бази в горах Скеттіс, спустися й поговори з наглядачкою Небесної Варти Іреною. Вона все владнає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2931131570] = {
        ["english"] = { [1] = "The officers' lounge" },
        ["text"] = "Офіцерська зала",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["reply"] = true },
    },
    [2982479576] = {
        ["english"] = { [1] = "Though we've arrived at the promised land, $N, much work remains to be done.  Our people won't reach Kael'thas if we lunge desperately across Outland.$B$BSafe routes must be found, resources must be secured and our enemies must be avoided or destroyed." },
        ["text"] = "Хоч ми й прибули до обіцяної землі, $N, попереду ще багато роботи. Наш народ не дістанеться до Кель’таса, якщо відчайдушно кинеться через Позамежжя.$B$BТреба знайти безпечні шляхи, забезпечити ресурси, а ворогів — обійти або знищити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4018715151] = {
        ["english"] = { [1] = "The spirit looks intently into your eyes and grasps your hand.  You feel a warmth shoot through your body, almost knocking you to your knees.$B$BAs the warmth passes, you feel the slight presence of an ursine spirit within your being... bolstering your resolve." },
        ["text"] = "Дух пильно дивиться тобі в очі й стискає твою руку. Ти відчуваєш, як тепло стрілою проходить крізь тіло, ледь не збиваючи з ніг.$B$BКоли воно минає, ти відчуваєш слабку присутність ведмежого духу всередині... він зміцнює твою рішучість.",
        ["npcs"] = { [1] = 12144 },
        ["roles"] = { ["greeting"] = true },
    },
    [1509262286] = {
        ["english"] = { [1] = "The night Kael'thas leveled the village, I could do nothing to help. His magic had already sealed me in the tower, exacerbating my torment by forcing me to witness the deaths of my fellows.$B$BAnd still their voices are calling from far away, waking me up in the middle of the night. " },
        ["text"] = "У ніч, коли Кель'тас зрівняв селище із землею, я не міг нічим допомогти. Його магія вже замкнула мене у вежі, поглиблюючи мої муки тим, що змушувала дивитися на смерть товаришів.$B$BІ досі їхні голоси кличуть мене здалеку, будять серед ночі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2880812816] = {
        ["english"] = { [1] = "The better to see you with, my child." },
        ["text"] = "Щоб краще тебе бачити, дитинко.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3228707267] = {
        ["english"] = { [1] = "The ground... is frozen.  We're sitting ducks here; these meatwagons aren't going anywhere." },
        ["text"] = "Земля... замерзла. Ми тут як на долоні; ці вози з трупами нікуди не поїдуть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4016730535] = {
        ["english"] = { [1] = "Thank you, $R. Now prepare yourselves. Archimonde is on the march, and we must hold off the inevitable for as long as we can." },
        ["text"] = "Дякую, $R. А тепер приготуйтеся. Архімонд уже в дорозі, і ми маємо стримувати неминуче якомога довше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1296051806] = {
        ["english"] = { [1] = "The Earthen are a synthesized race engineered by the Creators, functioning as one of the seed races in the initial population of the world designated as Azeroth.  The Earthen were created to aid the Creators' efforts in shaping the deep regions of this world.$B$BThey are a modification of the standard subterranean being matrix used on other worlds that the Creators have seeded.  The construction of this prototype race created various anomalies that were observed after initial synthesis." },
        ["text"] = "Земельники — синтезована раса, створена Творцями як одна з початкових рас для заселення світу, позначеного як Азерот. Земельників створили, щоб допомагати Творцям формувати глибинні області цього світу.$B$BВони є модифікацією стандартної матриці підземних істот, яку Творці застосовували на інших засіяних світах. Створення цієї прототипної раси спричинило різні аномалії, зафіксовані після початкового синтезу.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [3770557665] = {
        ["english"] = { [1] = "The nearest bank ye'll find is The Vault in Ironforge, $glad : lass;. " },
        ["text"] = "Найближчий банк — Сховище в Залізогарті, $gхлопче : дівчино;. ",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1405155743] = {
        ["english"] = { [1] = "The moment we've been dreading is now at hand, $C. Archimonde has made his way to Nordrassil, and is beginning to devour the World Tree's energies. Malfurion needs more time for his plan to work, so we must do the unthinkable. You must attack Archimonde directly, while my own troops hold off the streams of Burning Legion forces approaching the top of the mount." },
        ["text"] = "Мить, якої ми боялися, настала, $C. Архімонд дістався Нордрассілу й почав поглинати енергію Світового Дерева. Малфуріону потрібно більше часу, щоб його план спрацював, тож ми мусимо зробити немислиме. Ти маєш атакувати Архімонда напряму, поки мої війська стримуватимуть потоки сил Палаючого Легіону, що піднімаються на вершину гори.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3561329813] = {
        ["english"] = { [1] = "The Lion's Pride Inn in Goldshire is as good as any inn you will find around these parts.  Drop in and let Innkeeper Farley make you feel at home." },
        ["text"] = "Корчма «Левова Гордість» у Злотохресті не гірша за будь-яку іншу в цих краях. Завітай, і корчмар Фарлі подбає, щоб ти почувався як удома.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1627977175] = {
        ["english"] = { [1] = "The men and women of Honor Hold have shed such blood and have lost their youth in this monstrous land... and yet they still hold their spirits high!$B$BNow, you and your cohorts from Azeroth can help us turn the tide.  You give us hope that we may one day return to our homelands." },
        ["text"] = "Чоловіки й жінки Оплоту Честі пролили стільки крові й віддали молодість у цій жахливій землі... і все ж не втратили духу!$B$BТепер ти й твої товариші з Азероту можете допомогти нам переломити хід боротьби. Ви даруєте нам надію, що одного дня ми повернемося додому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2121307957] = {
        ["english"] = { [1] = "The Infinites are attempting something unusually subtle for them. They are trying to hide the evidence that will lead to Arthas deciding to cull Stratholme. Their agents have used illusionary magic on the plagued grain shipments in the nearby countryside to make them appear normal. I need you to find the hidden grain, and use this Arcane Disruptor on the shipments. Arthas' men are looking for plagued grain, and should find it quickly with the illusion gone." },
        ["text"] = "Нескінченні роблять щось незвично тонке для себе. Вони намагаються приховати докази, які змусять Артаса вирішити очистити Стратгольм. Їхні агенти наклали ілюзії на заражені поставки зерна в сусідній місцевості, щоб ті здавалися нормальними. Знайди приховане зерно й застосуй до поставок цей Арканічний Руйнівник. Люди Артаса шукають заражене зерно й швидко знайдуть його, коли ілюзія зникне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1145546815] = {
        ["english"] = { [1] = "The Headless Horseman has set fire to the village!  We must protect the children!" },
        ["text"] = "Вершник без голови підпалив селище! Ми мусимо захистити дітей!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2967018626] = {
        ["english"] = { [1] = "The Isle of Conquest is laden with valuable resources we cannot allow to fall into Alliance hands. Will you join the fight?" },
        ["text"] = "Острів Завоювання багатий на цінні ресурси, які ми не можемо віддати Альянсу. Приєднаєшся до бою?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [498876446] = {
        ["english"] = { [1] = "The magnataur are not as stupid as they appear. Keeping Gormok until his time is a difficult task, but he is bound tightly enough that there is no danger." },
        ["text"] = "Магнатаури не такі дурні, як здаються. Утримувати Ґормока до потрібного часу непросто, але він зв'язаний достатньо міцно й небезпеки немає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2911915097] = {
        ["english"] = { [1] = "The buzz around here is that we've collected everything that we need. Now it all comes down to the Horde gathering up their stuff. Once they have we can all ship our goods over to Silithus and the war can begin." },
        ["text"] = "Тут усі тільки й говорять, що ми вже зібрали все потрібне. Тепер усе залежить від того, коли Орда збере своє. Після цього разом відправимо припаси до Силітуса, і війна почнеться.",
        ["npcs"] = { [1] = 15455 },
        ["roles"] = { ["greeting"] = true },
    },
    [3795015972] = {
        ["english"] = { [1] = "The magi congregate in the Wizard's Sanctum in the Mage Quarter. Quite a tower they have there. Makes our barracks look like peasant hovels." },
        ["text"] = "Маги збираються в Святилищі Чарівників у Кварталі Магів. Оце в них вежа. Наші казарми на її тлі — селянські халупи.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [759534624] = {
        ["english"] = { [1] = "The mage tower to the north." },
        ["text"] = "Вежа магів на півночі.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["reply"] = true },
    },
    [1685550884] = {
        ["english"] = { [1] = "That Jormund Stonebrow has a knack for the needle, he does.  Should you be needing some training, then you'll find him at Stonebrow's Clothier on the northern side of The Great Forge." },
        ["text"] = "Йормунд Кам'янобров уміє вправно орудувати голкою. Якщо тобі потрібне навчання, знайдеш його в кравецькій Кам'яноброва на північному боці Великої Кузні.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1272329472] = {
        ["english"] = { [1] = "Thank the light you are here! I'd accept help from a two-headed ogre at this point.\010\010The city has been overrun by troggs! The attempts to wipe them out resulted in mass contamination. But there is still hope.\010\010Our scientists who evacuated to Ironforge are working on a cure for the fallout sickness. Meanwhile, if you can help me stop the trogg invasion, perhaps the city can be retaken. " },
        ["text"] = "Хвала Світлу, ти тут! Зараз я прийняв би допомогу навіть від двоголового огра.\010\010Місто заполонили троґґи! Спроби винищити їх призвели до масового зараження. Але надія ще є.\010\010Наші вчені, евакуйовані до Залізогарта, працюють над ліками від променевої хвороби. А поки що, якщо ти допоможеш мені зупинити навалу троґґів, можливо, місто ще вдасться відвоювати. ",
        ["npcs"] = { [1] = 7998 },
        ["roles"] = { ["greeting"] = true },
    },
    [3379607173] = {
        ["english"] = { [1] = "Tell me more about the history of Remulos and Zaetar." },
        ["text"] = "Розкажи мені більше про історію Ремулоса й Заетара.",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["reply"] = true },
    },
    [3979513811] = {
        ["english"] = { [1] = "Teach me how to create and apply a Heavy Mageweave Bandage, Doctor." },
        ["text"] = "Навчіть мене виготовляти й накладати щільний бинт із маготканини, лікарю.",
        ["npcs"] = { [1] = 12939 },
        ["roles"] = { ["reply"] = true },
    },
    [2442289276] = {
        ["english"] = { [1] = "The machine comes alive at your touch." },
        ["text"] = "Від твого дотику машина оживає.",
        ["npcs"] = { [1] = 7166 },
        ["roles"] = { ["greeting"] = true },
    },
    [1490557882] = {
        ["english"] = { [1] = "The spirits speak all around us. Are you listening, $r?" },
        ["text"] = "Духи говорять довкола нас. Ти слухаєш, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1192334969] = {
        ["english"] = { [1] = "There's trouble in the woods.  We must uncover its source before it is too late!" },
        ["text"] = "У лісі біда. Ми мусимо знайти її джерело, поки не пізно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3052515204] = {
        ["english"] = { [1] = "The Bank of Stormwind is located in the Trade District just northwest of the city gates. Here, let me show you on your map." },
        ["text"] = "Банк Штормовію розташований у Торговому районі, трохи на північний захід від міської брами. Ось, покажу на мапі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1065012391] = {
        ["english"] = { [1] = "There are many establishments where you can get a drink in Stormwind, but only one will let you spend the night. Head over to the Gilded Rose in the Trade District. I've heard the cost of a room is reasonable and the sheets are clean. " },
        ["text"] = "У Штормовії багато закладів, де можна випити, але лише в одному дозволять переночувати. Іди до «Позолоченої троянди» в Торговому районі. Кажуть, кімнати там недорогі, а простирадла чисті. ",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1810368146] = {
        ["english"] = { [1] = "The Valley of Trials will temper even the weakest into a warrior worthy to join the Horde. Those who cannot rise to its tests will be left to bake in the scorching desert sun." },
        ["text"] = "Долина Випробувань загартує навіть найслабшого й зробить із нього воїна, гідного приєднатися до Орди. Ті, хто не витримає її випробувань, лишаться пектися під палючим сонцем пустелі.",
        ["npcs"] = { [1] = 3143 },
        ["roles"] = { ["greeting"] = true },
    },
    [3353253066] = {
        ["english"] = { [1] = "The fact that you are here is a first step... a correct choice if you will, in aiding Ysera's Dragonflight.$B$BYou may be here for purely the lure of personal gain, or you may be here because you are morally compelled.  Neither reason is important on its own, but both are in fact critical to this end: The agony that Eranikus endures is what rousted me from my Dream, and it is now my charge to see his torment ended.  I now ask you to aid me in this quest.\010" },
        ["text"] = "Те, що ти тут, — уже перший крок... правильний вибір, якщо хочеш допомогти драконячій зграї Ізери.$B$BМожливо, тебе привела лише жага особистої вигоди, а можливо — моральний обов'язок. Жодна причина сама по собі не важлива, але обидві критично ведуть до одного: муки Еранікуса пробудили мене зі Сну, і тепер я зобов'язаний покласти край його стражданням. Я прошу тебе допомогти мені в цьому.\010",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["greeting"] = true },
    },
    [439876531] = {
        ["english"] = { [1] = "That the Sironas entity had plans for Saruan... $B$B<The writing stops abruptly and a long line scrolls off the page. This draenei died while making the entry.>$B" },
        ["text"] = "Що сутність Сіронас мала плани щодо Саруан... $B$B<Запис раптово обривається, а довга риска тягнеться за край сторінки. Цей дреней помер, роблячи запис.>$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [523358027] = {
        ["english"] = { [1] = "The fight against Kael'thas and Illidan continues on all fronts.  Defeat is not an option." },
        ["text"] = "Боротьба проти Кель'таса й Іллідана триває на всіх фронтах. Поразка неприпустима.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2475317308] = {
        ["english"] = { [1] = "Tell me about the Elementals Deck." },
        ["text"] = "Розкажи мені про Колоду Елементалів.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["reply"] = true },
    },
    [3083516203] = {
        ["english"] = { [1] = "The Thorium Brotherhood possesses the knowledge required to make the sacred arms and armaments of the Fire Lord, but we lack the manpower to obtain the materials required for the crafting.$B$BI, Lokhtos Darkbargainer, have been empowered by the Brotherhood to exchange the exalted recipes for materials gathered from the Molten Core.$B$BPresent your offer, $r." },
        ["text"] = "Торієве братство володіє знанням, потрібним для створення священної зброї й спорядження Володаря вогню, але нам бракує людей, щоб добути потрібні матеріали.$B$BЯ, Локтос Темний Торговець, уповноважений Братством обмінювати рецепти для превознесених на матеріали з Вогняних Надр.$B$BВисувай пропозицію, $r.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["greeting"] = true },
    },
    [4272782610] = {
        ["english"] = { [1] = "The kegs are filled with strong brew!  Drink, friend, and celebrate!" },
        ["text"] = "Барила повні міцного напою! Пий, друже, й святкуй!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2606754039] = {
        ["english"] = { [1] = "The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a bag of some sort. Your understanding of tailoring is insufficient to decipher the pattern." },
        ["text"] = "Щоденник Джендіс Баров переповнений безумними записами про невмерлих. Наприкінці книги, схоже, є кравецька викрійка для створення якоїсь сумки. Твого знання кравецтва недостатньо, щоб розібрати викрійку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1898391870] = {
        ["english"] = { [1] = "The Isle of Conquest is laden with valuable resources we cannot allow to fall into Horde hands. Will you join the fight?" },
        ["text"] = "Острів Завоювання багатий на цінні ресурси, які ми не можемо віддати Орді. Приєднаєшся до бою?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [142592738] = {
        ["english"] = { [1] = "The mailbox" },
        ["text"] = "Поштова скринька",
        ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [3623487321] = {
        ["english"] = { [1] = "The first suit of Dreadnaught armor was made exclusively for the Scarlet Highlord Mograine.  Whilst donning the full suit, the Highlord looked himself to be a demon from the depths of the Nether.$B$BAye, 'twas quite a sight to behold as Mograine would wade into a hundred Scourge, Ashbringer held high, and come out on the other side in a cloud of dust and flames - enemies left in ashes beneath his feet." },
        ["text"] = "Перший комплект обладунків Дредноута було виготовлено виключно для Багряного верховного лорда Моґрейна. У повному комплекті він виглядав, наче демон із глибин Підсвітньої Крутоверті.$B$BТак, це було видовище: Моґрейн ішов просто в сотню воїнів Скари, високо тримаючи Спопелителя, а виходив з іншого боку крізь хмару пилу й полум'я — вороги лишалися попелом під його ногами.",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["greeting"] = true },
    },
    [3375656365] = {
        ["english"] = { [1] = "The skin stretched taut between the bones is a call to arms against the main defender of the Alliance's Sylvanaar and the Living Grove to the west." },
        ["text"] = "Натягнута між кістками шкіра — заклик до бою проти головного захисника альянсового Сильванаара й Живого Гаю на заході.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2553616532] = {
        ["english"] = { [1] = "The forces of the Scourge bear down upon us.  Take heart, and fight on!" },
        ["text"] = "Сили Скари тиснуть на нас. Не падай духом і бийся далі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2343015615] = {
        ["english"] = { [1] = "The darkness does not embrace you, $c.  Cease your prattle and remove yourself from my sight!  Be gone!" },
        ["text"] = "Темрява не приймає тебе, $c. Припини базікати й забирайся з моїх очей! Геть!",
        ["npcs"] = { [1] = 459, [2] = 461, [3] = 906, [4] = 3326, [5] = 5173, [6] = 5495, [7] = 5496, [8] = 5612 },
        ["roles"] = { ["greeting"] = true },
    },
    [1620251900] = {
        ["english"] = { [1] = "The Infinite Dragonflight is attempting to alter the destiny of Prince Arthas Menethil. You know him now as the Lich King, but here and now he was still a Prince of Lordaeron trying to do what was best for his kingdom. Arthas makes a very fateful choice today, leading to something we Keepers of Time call an inflection point in the timeline." },
        ["text"] = "Нескінченна драконяча зграя намагається змінити долю принца Артаса Менетіла. Тепер ти знаєш його як Короля-ліча, але тут і зараз він іще принц Лордерону, який намагається зробити найкраще для свого королівства. Сьогодні Артас ухвалить доленосне рішення, що приведе до того, що ми, Хранителі Часу, називаємо точкою перегину часової лінії.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2011952375] = {
        ["english"] = { [1] = "The infernal is one of the most powerful demons a warlock could hope to have at $Ghis:her; side in battle. The creature is stong, well-armored, and delivers devastating blows upon any foe. If you were to choose to put the spirit of an infernal into your weapon, you would gain some of those benefits--greater health and regeneration and the like.$B$BIf you wish to know more about felhounds, then you should speak to Wytula across from me." },
        ["text"] = "Інфернал — один із наймогутніших демонів, яких чорнокнижник може мати на $Gсвоєму:своєму; боці в бою. Істота сильна, добре захищена й завдає нищівних ударів будь-якому ворогові. Якщо вкладеш дух інфернала у свою зброю, отримаєш частину цих переваг — більше здоров'я, краще відновлення тощо.$B$BЯкщо хочеш більше дізнатися про скверногончаків, поговори з Вітулою навпроти мене.",
        ["npcs"] = { [1] = 6252 },
        ["roles"] = { ["greeting"] = true },
    },
    [145581951] = {
        ["english"] = { [1] = "Stand up straight, grunt! You're under the command of the Kor'kron Guard now." },
        ["text"] = "Випростайся, рубако! Тепер ти під командуванням варти Кор'крона.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [491780703] = {
        ["english"] = { [1] = "The infected nightstalker runts seem to be coming from the north. If I were you, that's where I would start my hunt." },
        ["text"] = "Схоже, заражені дитинчата нічних ловців приходять із півночі. На твоєму місці я б почав полювання саме там.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2538468429] = {
        ["english"] = { [1] = "The indigenous rams of Alterac are vital to the functionality of our cavalry!" },
        ["text"] = "Місцеві альтерацькі барани життєво важливі для роботи нашої кінноти!",
        ["npcs"] = { [1] = 13617 },
        ["roles"] = { ["greeting"] = true },
    },
    [3473592196] = {
        ["english"] = { [1] = "The Iceblood Tower protects the Iceblood Garrison from the southeast.$B$BIt is controlled by the Horde." },
        ["text"] = "Вежа Крижаної Крові захищає гарнізон Крижаної Крові з південного сходу.$B$BЇї контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1172642105] = {
        ["english"] = { [1] = "The Hyldsmeet is sacred.  Whoever earns victory is assured a lifetime next to Thorim." },
        ["text"] = "Гільдсмут священний. Той, хто здобуде перемогу, забезпечить собі місце поруч із Торімом на все життя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [989184584] = {
        ["english"] = { [1] = "The Syndicate is made up of a bunch of hacks - disorganized, unskilled, and lazy... " },
        ["text"] = "Синдикат — купка халтурників: неорганізованих, невмілих і ледачих...",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [3255813972] = {
        ["english"] = { [1] = "The Stormpikes uncovered ancient artifacts within Alterac Valley, but the Frostwolf orcs don't take kindly to explorers.  If the dwarves have to fight for knowledge of their ancestors, then so be it!$B$BTo win this battle, defeat the orc, Drek'Thar, in Frostwolf Keep.  Fortune be with you, $c!" },
        ["text"] = "Бурешпилі знайшли стародавні артефакти в Альтерацькій долині, але оркам Морозних Вовків не до вподоби дослідники. Якщо дворфам доведеться битися за знання предків — хай буде так!$B$BЩоб виграти битву, переможи орка Дрек'Тара у фортеці Морозних Вовків. Нехай удача буде з тобою, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [784474699] = {
        ["english"] = { [1] = "The Halls of Stone, a level 77-79 dungeon within Storm Peaks, is now available for testing. Please be in your full group before teleporting to the dungeon. Meeting Stones are not available for this dungeon yet.$B$BTo leave the Halls of Stone, simply exit through the normal exit inside the dungeon and you will be returned here. If you die and release, you should teleport back from this NPC." },
        ["text"] = "Зали Каменю, підземелля 77–79 рівнів у Грозових вершинах, тепер доступні для тестування. Перед телепортацією зберіть повну групу. Каменів зустрічей для цього підземелля поки немає.$B$BЩоб залишити Зали Каменю, просто вийдіть через звичайний вихід усередині підземелля — вас поверне сюди. Якщо загинете й звільните дух, телепортуйтеся назад через цього NPC.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2519244767] = {
        ["english"] = { [1] = "Stop giving me that look. I may not be an adventurer like you, but that doesn't mean I can't have a few muscles. All that stirring makes your arms strong." },
        ["text"] = "Годі так на мене дивитися. Може, я й не шукач пригод, як ти, але це не означає, що в мене не може бути м'язів. Від постійного помішування руки стають сильними.",
        ["npcs"] = { [1] = 4900 },
        ["roles"] = { ["greeting"] = true },
    },
    [955403082] = {
        ["english"] = { [1] = "Thorfin Stoneshield came to us all the way from Ironforge to bring us his expertise in hunting.  If you don't mind breathing the smoke filled air of the Dwarven District then you'll find him at his house in the northeast area of the district." },
        ["text"] = "Торфін Кам’яний Щит прибув до нас аж зі Залізогарта, щоб поділитися своїм мисливським досвідом. Якщо вам не заважає дихати задимленим повітрям Дворфівського району, знайдете його в домі на північному сході району.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1831095175] = {
        ["english"] = { [1] = "The humans claimed much of the Dustwallow Marsh for themselves, but the Stonemaul clan, with our help, has been able to push them back." },
        ["text"] = "Люди привласнили собі значну частину Бруднолипкої трясовини, але клан Кам'яного Молота з нашою допомогою зміг відтиснути їх назад.",
        ["npcs"] = { [1] = 4926 },
        ["roles"] = { ["greeting"] = true },
    },
    [826267403] = {
        ["english"] = { [1] = "The Horde isn't the only danger in this forest. Don't let its seeming tranquility fool you." },
        ["text"] = "Орда — не єдина небезпека в цьому лісі. Не дай його удаваному спокою тебе обдурити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [831817524] = {
        ["english"] = { [1] = "That's great, just give me the signal for when to drop the binding spells." },
        ["text"] = "Чудово, просто подай мені знак, коли знімати зв'язувальні закляття.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2871557788] = {
        ["english"] = { [1] = "Thanks again, $n! I'm very pleased with what we found.$B$BGood luck to you!" },
        ["text"] = "Ще раз дякую, $n! Я дуже задоволений тим, що ми знайшли.$B$BЩасти тобі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [395054837] = {
        ["english"] = { [1] = "The Horde stands ready now that we have finished with all of our resource gathering. We only wait for the sluggish Alliance to finish with theirs, and then on to glorious battle!" },
        ["text"] = "Орда готова — ми завершили весь збір ресурсів. Тепер лише чекаємо, доки повільний Альянс закінчить свій, а тоді — до славної битви!",
        ["npcs"] = { [1] = 15522 },
        ["roles"] = { ["greeting"] = true },
    },
    [4134535522] = {
        ["english"] = { [1] = "The Horde is about honor and war. I am certain that there is nothing honorable about what these apothecaries are doing." },
        ["text"] = "Орда — це честь і війна. Я певен, у тому, що роблять ці аптекарі, немає нічого почесного.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2756161345] = {
        ["english"] = { [1] = "This beam of moonlight leads to Stormwind.  Use your invitation when you're ready." },
        ["text"] = "Цей промінь місячного світла веде до Штормовію. Скористайся запрошенням, коли будеш готовий.",
        ["npcs"] = { [1] = 15694 },
        ["roles"] = { ["greeting"] = true },
    },
    [3589335512] = {
        ["english"] = { [1] = "Tepa is renown for her clothwork.  She can be found at Thunder Bluff Armorers on the middle rise." },
        ["text"] = "Тепа славиться майстерністю роботи з тканиною. Її можна знайти в «Зброярах Громового Бескиду» на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [454793126] = {
        ["english"] = { [1] = "The Hippogryph is a noble beast, proud and swift.  They are an honor to train, and can quickly take their rider a great distance." },
        ["text"] = "Гіпогриф — шляхетний звір, гордий і швидкий. Навчати їх — честь, і вони можуть дуже швидко перенести вершника на велику відстань.",
        ["npcs"] = { [1] = 3841 },
        ["roles"] = { ["greeting"] = true },
    },
    [3685946611] = {
        ["english"] = { [1] = "Tarren Mill lies beyond these trees. The commotion at Durnholde should give us a little time to find Taretha before the entire countryside is flooded with human soldiers. Let's check the nearby barn, then head into town." },
        ["text"] = "За цими деревами — Млин Таррен. Метушня в Дарнгольді дасть нам трохи часу знайти Тарету, перш ніж усю округу заполонять людські солдати. Перевірмо сусідню стодолу, а тоді рушаймо до міста.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [608284871] = {
        ["english"] = { [1] = "The Maneweavers practice their professions out of their home on the road to Darnassus.  Nadyia is an excellent teacher when it comes to Leatherworking.  You should see what she can teach you." },
        ["text"] = "Гривоткачі займаються ремеслами у своєму домі на дорозі до Дарнаса. Надія — чудова наставниця зі шкірництва. Подивися, чого вона може тебе навчити.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2661052892] = {
        ["english"] = { [1] = "The Highborne ghosts that you see wandering through the courtyard and halls of Eldre'Thalas were slain, not by invading Gordok ogres or satyrs, but by the Prince himself!" },
        ["text"] = "Привидів Високородних, яких бачиш у дворі й залах Елдре'Таласа, убили не Ґордокські огри й не сатири, що вторглися сюди, а сам Принц!",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [3020370238] = {
        ["english"] = { [1] = "The high executor and Dame Auriferous are making me wait, but I don't have time for this! My friends are out there dying, $c!" },
        ["text"] = "Верховний кат і дама Ауріферус змушують мене чекати, але в мене немає на це часу! Мої друзі там гинуть, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3576830075] = {
        ["english"] = { [1] = "Thank you again for helping Hilary, $g mister : miss;!  When I grow up, I wanna be a hero just like you!" },
        ["text"] = "Ще раз дякую, що допомогли Гіларі, $g пане : панно;! Коли виросту, хочу бути героєм, як ви!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2764835196] = {
        ["english"] = { [1] = "The Headless Horseman's mind is plagued with dementia!  During Hallow's End, he might attack this village at any moment." },
        ["text"] = "Розум Вершника без голови затьмарений безумством! Під час Тиквовину він може напасти на це селище будь-якої миті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [392601694] = {
        ["english"] = { [1] = "The blade and Mograine were a singular entity. Do you understand? This act corrupted the blade and lead to Mograine's own corruption as a death knight of Kel'Thuzad. I swore that if I lived, I would expose the perpetrators of this heinous crime. For two days I remained under the rot and contagion of Scourge - gathering as much strength as possible to escape the razed city.\010" },
        ["text"] = "Клинок і Моґрейн були єдиним цілим. Розумієш? Цей вчинок осквернив клинок і зрештою призвів до осквернення самого Моґрейна, який став лицарем смерті Кел'Тузада. Я присягнувся: якщо виживу, викрию винуватців цього огидного злочину. Два дні я пролежав серед гнилі й зарази Скари, збираючи сили, щоб утекти зі спаленого міста.\010",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [1773952457] = {
        ["english"] = { [1] = "Tailoring you say?  Hmmm.  Ah yes, of course.  You'll need to head to Thunder Bluff, up north.  Take the path out of the village to get there.  When you arrive at the base of the bluffs ride the elevator to the top of the rise and speak with one of the Bluffwatchers." },
        ["text"] = "Кравецтво, кажеш? Гм-м. А, так, звісно. Тобі треба вирушити на північ, до Громового Бескиду. Вийди стежкою із селища. Коли дістанешся підніжжя бескидів, піднімись ліфтом нагору й поговори з одним із вартових Бескиду.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [349825357] = {
        ["english"] = { [1] = "The Headless Horseman was scary, but I wasn't scared!  Not me!" },
        ["text"] = "Вершник без голови був страшний, але я не злякався! Я — ні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1409450398] = {
        ["english"] = { [1] = "The Highlord was the lynchpin of the Crusade. Aye, Mograine was called the Ashbringer because of his exploits versus the armies of the Lich King. With only blade and faith, Mograine would walk into whole battalions of undead and emerge unscathed - the ashes of his foes being the only indication that he had been there at all. Do you not understand? The very face of death feared him! It trembled in his presence!" },
        ["text"] = "Верховний лорд був стрижнем Походу. Так, Моґрейна називали Спопелителем за його подвиги проти армій Короля-ліча. Лише з клинком і вірою Моґрейн входив у цілі батальйони невмерлих і виходив неушкодженим — лише попіл ворогів свідчив, що він узагалі там був. Ти не розумієш? Сам лик смерті боявся його! Тремтів у його присутності!",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [1178509172] = {
        ["english"] = { [1] = "The corpse of one of the Broken lies here.  Mysteriously, the cause of its death does not appear to be from one of the mutated moths.$B$BPerhaps it has something to do with the strange object resting right next to its outstretched hand?" },
        ["text"] = "Тут лежить тіло одного зі Зломлених. Дивно, але причина смерті не схожа на напад однієї з мутованих молей.$B$BМожливо, це якось пов'язано з дивним предметом біля його простягнутої руки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [823582392] = {
        ["english"] = { [1] = "The humans built an inn on the edge of the Barrens. The Shady Rest, they called it. Weeks ago, it was burned down.$b$bThe Warchief told us to leave the humans alone, so long as they didn't cross our borders, but it appears someone violated his wishes.$b$bHe has put me in charge of getting to the bottom of it. If you wish to provide assistance, go to the remains of the Shady Rest Inn and return any clues you find to me." },
        ["text"] = "Люди збудували корчму на краю Степів. Назвали її «Тінистий Притулок». Кілька тижнів тому вона згоріла.$b$bВождь наказав не чіпати людей, доки вони не переходять наші кордони, але, схоже, хтось порушив його волю.$b$bВін доручив мені з'ясувати правду. Якщо хочеш допомогти, іди до руїн «Тінистого Притулку» й принеси мені всі знайдені докази.",
        ["npcs"] = { [1] = 4926 },
        ["roles"] = { ["greeting"] = true },
    },
    [3294911528] = {
        ["english"] = { [1] = "The guards of Theramore are the finest group of Alliance soldiers based in Kalimdor. It is our duty to uphold the laws of the Alliance even so far away from our homes." },
        ["text"] = "Варта Терамора — найкращі солдати Альянсу в Калімдорі. Наш обов'язок — підтримувати закони Альянсу навіть так далеко від дому.",
        ["npcs"] = { [1] = 4944 },
        ["roles"] = { ["greeting"] = true },
    },
    [2454187106] = {
        ["english"] = { [1] = "The needle is small, but the thread is strong, and the stitches are fine. Our pact with Thrall and the others will hold. The Horde will not be driven from these lands." },
        ["text"] = "Голка мала, але нитка міцна, а стібки надійні. Наш союз із Траллом та іншими витримає. Орду не витіснять із цих земель.",
        ["npcs"] = { [1] = 3007 },
        ["roles"] = { ["greeting"] = true },
    },
    [4110378072] = {
        ["english"] = { [1] = "Tai'jin is her name and you'll find her inside the barracks on the east side of Razor Hill.  She'll teach you to respect the gods.  Make certain that you show her the proper respect in return!" },
        ["text"] = "Її звати Тай'джин, і ти знайдеш її в казармах на східному боці Колючого Пагорба. Вона навчить тебе шанувати богів. І не забудь виявити належну пошану й до неї!",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2682977989] = {
        ["english"] = { [1] = "Strength of the body is the power and swiftness of action.  You must keep yourself fit at all times, both physically and mentally.  The bear's girth highlights its strength, as it is a ferocious foe in combat.  The bear's girth, however, belies its lithe agility and sharp mind.  These are surprises you will use to your advantage.$B$BYou must rely on the strength of the bear's body in order to master the way of the Claw." },
        ["text"] = "Сила тіла — це міць і швидкість дії. Ти завжди мусиш підтримувати себе у формі — і фізично, і розумово. Масивність ведмедя підкреслює його силу, адже в бою це лютий супротивник. Та ця масивність приховує спритність і гострий розум. Саме ці несподівані якості ти використаєш на свою користь.$B$BЩоб опанувати шлях Кігтя, ти мусиш покладатися на силу ведмежого тіла.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [3003354992] = {
        ["english"] = { [1] = "The Scourge brought only small forces to bear against each of Azeroth's capital cities, while their main forces periodically attack the following lands:$B$BAzshara, the Blasted Lands, the Burning Steppes, the Tanaris Desert, the Eastern Plaguelands and Winterspring." },
        ["text"] = "Скара кинула лише невеликі сили проти кожної столиці Азероту, тоді як основні війська періодично атакують такі землі:$B$BАзшара, Спустошені землі, Палаючий степ, пустеля Танаріс, Східне Чумнозем'я та Зимоключ.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [790058688] = {
        ["english"] = { [1] = "That was an impressive display.  But are you ready for your next challege?" },
        ["text"] = "Вражаюче видовище. Але чи готовий ти до наступного випробування?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1823549922] = {
        ["english"] = { [1] = "The graveyards in Alterac Valley are where the souls of the deceased find rest and succor.  If you die, then your spirit will drift to the closest graveyard that our side controls." },
        ["text"] = "Кладовища Альтерацької долини — місця, де душі загиблих знаходять спокій і прихисток. Якщо помреш, твій дух переміститься до найближчого кладовища, яке контролює наша сторона.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3555830690] = {
        ["english"] = { [1] = "The grace with which I fight is not something I can teach you, but I can teach you the use of various weapons." },
        ["text"] = "Грації, з якою я б'юся, навчити не можна, але я можу навчити тебе користуватися різною зброєю.",
        ["npcs"] = { [1] = 11866 },
        ["roles"] = { ["greeting"] = true },
    },
    [1433068404] = {
        ["english"] = { [1] = "The Goddess has granted me wisdom, stranger. If it is her will, I shall pass it on to you." },
        ["text"] = "Богиня дарувала мені мудрість, незнайомцю. Якщо така її воля, я передам її тобі.",
        ["npcs"] = { [1] = 11070 },
        ["roles"] = { ["greeting"] = true },
    },
    [911605414] = {
        ["english"] = { [1] = "The Firelord and his brethren once held sway over this entire world, mortal. As a servant of the Old Gods, he fought against the Titans for domination of this planet. The victorious Titans banished my master and his brethren to the Elemental Plane - there to remain imprisoned until the end of time." },
        ["text"] = "Володар вогню та його побратими колись панували над усім цим світом, смертний. Як слуга Старих Богів, він воював із титанами за владу над планетою. Переможні титани вигнали мого господаря та його братів на Стихійний план — там вони мали лишатися ув'язненими до кінця часів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3504724621] = {
        ["english"] = { [1] = "The goblin Steamwheedle Fighting Circuit is beginning soon. They're holding practice matches in their arenas now, but ranking fights begin in $4262d." },
        ["text"] = "Ґоблінський Бойовий Турнір Парової Шляхти скоро почнеться. Зараз на аренах проходять тренувальні матчі, а рейтингові бої почнуться через $4262d.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4282278909] = {
        ["english"] = { [1] = "Thanks to you, we can now unlock the secrets of the crystals and the mysterious pylons, $N. If you need more information at any time, please come back and visit me again!" },
        ["text"] = "Завдяки тобі ми тепер можемо розкрити таємниці кристалів і загадкових пілонів, $N. Якщо тобі колись знадобиться більше відомостей, просто повертайся до мене!",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [2512360012] = {
        ["english"] = { [1] = "The Fleshwerks will never again produce soldiers for the Lich King's armies." },
        ["text"] = "Плотеробня більше ніколи не створюватиме солдатів для армій Короля-ліча.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [571344734] = {
        ["english"] = { [1] = "The gnome weapon master Bixi can train you in crossbows. She's found in the Timberline Arms in Ironforge." },
        ["text"] = "Гномка-майстриня зброї Біксі може навчити тебе володіти арбалетами. Її знайдеш у «Зброї Лісового Краю» в Залізогарті.",
        ["npcs"] = { [1] = 11866 },
        ["roles"] = { ["greeting"] = true },
    },
    [91773573] = {
        ["english"] = { [1] = "The ghostly figure looks at you with mistrust in her eyes and remains silent." },
        ["text"] = "Примарна постать дивиться на тебе з недовірою й мовчить.",
        ["npcs"] = { [1] = 15293 },
        ["roles"] = { ["greeting"] = true },
    },
    [3520957395] = {
        ["english"] = { [1] = "The Frostwolf Graveyard is along the side of the road, not far north of Frostwolf Village.$B$BThe Horde currently controls it." },
        ["text"] = "Кладовище Морозних Вовків розташоване край дороги, трохи на північ від селища Морозних Вовків.$B$BНаразі його контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1501947008] = {
        ["english"] = { [1] = "Thorium Brotherhood or not, if one of them Dark Iron gets near to me they'll taste my mattock up the side of their head!  Now, where can I send ya $G lad : lass;?" },
        ["text"] = "Братство Торію чи ні, якщо хоч один із тих дворфів Темного Заліза підійде до мене, отримає кайлом по голові! Ну, куди вас відправити, $G хлопче : дівчино;?",
        ["npcs"] = { [1] = 2941 },
        ["roles"] = { ["greeting"] = true },
    },
    [3172412916] = {
        ["english"] = { [1] = "Teach me how to create and apply a Runecloth Bandage, Doctor.", [2] = "Teach me how to create and apply a Runecloth Bandage, Doctor.\010" },
        ["text"] = "Навчіть мене виготовляти й накладати бинт із рунічної тканини, лікарю.",
        ["npcs"] = { [1] = 12939 },
        ["roles"] = { ["reply"] = true },
    },
    [749626672] = {
        ["english"] = { [1] = "Throm-ka! What you looking for, stranger?" },
        ["text"] = "Тром-ка! Чого шукаєш, чужинцю?",
        ["npcs"] = { [1] = 11066 },
        ["roles"] = { ["greeting"] = true },
    },
    [2546276561] = {
        ["english"] = { [1] = "The ruins of Dire Maul stand in central Ferelas." },
        ["text"] = "Руїни Страхомістя стоять у центральній частині Фераласа.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [947655945] = {
        ["english"] = { [1] = "There's an old saying, \"Give a man a fish; you have fed him for a day.  Teach a man to fish; and you have fed him for a lifetime.\"  Of course, you might want to cook that fish and that is where I come in." },
        ["text"] = "Є стара приказка: «Дай людині рибу — нагодуєш її на день. Навчи ловити рибу — нагодуєш на все життя». Звісно, ту рибу ще варто приготувати — і тут уже в справу вступаю я.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4172273683] = {
        ["english"] = { [1] = "The seas are a dangerous place, $c.  We must be alert." },
        ["text"] = "Море — небезпечне місце, $c. Треба бути пильними.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1469688371] = {
        ["english"] = { [1] = "The forces of the Sentinel Army hold back the Horde across all of Kalimdor. While the war continues in Ashenvale and Stonetalon, our forces are also needed here, to protect these remaining wilds and prevent our enemies from gaining further footholds." },
        ["text"] = "Сили Армії Вартових стримують Орду по всьому Калімдору. Поки війна триває в Ясенедолі й Кам'янистих горах, наші сили потрібні й тут — захищати рештки дикої природи та не дозволяти ворогам закріплюватися далі.",
        ["npcs"] = { [1] = 3936 },
        ["roles"] = { ["greeting"] = true },
    },
    [3622376374] = {
        ["english"] = { [1] = "The flight from Grom'gol to Undercity is beautiful, though uneventful.  Though that is no excuse to fall asleep on the job." },
        ["text"] = "Політ із Ґром'ґола до Підмістя гарний, хоч і без пригод. Але це не привід засинати на роботі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1934077561] = {
        ["english"] = { [1] = "Thank you!  You freed me!" },
        ["text"] = "Дякую! Ти звільнив мене!",
        ["npcs"] = { [1] = 11064 },
        ["roles"] = { ["greeting"] = true },
    },
    [223933577] = {
        ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the east end of the faire. I hear that she's placed a target ring way over on Crystal Lake for you to aim for as you sail through the air!" },
        ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на східному краю ярмарку. Кажуть, вона поставила кільце-мішень аж над Кришталевим озером, щоб ти цілився в нього під час польоту!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [114895077] = {
        ["english"] = { [1] = "The Silverwing Sentinels are hardly what I would call honorable opponents.  But if you are intent upon their slaughter $c, then seek out Brakgul Deathbringer in the Hall of the Brave.", [2] = "The Silverwing Sentinels are hardly what I would call honorable opponents. But if you are intent upon their slaughter $c, then seek out Brakgul Deathbringer in the Hall of the Brave." },
        ["text"] = "Срібнокрилі Вартові — аж ніяк не ті, кого я назвав би почесними супротивниками. Але якщо ти справді прагнеш їх винищити, $c, знайди Бракґула Смертеносця в Залі Відважних.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2005580149] = {
        ["english"] = { [1] = "The League of Arathor is trying to reclaim their ancestral holdings in Arathi Basin from the Forsaken.  If you would aid them $N speak to Donal Osgood in the Hall of Arms." },
        ["text"] = "Ліга Аратора намагається повернути свої прадавні володіння в Низині Араті, відібравши їх у Відречених. Якщо хочеш допомогти їм, $N, поговори з Доналом Осґудом у Залі Зброї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4231056293] = {
        ["english"] = { [1] = "Surely Mot didn't send you to me? He knows better. You are not yet capable of understanding what I would teach you. See my son Mot, just outside there, and finish training with him." },
        ["text"] = "Невже Мот послав тебе до мене? Він краще знає. Ти ще не здатний зрозуміти те, чого я міг би тебе навчити. Знайди мого сина Мота надворі й закінчи навчання з ним.",
        ["npcs"] = { [1] = 3011 },
        ["roles"] = { ["greeting"] = true },
    },
    [2931689775] = {
        ["english"] = { [1] = "The Shen'dralar were Queen Azshara's most revered arcanists. It was within these very walls that the Queen's most important demands were processed - often in secret.$B$BAfter the destruction of the Well and the subsequent lethargy that overcame the Highborne and lesser night elf sects, the Prince of Eldre'Thalas, Tortheldrin, began construction of the pylons that you see littering the halls of the west wing.\010" },
        ["text"] = "Шен'дралар були найшанованішими чародіями королеви Азшари. Саме в цих стінах виконувалися найважливіші накази Королеви — часто таємно.$B$BПісля знищення Колодязя й подальшої млявості, що охопила Високородних та інші групи нічних ельфів, принц Елдре'Таласа Тортелдрін почав будівництво пілонів, якими всіяні зали західного крила.\010",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [3219622355] = {
        ["english"] = { [1] = "The Firelord's advances were wholly unknown to Thunderaan. Before my Lord could react, Sulfuras, legendary hammer of Ragnaros, would strike an unmerciful blow. Thunderaan fell, utterly defeated.$B$BThe Firelord feasted upon the essence of my Lord, but was unable to consume him entirely." },
        ["text"] = "Наступ Володаря вогню був для Тундераана цілковитою несподіванкою. Перш ніж мій володар устиг відреагувати, Сульфурас, легендарний молот Раґнароса, завдав безжального удару. Тундераан упав, остаточно переможений.$B$BВолодар вогню поглинув сутність мого повелителя, але не зміг пожерти її повністю.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [2118666665] = {
        ["english"] = { [1] = "The fleet is ready, $N. You must take this beacon and place it at the western crater of the central battlezone. Defend the beacon from attackers until the fleet is able to lock on to its coordinates!" },
        ["text"] = "Флот готовий, $N. Візьми цей маяк і встанови його у західному кратері центральної зони бою. Захищай маяк від нападників, доки флот не зможе зафіксувати його координати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [700285350] = {
        ["english"] = { [1] = "Tailoring can come in very handy. I once had to sew my arm back on." },
        ["text"] = "Кравецтво може дуже стати в пригоді. Якось мені довелося пришити собі руку назад.",
        ["npcs"] = { [1] = 11049 },
        ["roles"] = { ["greeting"] = true },
    },
    [4248079018] = {
        ["english"] = { [1] = "The corruption of Felwood has trapped my spirit here... I may never rest..." },
        ["text"] = "Осквернення Сквернолісся скувало тут мій дух... Можливо, я ніколи не знайду спокою...",
        ["npcs"] = { [1] = 9598 },
        ["roles"] = { ["greeting"] = true },
    },
    [2752542020] = {
        ["english"] = { [1] = "The Dun Baldar North Bunker protects the eastern entrance to Dun Baldar.$B$BIt is controlled by the Alliance." },
        ["text"] = "Північний бункер Дун-Балдара захищає східний вхід до Дун-Балдара.$B$BЙого контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2268749332] = {
        ["english"] = { [1] = "The fel crystalforge can be used to transform your apexis shards into unstable flasks of the beast.  These flasks make the imbiber more agile, stronger and heartier.$B$BIt appears, however, that you do not have the ten shards necessary to purchase even a single flask." },
        ["text"] = "Сквернокристалокузня може перетворювати апекситові уламки на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип'є, спритнішим, сильнішим і витривалішим.$B$BАле, схоже, в тебе немає десяти уламків, потрібних навіть для одного флакона.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3933521866] = {
        ["english"] = { [1] = "Thank you, Tirion. What of your identity?" },
        ["text"] = "Дякую, Тіріоне. А що з твоєю особою?",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["reply"] = true },
    },
    [2828542739] = {
        ["english"] = { [1] = "The Lich King is near, $n. His voice taunts me...$b$bLet us silence him at last!" },
        ["text"] = "Король-ліч близько, $n. Його голос глузує з мене...$b$bЗмусімо його нарешті замовкнути!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [945575181] = {
        ["english"] = { [1] = "Stop! Do not go any further, mortal. You are ill-prepared to face the forces of the Infinite Dragonflight.Come, let me help you." },
        ["text"] = "Стій! Не йди далі, смертний. Ти не готовий зустрітися із силами Нескінченної драконячої зграї. Ходи, я тобі допоможу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2856053257] = {
        ["english"] = { [1] = "There are secrets contained within these halls that are beyond our wildest dreams." },
        ["text"] = "У цих залах приховані таємниці, про які ми й мріяти не могли.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [643616273] = {
        ["english"] = { [1] = "The conflicts in Outland are deadlier than any I have seen.  And their most tragic victims are the children that are left behind.$B$BNow, with the threat against Shattrath from the arakkoa of Skettis, there will be even more orphans to take care of.  These children often live without the hope of a bright future.$B$BBut you have the power to do something about that.  It's Children's Week, $c, and I implore you to volunteer to bring joy and wonder into a child's life." },
        ["text"] = "Конфлікти в Позамежжі смертоносніші за все, що я бачила. А найтрагічніші їхні жертви — діти, що лишаються самі.$B$BТепер, через загрозу Шаттрату з боку араккоа Скеттіса, сиріт стане ще більше. Ці діти часто живуть без надії на світле майбутнє.$B$BАле ти можеш щось змінити. Зараз Дитячий тиждень, $c, і я прошу тебе добровільно подарувати одній дитині радість і диво.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2825424231] = {
        ["english"] = { [1] = "The end draws nigh! Even as we speak our supplies are being shipped to Silithus and should arrive within $2113w days. Once there I am sure that all we be assembled in quick order, and then we'll be awaiting the ringing of the gong at the gates to Ahn'Qiraj to start the war. I look forward to analyzing whether our preparatory efforts will make a difference." },
        ["text"] = "Кінець близько! Поки ми говоримо, наші припаси везуть до Силітуса, і вони мають прибути протягом $2113w днів. Упевнений, там усе швидко зберуть, і тоді ми чекатимемо удару в гонг біля брам Ан'Кіражу, що почне війну. Цікаво буде проаналізувати, чи дадуть результат наші підготовчі зусилля.",
        ["npcs"] = { [1] = 15512 },
        ["roles"] = { ["greeting"] = true },
    },
    [2145457318] = {
        ["english"] = { [1] = "The Emerald Dream has become a dangerous place. I grow increasingly concerned for those who have sacrificed their waking life in Azeroth in hopes of saving it." },
        ["text"] = "Смарагдовий Сон став небезпечним місцем. Я дедалі більше хвилююся за тих, хто пожертвував своїм життям наяву в Азероті, сподіваючись урятувати його.",
        ["npcs"] = { [1] = 11832 },
        ["roles"] = { ["greeting"] = true },
    },
    [2262071840] = {
        ["english"] = { [1] = "The Inn?  Ah, ye looking to toss back some of the best ales Ironforge has to offer?  The Stonefire Tavern is where ye'll want to go.  $B$BYe'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going.", [2] = "The Inn?  Ah, ye looking to toss back some of the best ales Ironforge has to offer?  The Stonefire Tavern is where ye'll want to go. $B$BYe'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going." },
        ["text"] = "Корчма? А, хочеш хильнути найкращого елю, який може запропонувати Залізогарт? Тобі до таверни «Кам'яний Вогонь».$B$BЯкщо входиш до Залізогарта — вона одразу ліворуч від входу, а якщо виходиш — праворуч.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2704658469] = {
        ["english"] = { [1] = "These are dangerous times, adventurer. Walk lightly." },
        ["text"] = "Небезпечні часи, шукачу пригод. Ступай обережно.",
        ["npcs"] = { [1] = 11872 },
        ["roles"] = { ["greeting"] = true },
    },
    [3637974106] = {
        ["english"] = { [1] = "Thanks to everyone's efforts we now have all the iron bars that we need. Check with one of the others to see if there's something else you should be out there collecting for the war effort. Me, I'm going to see if I can get out of here a little early to play some cards." },
        ["text"] = "Завдяки спільним зусиллям у нас тепер є всі потрібні залізні зливки. Розпитай когось іншого, чи немає ще чогось, що треба збирати для війни. А я спробую сьогодні піти трохи раніше й зіграти в карти.",
        ["npcs"] = { [1] = 15431 },
        ["roles"] = { ["greeting"] = true },
    },
    [1660714592] = {
        ["english"] = { [1] = "This is a fine mess." },
        ["text"] = "Ну й халепа.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [80849658] = {
        ["english"] = { [1] = "The saronite... there's something in it!" },
        ["text"] = "Сароніт... у ньому щось є!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [355285777] = {
        ["english"] = { [1] = "The druid, Kal, often spends his time at the moonwell in Dolanaar.  I am certain he would be able to provide you with the training you require." },
        ["text"] = "Друїд Кал часто проводить час біля місячного колодязя в Доланаарі. Певен, він зможе дати тобі потрібне навчання.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [334654937] = {
        ["english"] = { [1] = "Thank goodness for you!  Claw and I were investigating this place when we were jumped by Swamplord Musel'ek.  He can control animals, even druids!$B$BUnfortunately, Claw was caught in bear form at the time, and is now the swamplord's pet.  I don't dare change into cat form or he'll get me too!$B$BI'm afraid you'll have to fight Claw in order to save him.  Just keep heading west; you can't miss him." },
        ["text"] = "Слава богам, що ти тут! Ми з Кігтем досліджували це місце, коли на нас напав Болотяний володар Мусел'ек. Він може підкоряти тварин, навіть друїдів!$B$BНа жаль, Кіготь саме був в образі ведмедя, і тепер він вихованець болотяного володаря. Я навіть не наважуюся перетворитися на кота, бо тоді він підкорить і мене!$B$BБоюся, щоб урятувати Кігтя, тобі доведеться з ним битися. Просто йди далі на захід — не проминеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [571841580] = {
        ["english"] = { [1] = "The warrior's role is one of protection.  Just as we protect our compatriots in battle, we must also protect the interests of the Forsaken." },
        ["text"] = "Роль воїна — захищати. Так само як ми захищаємо побратимів у бою, ми мусимо захищати й інтереси Відречених.",
        ["npcs"] = { [1] = 2119, [2] = 2131, [3] = 4593, [4] = 4594, [5] = 4595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1990284520] = {
        ["english"] = { [1] = "The dwarven weapon master Buliwyf can train you in both one and two-handed axes. He's found in the Timberline Arms in Ironforge." },
        ["text"] = "Дворф-майстер зброї Булівіф може навчити тебе володіти одноручними й дворучними сокирами. Його знайдеш у «Зброї Лісового Краю» в Залізогарті.",
        ["npcs"] = { [1] = 11866, [2] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [2811003419] = {
        ["english"] = { [1] = "The Darkspears stand ready to face the competition and the enemy." },
        ["text"] = "Темносписи готові зустріти і суперників, і ворога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3621447577] = {
        ["english"] = { [1] = "The Dun Baldar South Bunker protects the south and east flanks of Dun Baldar.$B$BIt is controlled by the Alliance." },
        ["text"] = "Південний бункер Дун-Балдара захищає південний і східний фланги Дун-Балдара.$B$BЙого контролює Альянс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2459548702] = {
        ["english"] = { [1] = "The twists and turns of Orgrimmar are designed to thwart invaders. Can you imagine how quickly one of those puny gnomes would get lost in here? Ha! If it was lucky, I'd track it down and keep it as a pet." },
        ["text"] = "Звивисті вулиці Орґріммара створено, щоб збивати загарбників із пантелику. Уявляєш, як швидко тут заблукав би якийсь жалюгідний гном? Ха! Якби йому пощастило, я б вистежив його й залишив собі як вихованця.",
        ["npcs"] = { [1] = 3365 },
        ["roles"] = { ["greeting"] = true },
    },
    [2646012415] = {
        ["english"] = { [1] = "The Cathedral of Light is the center of all the healing practices of Stormwind. There you can find Shaina Fuller to help you learn this craft." },
        ["text"] = "Собор Світла — осередок усіх цілющих ремесел Штормовію. Там знайдеш Шайну Фуллер, яка допоможе опанувати це ремесло.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4179612819] = {
        ["english"] = { [1] = "The Defenders are here to protect Blood Watch from the Sunhawk threat. " },
        ["text"] = "Захисники тут, щоб обороняти Криваву заставу від загрози Сонячних Яструбів. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1323228949] = {
        ["english"] = { [1] = "There's only one person I know of who is more learned in the art of tailoring than myself. Last I heard he could be found in Theramore Isle. He is the person you should seek." },
        ["text"] = "Я знаю лише одну людину, що знається на кравецтві краще за мене. Востаннє чув, що він був на острові Терамор. Саме його тобі й треба шукати.",
        ["npcs"] = { [1] = 1346 },
        ["roles"] = { ["greeting"] = true },
    },
    [2308875128] = {
        ["english"] = { [1] = "They don't realize that they're dead, $r. They are cursed to relive the last memory they had before the town was eaten alive from the inside out. Most of them, anyway. Some were less fortunate.$B$BYou thought the Scourge did this? The Scourge did not yet exist and if they had, we would have at least put up a damned fight.$B$BNo, this was the result of a plague that came out of Scholomance and ravaged the town. It was horrifying and devastating. None survived.$B$BNow leave me to my sorrows." },
        ["text"] = "Вони не розуміють, що мертві, $r. Їх проклято знову й знову переживати останній спогад перед тим, як місто пожерло себе зсередини. Принаймні більшість із них. Декому пощастило ще менше.$B$BДумав, це зробила Скара? Скари тоді ще не існувало, а якби існувала — ми хоча б дали клятий бій.$B$BНі, це була чума з Некроситету, яка спустошила місто. Це було жахливо й нищівно. Ніхто не вижив.$B$BА тепер залиш мене наодинці з моїм горем.",
        ["npcs"] = { [1] = 11285 },
        ["roles"] = { ["greeting"] = true },
    },
    [2965407120] = {
        ["english"] = { [1] = "The Crystal Pylons of Un'Goro are a mystery to all. To the few inhabitants here, they are a source of legend, with much speculation as to their purpose." },
        ["text"] = "Кришталеві пілони Ун'Ґоро — загадка для всіх. Для небагатьох місцевих мешканців вони стали джерелом легенд і безлічі припущень про їхнє призначення.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [840396520] = {
        ["english"] = { [1] = "Thanks, Ragged John. Your story was very uplifting and informative. " },
        ["text"] = "Дякую, Обідраний Джоне. Твоя історія була дуже надихаючою й пізнавальною. ",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3690882659] = {
        ["english"] = { [1] = "The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see?" },
        ["text"] = "Ярмарок Темного Місяця прибув до міста! Не пропусти найзахопливіше видовище у своєму житті?",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["greeting"] = true },
    },
    [46804233] = {
        ["english"] = { [1] = "The burgeoning hero returns! It is good to see you again, $N. You are always welcome at our village." },
        ["text"] = "Юний герой повернувся! Радий знову тебе бачити, $N. У нашому селищі тобі завжди раді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2059189708] = {
        ["english"] = { [1] = "The crystal foci?  Of course we'll explain it seeing as you only have half the brain power to figure it out.$B$BA depleted crystal focus can be combined with ten apexis shards in a simple process, which creates a charged crystal focus.  These charged foci have some healing properties, but more important is their use with a possessed demon.$B$BYou see, the charged focus can be used to enable a possessed demon to exhibit special powers.  After a time, Gahk will have a mission for you to do just that." },
        ["text"] = "Кришталеві фокуси? Звісно, пояснимо, раз у тебе лише половина потрібного розуму, щоб здогадатися самому.$B$BВиснажений кришталевий фокус можна поєднати з десятьма апекситовими уламками — простий процес, що створює заряджений кришталевий фокус. Такі фокуси мають певні цілющі властивості, але важливіше їх використання з одержимим демоном.$B$BРозумієш, заряджений фокус дає одержимому демону особливі сили. Згодом Ґак дасть тобі завдання саме на це.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2806070525] = {
        ["english"] = { [1] = "The Twilight Cult seeks to undo everything we fight to preserve. It is our sworn duty to prevent this calamity from coming to pass, $r." },
        ["text"] = "Сутінковий культ прагне зруйнувати все, що ми боремося зберегти. Наш священний обов'язок — не допустити цієї катастрофи, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3384412323] = {
        ["english"] = { [1] = "Stand at attention, grunt!" },
        ["text"] = "Струнко, рубако!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [813799240] = {
        ["english"] = { [1] = "The conflicts in Outland are deadlier than any I have seen.  And their most tragic victims are the children that are left behind.$B$BNow, with the threat against Shattrath from the arakkoa of Skettis, there will be even more orphans to take care of.  These children often live without the hope of a bright future." },
        ["text"] = "Конфлікти в Позамежжі смертоносніші за все, що я бачила. А найтрагічніші їхні жертви — діти, що лишаються самі.$B$BТепер, через загрозу Шаттрату з боку араккоа Скеттіса, сиріт стане ще більше. Ці діти часто живуть без надії на світле майбутнє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [352053958] = {
        ["english"] = { [1] = "The competition will be fierce, but Orgrimmar's champions will decimate all who stand in our way." },
        ["text"] = "Змагання буде жорстким, але чемпіони Орґріммара зметуть усіх, хто стане на нашому шляху.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3408111144] = {
        ["english"] = { [1] = "The blue dragons themselves aren't here, but followers of Malygos are. I do not know why, but I can tell you this: wherever the blue dragons are, expect to find arcane magic. I wouldn't be surprised if the dragonspawn are here protecting something... perhaps something the Highborne left behind." },
        ["text"] = "Самих синіх драконів тут немає, але є послідовники Маліґоса. Не знаю чому, але скажу одне: де сині дракони — там і таємна магія. Не здивуюся, якщо драконороджені щось тут охороняють... можливо, те, що залишили Високородні.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [2964418654] = {
        ["english"] = { [1] = "The bear spirit looks upon you with a calm and peaceful gaze.  You hear a voice speak to you as though it was coming from the bear, but the creature makes no indication that it is speaking.$B$B\"Greetings, my young friend.  If you have come to me seeking guidance, then perhaps I can help you find what you seek.\"" },
        ["text"] = "Дух ведмедя дивиться на тебе спокійним і мирним поглядом. Ти чуєш голос, ніби він лунає від ведмедя, хоча істота ніяк не показує, що говорить.$B$B«Вітаю, мій юний друже. Якщо ти прийшов по настанову, можливо, я допоможу знайти те, чого ти шукаєш».",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [1958303270] = {
        ["english"] = { [1] = "Thank you again, $N, for helping me to uncover what happened here at the thicket." },
        ["text"] = "Ще раз дякую, $N, що допоміг мені з'ясувати, що сталося тут, у гущавині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [91519682] = {
        ["english"] = { [1] = "The Commander has not been himself as of late. His mistress disappeared while on an archaeological dig in the southern desert - vanished without a trace! Very strange, indeed.$B$BI suppose you're looking for work? Do I need to bash you in the head with a clue?" },
        ["text"] = "Останнім часом Командир сам не свій. Його кохана зникла під час археологічних розкопок у південній пустелі — наче крізь землю провалилася! Дуже дивно.$B$BГадаю, ти шукаєш роботу? Мені що, натякнути тобі ударом по голові?",
        ["npcs"] = { [1] = 15182 },
        ["roles"] = { ["greeting"] = true },
    },
    [2863684870] = {
        ["english"] = { [1] = "The Defenders of Blood Watch protect this outpost from any threat. " },
        ["text"] = "Захисники Кривавої застави боронять цей форпост від будь-якої загрози. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3068851613] = {
        ["english"] = { [1] = "The forest sings with the seeds of change.  Our new friends, the draenei, are here, and we will help them to build a place of their own." },
        ["text"] = "Ліс співає насінням змін. Наші нові друзі, дренеї, вже тут, і ми допоможемо їм збудувати власний дім.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2578195239] = {
        ["english"] = { [1] = "The Cenarion Circle is wise, and has delved into many of earth's secrets.  Craftsmen would do well to heed the words of these druids." },
        ["text"] = "Кенарієве Коло мудре й проникло в чимало таємниць землі. Ремісникам варто прислухатися до слів цих друїдів.",
        ["npcs"] = { [1] = 15282 },
        ["roles"] = { ["greeting"] = true },
    },
    [2343698065] = {
        ["english"] = { [1] = "Then it is Thelman Slatefist that you wish to speak to.  You can find him in the presence of the King at Stormwind Keep.", [2] = "Then it is Thelman Slatefist that you wish to speak to. You can find him in the presence of the King at Stormwind Keep." },
        ["text"] = "Тоді тобі потрібен Телман Кам'яний Кулак. Знайдеш його поруч із Королем у фортеці Штормовію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2914616063] = {
        ["english"] = { [1] = "The Burning Legion presses us hard, but our defenses hold. Every moment we keep Archimonde away from the World Tree brings us closer to victory." },
        ["text"] = "Палаючий Легіон тисне на нас, але оборона тримається. Кожна мить, на яку ми затримуємо Архімонда подалі від Світового Дерева, наближає перемогу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1700002698] = {
        ["english"] = { [1] = "The Burning Inn." },
        ["text"] = "Палаюча корчма.",
        ["npcs"] = { [1] = 4926 },
        ["roles"] = { ["reply"] = true },
    },
    [797104162] = {
        ["english"] = { [1] = "Strange wizard?" },
        ["text"] = "Дивний чарівник?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [588494003] = {
        ["english"] = { [1] = "Stay away from me, $r! There's no telling when the sickness will take me again.$B$BJust leave me alone before it happens again." },
        ["text"] = "Тримайся від мене подалі, $r! Невідомо, коли хвороба знову мене скрутить.$B$BПросто залиш мене в спокої, перш ніж це станеться знову.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2135430236] = {
        ["english"] = { [1] = "That was quite a fight.  Let us catch our breath for a bit." },
        ["text"] = "От це був бій. Переведімо трохи подих.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [541592524] = {
        ["english"] = { [1] = "Tell me about the Beasts Deck." },
        ["text"] = "Розкажи мені про Колоду Звірів.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["reply"] = true },
    },
    [1806232286] = {
        ["english"] = { [1] = "Strong of body and spirit.  There can be no stronger combination!  Find your destiny with Sark Ragetotem in the Hunter's Hall." },
        ["text"] = "Сильний тілом і духом. Сильнішого поєднання не буває! Знайди свою долю із Сарком Лютим Тотемом у Залі Мисливців.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1727496069] = {
        ["english"] = { [1] = "That's it, everything's been collected by both sides. Now it's all being transported over to Silithus and should be there in less than $2113w days. Once that's done and someone rings the gong on the Scarab Dais with the Scepter of the Shifting Sands, the war is on!" },
        ["text"] = "От і все, обидві сторони зібрали все потрібне. Тепер усе везуть до Силітуса, і менш ніж за $2113w днів воно буде там. Коли це станеться й хтось ударить у гонг на Помості Скарабея Скіпетром Мінливих Пісків — війна почнеться!",
        ["npcs"] = { [1] = 15434 },
        ["roles"] = { ["greeting"] = true },
    },
    [2469072686] = {
        ["english"] = { [1] = "The Barrens, with its hot sun and hostile denizens, is the perfect place to test your strength and fortitude." },
        ["text"] = "Степи з їхнім палючим сонцем і ворожими мешканцями — ідеальне місце, щоб випробувати силу й витривалість.",
        ["npcs"] = { [1] = 3483 },
        ["roles"] = { ["greeting"] = true },
    },
    [961936169] = {
        ["english"] = { [1] = "The beasts of these blasted lands exhibit preternatural attributes, heretofore unseen in nature.$B$BWe have theorized that the energy which was released upon the opening of the Dark Portal, infused into their physical being and forced the creatures to evolve into their current forms.$B$BFearsome beasts they are, no doubt, but we also believe that they could prove to be quite useful in our studies.$B$BPerhaps you would be interested in assisting us in the study of these beasts, $N?\010" },
        ["text"] = "Звірі цих Спустошених земель мають надприродні властивості, яких досі не бачили в природі.$B$BМи припускаємо, що енергія, вивільнена під час відкриття Темного порталу, проникла в їхні тіла й примусила істот еволюціонувати до теперішніх форм.$B$BБез сумніву, це страшні звірі, але ми вважаємо, що вони можуть бути надзвичайно корисними для наших досліджень.$B$BМожливо, тобі цікаво допомогти нам вивчити цих звірів, $N?\010",
        ["npcs"] = { [1] = 7505 },
        ["roles"] = { ["greeting"] = true },
    },
    [1097550464] = {
        ["english"] = { [1] = "The battle for Arathi Basin is a battle for resources.  Lumber, ore, food... all these are needed in order to wage a good war.$B$BDenying our enemies of their supplies is as good as killing them on the battlefield." },
        ["text"] = "Битва за Низину Араті — це битва за ресурси. Деревина, руда, їжа... усе це необхідне для війни.$B$BПозбавити ворога постачання майже те саме, що вбити його на полі бою.",
        ["npcs"] = { [1] = 15022 },
        ["roles"] = { ["greeting"] = true },
    },
    [1039490946] = {
        ["english"] = { [1] = "The bat handler" },
        ["text"] = "Доглядач кажанів",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5624, [13] = 5725 },
        ["roles"] = { ["reply"] = true },
    },
    [2888678822] = {
        ["english"] = { [1] = "The blade itself had to be crafted in ceremony with the children of the Aspects. A rare occurrence indeed... For not only would a dragon have to willingly heat and mold the enchanted metal with their breath, they would also need to contain the fury of their own enchantment by using their blood as temper." },
        ["text"] = "Сам клинок треба було викувати в обряді за участю дітей Аспектів. Надзвичайно рідкісний випадок... Дракон мав не лише добровільно нагріти й сформувати зачарований метал своїм подихом, а й приборкати лють власного зачарування, використавши свою кров для гартування.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [1683408867] = {
        ["english"] = { [1] = "This here is the finest, most state of the art mode of transportation money can build. What? Deeprun Tram? Gnomes? Listen pal, If you believe that garbage then I've got a statue down in Stranglethorn to sell ya. Now, are you walking to Grom'Gol or are you gonna ride in style in this fine flying machine? Your choice." },
        ["text"] = "Оце тут — найкращий і найсучасніший транспорт, який тільки можна купити за гроші. Що? Глибокобіжний трамвай? Гноми? Слухай, друже, якщо віриш у ці дурниці, то я ще можу продати тобі статую в Тернистій долині. То що, підеш до Ґром’ґола пішки чи полетиш із шиком на цій чудовій машині? Вибір за тобою.",
        ["npcs"] = { [1] = 3150 },
        ["roles"] = { ["greeting"] = true },
    },
    [4096013194] = {
        ["english"] = { [1] = "There is only one Warchief, Eitrigg!" },
        ["text"] = "Є лише один Вождь — Айтріґ!",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [4017185930] = {
        ["english"] = { [1] = "The symbols on the tablet are carefully transcribed..." },
        ["text"] = "Символи з таблички ретельно переписано...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [65016107] = {
        ["english"] = { [1] = "The auction house" },
        ["text"] = "Аукціонний дім",
        ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 },
        ["roles"] = { ["reply"] = true },
    },
    [294330367] = {
        ["english"] = { [1] = "The ranged Shield-Breaker attack is simple to learn, but difficult to master. Alone it may seem weak, but in conjunction with Thrusts and Charges the Shield-Breaker makes a successful jouster.$B$BFind a Ranged Target. Take a moment to understand the Shield-Breaker's range... how much space you need, and how far you can hurl the lance.$B$BAfter that? Well. Start throwing, and do not stop until you've broken every last layer of Defend and pierced the vulnerable target.$B$BThis tactic will serve you well in actual mounted combat: Break down your opponents' defenses... and then crush them!" },
        ["text"] = "Дальню атаку «Розбивач щита» легко вивчити, але важко опанувати. Сама по собі вона здається слабкою, та в поєднанні з Випадами й Ривками робить із тебе успішного турнірного вершника.$B$BЗнайди дальню мішень. Відчуй дальність «Розбивача щита»: скільки простору потрібно й наскільки далеко можеш кинути спис.$B$BА потім? Кидай і не зупиняйся, доки не зіб'єш усі шари Захисту й не проб'єш вразливу мішень.$B$BЦя тактика стане в пригоді у справжньому кінному бою: руйнуй захист супротивників... а тоді трощи їх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1826772307] = {
        ["english"] = { [1] = "The Arch Druid believes that Ivus the Forest Lord will come once he is made aware of the destructive forces within this valley." },
        ["text"] = "Верховний друїд вірить, що Івус Володар Лісу прийде, щойно дізнається про руйнівні сили в цій долині.",
        ["npcs"] = { [1] = 13443 },
        ["roles"] = { ["greeting"] = true },
    },
    [3194313353] = {
        ["english"] = { [1] = "The arcane only corrupts those who are weak. Keep up on your training, or you may find a similar fate." },
        ["text"] = "Таємна магія розбещує лише слабких. Не занедбуй тренувань, інакше тебе може спіткати така сама доля.",
        ["npcs"] = { [1] = 460, [2] = 461, [3] = 906, [4] = 3324, [5] = 3325, [6] = 3326, [7] = 5171, [8] = 5172, [9] = 5173, [10] = 5495, [11] = 5496, [12] = 5612, [13] = 6251 },
        ["roles"] = { ["greeting"] = true },
    },
    [502697056] = {
        ["english"] = { [1] = "The fleet is ready, $N. You must take this beacon and place it at the eastern crater of the central battlezone. Defend the beacon from attackers until the fleet is able to lock on to its coordinates!" },
        ["text"] = "Флот готовий, $N. Візьми цей маяк і встанови його у східному кратері центральної зони бою. Захищай маяк від нападників, доки флот не зможе зафіксувати його координати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [628857854] = {
        ["english"] = { [1] = "The ancient Altar of Hakkar stands silently near the entrance to the room.$B$BLooking to the balconies above it, you notice a large serpent-like statue rests on each. The statues look very much like the ones on the altar before you. They must be related in some way..." },
        ["text"] = "Стародавній Вівтар Гаккара мовчки стоїть біля входу до кімнати.$B$BПоглянувши на балкони над ним, ти помічаєш на кожному велику статую, схожу на змію. Вони дуже нагадують статуї на вівтарі перед тобою. Мабуть, між ними є якийсь зв'язок...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3992577393] = {
        ["english"] = { [1] = "The actions of these deserters shames us all. A shame so powerful that it must be witnessed to be understood. It is why Ug'thor is here... The boy must learn." },
        ["text"] = "Вчинки цих дезертирів ганьблять усіх нас. Це така ганьба, що її треба побачити на власні очі, аби зрозуміти. Саме тому Уґ'тор тут... Хлопець має навчитися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1919800648] = {
        ["english"] = { [1] = "Tasty drinks for sale!  Quench your thirst on some of the Darkmoon Faire's finest brews!" },
        ["text"] = "Смачні напої на продаж! Втамуйте спрагу найкращими напоями ярмарку Темного Місяця!",
        ["npcs"] = { [1] = 14844 },
        ["roles"] = { ["greeting"] = true },
    },
    [4146160664] = {
        ["english"] = { [1] = "Tell me how to use the Blastenheimer 5000 Ultra Cannon." },
        ["text"] = "Розкажи, як користуватися Ультрагарматою Бластенгаймера 5000.",
        ["npcs"] = { [1] = 15303 },
        ["roles"] = { ["reply"] = true },
    },
    [547886522] = {
        ["english"] = { [1] = "That's fine. When do I start?" },
        ["text"] = "Гаразд. Коли починати?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [564396695] = {
        ["english"] = { [1] = "That will be the choice of the demon you wish to conjure and enslave. We wield dark powers and we pay grossly for the use of said powers." },
        ["text"] = "Це залежатиме від того, якого демона ти захочеш викликати й поневолити. Ми володіємо темними силами й платимо страшну ціну за їх використання.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1848897545] = {
        ["english"] = { [1] = "The Frost Lord, Ahune, must be stopped.$B$BEven now he is taking form, summoned from his elemental prison by the mad cultists of the Twilight's Hammer.$B$BIf he's allowed to enter our world completely, he'll bury us beneath an eternal winter." },
        ["text"] = "Володаря Криги, Агуна, треба зупинити.$B$BВін уже набуває форми, викликаний зі своєї стихійної в'язниці божевільними культистами Сутінкового Молота.$B$BЯкщо дозволити йому повністю увійти в наш світ, він поховає нас під вічною зимою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2690650590] = {
        ["english"] = { [1] = "Sure are a lot of litter bugs around here." },
        ["text"] = "Ох і багато ж тут сміттярів.",
        ["npcs"] = { [1] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [4096947208] = {
        ["english"] = { [1] = "The blood of our enemies shall be spilt upon the battlefield. The great elementals shall answer our call and crush all that stand in our way." },
        ["text"] = "Кров наших ворогів проллється на полі бою. Великі елементалі відгукнуться на наш поклик і розчавлять усіх, хто стане на шляху.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3223637684] = {
        ["english"] = { [1] = "Tell me more about Forging Weapons." },
        ["text"] = "Розкажи мені більше про кування зброї.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3802201473] = {
        ["english"] = { [1] = "The Headless Horseman, once a knight of the Silver Hand and a hero among his fellow paladins, is cursed.  Driven insane within the Scarlet Monastery, he believes that he is alive and we are dead.$B$BNow, his fervor no longer serves the Light.  With the coming of Hallow's End, he spreads gloom and fire across the villages of Azeroth." },
        ["text"] = "Вершник без голови колись був лицарем Срібної Десниці й героєм серед паладинів, але його проклято. Збожеволівши в Багряному монастирі, він вірить, що живий він, а мертві — ми.$B$BТепер його запал більше не служить Світлу. З приходом Тиквовину він несе морок і вогонь селами Азероту.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1856848306] = {
        ["english"] = { [1] = "The Sons of Gruul must be defeated if we are to shake off our shackles and live as free ogres once more!$B$BWe must work quietly, yet quickly, if our underground resistance is to have a chance of success." },
        ["text"] = "Синів Ґруула треба перемогти, якщо ми хочемо скинути кайдани й знову жити вільними ограми!$B$BМи повинні діяти тихо, але швидко, якщо наше підпільне повстання має хоч якийсь шанс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2336442983] = {
        ["english"] = { [1] = "The Dark Iron dwarves of the Slag Pit in Searing Gorge have a great number of locked boxes." },
        ["text"] = "У дворфів Темного Заліза в Шлаковій Ямі у Випаленій ущелині чимало замкнених скринь.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [699544776] = {
        ["english"] = { [1] = "The pleasure is mine, madam. Might I ask what it is that you are doing here?" },
        ["text"] = "Задоволення взаємне, пані. Дозвольте запитати, що ви тут робите?",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [3792117766] = {
        ["english"] = { [1] = "Then head over to Bena's Alchemy on the middle rise and talk to Bena herself.  She will be able to help you master the art of potion brewing." },
        ["text"] = "Тоді йди до «Алхімії Бени» на середньому виступі й поговори з самою Беною. Вона допоможе тобі опанувати мистецтво варіння зіль.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2230579877] = {
        ["english"] = { [1] = "The League of Arathor has sworn to retake Arathi for humans of Stromgarde and the Alliance.  It is a battle hard fought, but a battle worth fighting." },
        ["text"] = "Ліга Аратора присягнулася повернути Араті людям Стромґарда й Альянсу. Це важка битва, але вона варта того.",
        ["npcs"] = { [1] = 14983 },
        ["roles"] = { ["greeting"] = true },
    },
    [1067584620] = {
        ["english"] = { [1] = "Thank you, $c, for seeing to it that I received the letter from my brother.$B$BRest assured, his death will not have been in vain. The blue dragonflight will pay for this.$B$BI'll see to it personally!" },
        ["text"] = "Дякую, $c, що подбав, аби лист від мого брата дістався до мене.$B$BБудь певен: його смерть не була марною. Синя драконяча зграя за це заплатить.$B$BЯ особисто про це подбаю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [930597514] = {
        ["english"] = { [1] = "The Scourge infestation grows in the Blasted Lands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2280W" },
        ["text"] = "Навала Скари посилюється в Спустошених землях. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2280W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [44183360] = {
        ["english"] = { [1] = "The Thunderbrews run a fine Inn in Kharanos which bears their name.  Stop in for a pint and a bit of rest." },
        ["text"] = "Громовари тримають гарну корчму в Караносі, що носить їхнє ім'я. Зайди випити кухоль і трохи відпочити.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [4024000158] = {
        ["english"] = { [1] = "That is tragic. How did this happen?" },
        ["text"] = "Це трагедія. Як так сталося?",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["reply"] = true },
    },
    [2568345025] = {
        ["english"] = { [1] = "Tell me about the hide." },
        ["text"] = "Розкажи мені про шкуру.",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["reply"] = true },
    },
    [2581413641] = {
        ["english"] = { [1] = "Thanks to the Warchief, even here in the remains of our former prison, some hope remains, and the Horde rises anew." },
        ["text"] = "Завдяки вождю навіть тут, серед решток нашої колишньої в'язниці, ще жевріє надія, а Орда постає знову.",
        ["npcs"] = { [1] = 2706 },
        ["roles"] = { ["greeting"] = true },
    },
    [3195219780] = {
        ["english"] = { [1] = "The plans for my twenty-foot tall turkey baster are nearly complete! Now all I need is a twenty-foot tall turkey..." },
        ["text"] = "Креслення моєї двадцятифутової спринцівки для індички майже готові! Тепер лишилося знайти двадцятифутову індичку...",
        ["npcs"] = { [1] = 11029 },
        ["roles"] = { ["greeting"] = true },
    },
    [3030517804] = {
        ["english"] = { [1] = "Success!  I have attuned myself to Hellfire Citadel and the magic within.  Ah, such power!$B$BThere are countless fel orcs in that place... but that is not all!  I sense demonic power within those walls as well...$B$BIf you open yourself, then I shall grasp your mind -- briefly, mind you -- and take quill to parchment and record my findings for you..." },
        ["text"] = "Успіх! Я налаштувався на Цитадель Пекельного Вогню та магію всередині. Ах, яка сила!$B$BТам безліч орків скверни... але це ще не все! Я відчуваю й демонічну силу в тих мурах...$B$BЯкщо відкриєш свій розум, я ненадовго — лише ненадовго — заволодію ним, а тоді візьму перо й пергамент та запишу для тебе свої знахідки...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [466337085] = {
        ["english"] = { [1] = "Take it with my gratitude, $c." },
        ["text"] = "Візьми це з моєю вдячністю, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2012144835] = {
        ["english"] = { [1] = "Stupid snow... Hey, you're, $n, aren't you? I've just received a message asking for you." },
        ["text"] = "Клятий сніг... Гей, ти ж $n, еге ж? Я щойно отримав повідомлення — тебе шукають.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [79186336] = {
        ["english"] = { [1] = "They died. All of them...$B$BAs the Murkbloods cut through us, something took hold of me that I cannot understand. Tell me, have you ever felt a rage so great that the whole of your being burns? A heat that wilts the living? A heat that incinerates the blood in your veins? That is what I felt.$B$B<Saurfang's eyes glow red for a brief moment.>$B$BI was the last one left alive. 30 of them surrounded me... Murkbloods... I remember nothing beyond that vision. I blacked out and awoke some time later." },
        ["text"] = "Вони загинули. Усі...$B$BКоли Бруднокрові прорубувалися крізь нас, мною заволоділо щось, чого я не можу зрозуміти. Скажи, ти коли-небудь відчував таку лють, що все твоє єство палає? Жар, від якого в'яне все живе? Жар, що випаровує кров у жилах? Саме це я відчув.$B$B<Очі Саурфанґа на мить спалахують червоним.>$B$BЯ лишився останнім живим. Тридцять із них оточили мене... Бруднокрові... Далі пам'ятаю лише те видіння. Я знепритомнів і прокинувся через якийсь час.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [648190190] = {
        ["english"] = { [1] = "The trick to using evasion is realizing that the best fifteen seconds of your life are often the last." },
        ["text"] = "Секрет «Ухилення» в тому, щоб зрозуміти: найкращі п'ятнадцять секунд твого життя часто бувають останніми.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1564859283] = {
        ["english"] = { [1] = "Step right up and hear about the most amazing spectacle in all of Azeroth - the Darkmoon Faire!  Huzzah!" },
        ["text"] = "Підходьте ближче й послухайте про найдивовижніше видовище в усьому Азероті — ярмарок Темного Місяця! Ура!",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["greeting"] = true },
    },
}
for key, row in pairs(rows) do addonTable.gossip_hashed.rows[key] = row end
